_ttk_treeview_init = ttk.Treeview.__init__
_ttk_treeview_insert = ttk.Treeview.insert


def _excel_tree_init(self, *args, **kwargs):
    _ttk_treeview_init(self, *args, **kwargs)
    self.tag_configure("_excel_even", background="#ffffff", foreground="#172b3a")
    self.tag_configure("_excel_odd", background="#d9e5f6", foreground="#172b3a")


def _excel_tree_insert(self, parent, index, iid=None, **kwargs):
    if not kwargs.get("tags"):
        stripe = "_excel_odd" if len(self.get_children(parent)) % 2 else "_excel_even"
        kwargs["tags"] = (stripe,)
    return _ttk_treeview_insert(self, parent, index, iid=iid, **kwargs)


ttk.Treeview.__init__ = _excel_tree_init
ttk.Treeview.insert = _excel_tree_insert
