# V165 — référence unique des boutons HBZ : couleur métier, icône à gauche,
# contour discret, typographie compacte et survol cohérent. Les petits boutons
# techniques (calendrier, flèches, jours) gardent volontairement leur gabarit.
_NativeTkButton = tk.Button


class HBZButton(_NativeTkButton):
    _icon_rules = (
        ("NOUVEAU", "＋"), ("NOUVELLE", "＋"), ("AJOUT", "＋"),
        ("ENREGISTR", "▣"), ("MODIFIER", "✎"), ("SUPPRIM", "🗑"),
        ("IMPRIM", "🖨"), ("APERÇU", "◉"), ("PDF", "▤"),
        ("EXPORT", "⇧"), ("IMPORT", "⇩"), ("ACTUALIS", "↻"),
        ("RECHERCH", "⌕"), ("FILT", "⌕"), ("EFFAC", "⌫"),
        ("CONFIRM", "✓"), ("VALID", "✓"), ("FERMER", "✕"),
        ("ANNUL", "✕"), ("PHOTO", "▣"), ("SCAN", "▣"),
        ("CHOISIR", "✓"), ("SYNCHRON", "⇄"), ("RÈGL", "▤"),
        ("PAI", "▤"), ("HISTOR", "▤"), ("ALERTE", "!"),
    )
    _color_rules = (
        ("SUPPRIM", "#e84b4f"), ("ANNUL", "#e84b4f"),
        ("NOUVE", "#249447"), ("AJOUT", "#249447"),
        ("ENREGISTR", "#168bd0"), ("MODIFIER", "#f2a20b"),
        ("IMPRIM", "#6653c7"), ("APERÇU", "#1689a7"),
        ("PDF", "#1689a7"), ("EXPORT", "#179a74"),
        ("IMPORT", "#405b73"), ("FERMER", "#647789"),
    )

    @staticmethod
    def _hover_color(value):
        if not isinstance(value, str) or not re.fullmatch(r"#[0-9A-Fa-f]{6}", value):
            return value
        rgb=[int(value[i:i+2],16) for i in (1,3,5)]
        return "#"+"".join(f"{max(0,int(channel*0.82)):02x}" for channel in rgb)

    def __init__(self, master=None, cnf=None, **kwargs):
        options=dict(cnf or {});options.update(kwargs)
        text=str(options.get("text","") or "");clean=text.strip();compact=(not clean or len(clean)<=3 or clean.isdigit())
        has_image=bool(options.get("image"));anchor=str(options.get("anchor","")).lower()
        if clean and not compact and not has_image and anchor!="w" and clean[0].isalnum():
            upper=clean.upper()
            for keyword,icon in self._icon_rules:
                if keyword in upper:
                    options["text"]=f"{icon}  {clean}";break
        upper=str(options.get("text",text)).upper()
        if "bg" not in options and "background" not in options and not compact:
            options["bg"]="#168bd0"
            for keyword,color in self._color_rules:
                if keyword in upper:options["bg"]=color;break
        options.setdefault("relief","flat");options.setdefault("bd",0);options.setdefault("highlightthickness",0)
        options.setdefault("cursor","hand2");options.setdefault("overrelief","flat")
        if not compact:
            options.setdefault("font",("Segoe UI",9,"bold"));options.setdefault("padx",13);options.setdefault("pady",7)
        bg=options.get("bg",options.get("background"))
        if bg:options.setdefault("activebackground",self._hover_color(bg))
        if options.get("fg",options.get("foreground"))=="white":options.setdefault("activeforeground","white")
        super().__init__(master, **options)


tk.Button = HBZButton


class GestionProApp(LocationFormsReferenceMixin, FinancialCenterMixin, DashboardReferenceMixin, SupplierReferenceMixin, ChecksReferenceMixin, FleetManagementMixin, ReservationReferenceMixin):
    def __init__(self, root: tk.Tk):
        self.root = root
        from remote_signature_client import monitor
        monitor()
        self.contract_output_model = "Modèle 1 — HBZ élégant"
        self.root.title(f"GestionPro — HBZ Rent Car — {BUILD_ID}")
        self.root.geometry("1536x864")
        self.root.minsize(1180, 700)
        self.root.configure(bg=BG)
        try:
            self.root.state("zoomed")
        except tk.TclError:
            pass

        self.conn = sqlite3.connect(DB_PATH)
        self.conn.row_factory = sqlite3.Row
        self._create_database()
        from mobile_sync import start as start_mobile_sync
        start_mobile_sync(APP_DIR,self)
        from contract_revisions import install as install_contract_revisions
        install_contract_revisions(self.conn)
        self.recurring_charges=RecurringCharges(self.conn)
        self._sync_recurring_charges()
        self._apply_saved_appearance()
        self.root.configure(bg=BG)
        self._automatic_backup()
        self.vars = {name: tk.StringVar() for name in (
            "contract_no client_code cin last_name first_name phone city address license_no birth_date age license_date license_age "
            "second_search second_code second_cin second_last second_first second_license second_phone second_birth_date second_age second_license_date second_license_age "
            "vehicle_code vehicle_model vehicle_name plate chassis invoice_no vehicle_initial_state km_start km_return km_used "
            "date_start time_start date_end time_end duration daily_price paid total balance fuel_level"
        ).split()}
        self.status_var = tk.StringVar(value="● Sélectionnez un véhicule et les dates")
        self.web_sync_var = tk.StringVar(value="Site Web : prêt à synchroniser")
        self._web_sync_running = False
        self._web_sync_after_id = None
        self._build_styles()
        self._build_shell()
        self.new_contract()
        self._load_search_values()
        # La connexion professionnelle est affichée après le premier rendu,
        # afin que le tableau de bord soit déjà construit derrière la fenêtre.
        account_count=self.conn.execute("SELECT COUNT(*) FROM users WHERE active=1 AND role IN ('ADMINISTRATEUR','UTILISATEUR')").fetchone()[0]
        self._authenticated=not bool(account_count)
        self.current_user="Accès libre" if not account_count else ""
        self.current_username="__FREE_ACCESS__" if not account_count else ""
        self.current_role="ADMINISTRATEUR" if not account_count else ""
        if account_count:
            self.root.after(150, self.show_login)
        # Les alertes ne doivent pas retarder l'affichage de l'accueil.
         # Synchronisation HBZ Crédit : chaque échéance est débitée de Banque à J-3,
        # recalculée si les échéances HBZ sont modifiées.
        self.root.after(1200, self._sync_hbz_credit_monthly_bank)
        self.root.after(60000, self._recurring_charges_clock)
        # L'écran d'alerte s'ouvre dès que l'accueil est rendu et l'accès autorisé.
        if self._authenticated:self.root.after(300, self._show_startup_alerts)
        self.root.protocol("WM_DELETE_WINDOW", self.close)

    def _apply_saved_appearance(self):
        """Charge le thème sauvegardé avant de construire les formulaires."""
        global NAVY, BLUE, BG, CARD, TEXT, MUTED, BORDER
        theme=self._get_setting("theme","HBZ Bleu")
        ui_style=self._get_setting("ui_style","HBZ Moderne Pro 2D")
        # Migration des anciennes copies : le style moderne devient effectivement
        # le style actif au prochain démarrage, au lieu de rester un simple choix
        # enregistré sans effet visuel.
        if ui_style == "Ancien style HBZ":
            ui_style = "HBZ Moderne Pro 2D"
            self._set_setting("ui_style", ui_style)
            self.conn.commit()
        # Le style d’application est maintenant réellement pris en compte.
        # Moderne Pro 2D est le style par défaut : plat, clair, arrondi et sans 3D.
        if ui_style in ("HBZ Moderne Pro 2D", "HBZ Premium Moderne") and theme=="Sombre":
            NAVY,BLUE,BG,CARD,TEXT,MUTED,BORDER="#082f49","#0284c7","#111827","#1f2937","#f8fafc","#cbd5e1","#475569"
        elif ui_style in ("HBZ Moderne Pro 2D", "HBZ Premium Moderne") and theme=="Clair":
            NAVY,BLUE,BG,CARD,TEXT,MUTED,BORDER="#155e75","#0891b2","#f8fafc","#ffffff","#172554","#64748b","#cbd5e1"
        elif ui_style in ("HBZ Moderne Pro 2D", "HBZ Premium Moderne"):
            NAVY,BLUE,BG,CARD,TEXT,MUTED,BORDER="#173b5f","#2d8bb8","#f4f8fb","#ffffff","#172b3d","#607589","#d7e5ed"
        elif theme=="Sombre":
            NAVY,BLUE,BG,CARD,TEXT,MUTED,BORDER="#082f49","#0284c7","#111827","#1f2937","#f8fafc","#cbd5e1","#475569"
        elif theme=="Clair":
            NAVY,BLUE,BG,CARD,TEXT,MUTED,BORDER="#155e75","#0891b2","#f8fafc","#ffffff","#172554","#64748b","#cbd5e1"
        else:
            NAVY,BLUE,BG,CARD,TEXT,MUTED,BORDER="#0e5a91","#168bd0","#f4f8fb","#ffffff","#20364a","#748391","#bfd0dc"
        saved_font_color=self._get_setting("font_color","Bleu nuit")
        color={"Bleu nuit":"#20364a","Noir":"#111111","Gris":"#52677a","Blanc":"#ffffff"}.get(saved_font_color,TEXT)
        if theme=="Sombre" and saved_font_color=="Bleu nuit": color=TEXT
        # Sécurité lisibilité : le blanc ne doit jamais rendre les libellés invisibles sur un thème clair.
        if theme != "Sombre" and saved_font_color == "Blanc": color="#20364a"
        TEXT=color
        size={"Petite":8,"Normale":9,"Grande":11}.get(self._get_setting("font_size","Normale"),9)
        weight="bold" if self._get_setting("font_weight","Normal")=="Gras" else "normal"
        for name in ("TkDefaultFont","TkTextFont","TkMenuFont","TkHeadingFont","TkCaptionFont"):
            try: tkfont.nametofont(name).configure(family="Segoe UI",size=size,weight=weight)
            except (tk.TclError, RuntimeError): pass

    def _create_database(self):
        self.conn.executescript("""
        CREATE TABLE IF NOT EXISTS clients(
            code TEXT PRIMARY KEY, cin TEXT, nom TEXT, prenom TEXT,
            telephone TEXT, ville TEXT, adresse TEXT, permis TEXT
        );
        CREATE TABLE IF NOT EXISTS vehicles(
            code TEXT PRIMARY KEY, modele TEXT, immatriculation TEXT UNIQUE,
            chassis TEXT, compteur INTEGER DEFAULT 0, prix REAL DEFAULT 0,
            service INTEGER DEFAULT 1, photo TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS contracts(
            numero TEXT PRIMARY KEY, client_code TEXT, second_code TEXT,
            vehicle_code TEXT, date_depart TEXT, heure_depart TEXT,
            date_retour TEXT, heure_retour TEXT, duree INTEGER,
            prix REAL, montant REAL, reglement REAL, reste REAL,
            km_depart INTEGER, km_retour INTEGER, created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS contract_vehicle_states(
            contract_no TEXT PRIMARY KEY,
            payload TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS module_records(
            module TEXT NOT NULL, record_id TEXT NOT NULL,
            payload TEXT NOT NULL, created_at TEXT NOT NULL,
            PRIMARY KEY(module, record_id)
        );
        CREATE TABLE IF NOT EXISTS audit_log(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            action TEXT NOT NULL, module TEXT NOT NULL,
            reference TEXT, details TEXT, created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS app_settings(
            setting_key TEXT PRIMARY KEY, setting_value TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS users(
            username TEXT PRIMARY KEY, display_name TEXT NOT NULL,
            password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'UTILISATEUR',
            active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS user_permissions(
            username TEXT NOT NULL, permission TEXT NOT NULL, allowed INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(username, permission), FOREIGN KEY(username) REFERENCES users(username) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS client_documents(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            client_code TEXT NOT NULL, document_type TEXT NOT NULL,
            file_path TEXT NOT NULL, created_at TEXT NOT NULL
        );
        """)
        existing = {r[1] for r in self.conn.execute("PRAGMA table_info(clients)")}
        for column, sql_type in (
            ("date_naissance", "TEXT"), ("date_permis", "TEXT"),
            ("lieu_permis", "TEXT"), ("categorie", "TEXT"),
            ("validite_permis", "TEXT"), ("sexe", "TEXT"),
            ("profession", "TEXT"), ("email", "TEXT"),
            ("observations", "TEXT"), ("photo", "TEXT"),
            ("date_enregistrement", "TEXT")
        ):
            if column not in existing:
                self.conn.execute(f"ALTER TABLE clients ADD COLUMN {column} {sql_type} DEFAULT ''")
        contract_columns = {r[1] for r in self.conn.execute("PRAGMA table_info(contracts)")}
        for column in ("return_status", "actual_return_date", "actual_return_time"):
            if column not in contract_columns:
                self.conn.execute(f"ALTER TABLE contracts ADD COLUMN {column} TEXT DEFAULT ''")
        vehicle_columns = {r[1] for r in self.conn.execute("PRAGMA table_info(vehicles)")}
        for column, sql_type in (
            ("assurance_fin", "TEXT DEFAULT ''"), ("controle_technique", "TEXT DEFAULT ''"),
            ("mise_circulation", "TEXT DEFAULT ''"), ("fin_service", "TEXT DEFAULT ''"),
            ("adblue_restant", "INTEGER DEFAULT 0"), ("prochaine_vidange", "INTEGER DEFAULT 0"),
            ("prochaine_chaine", "INTEGER DEFAULT 0"), ("remarque", "TEXT DEFAULT ''"),
            ("age_mois", "INTEGER DEFAULT 0"), ("reste_service_mois", "INTEGER DEFAULT 60"),
            ("entretien_date", "TEXT DEFAULT ''"), ("entretien_type", "TEXT DEFAULT ''"),
            ("entretien_km_intervention", "INTEGER DEFAULT 0"),
            ("entretien_km_produit", "INTEGER DEFAULT 0"),
            ("entretien_prochaine", "INTEGER DEFAULT 0"),
            ("entretien_km_restant", "INTEGER DEFAULT 0"),
            ("prochaine_adblue", "INTEGER DEFAULT 0"),
            ("vidange_restant", "INTEGER DEFAULT 0"),
            ("chaine_restant", "INTEGER DEFAULT 0"),
            ("fuel_eighths", "INTEGER DEFAULT 4")
        ):
            if column not in vehicle_columns:
                self.conn.execute(f"ALTER TABLE vehicles ADD COLUMN {column} {sql_type}")
        if not self.conn.execute("SELECT 1 FROM clients LIMIT 1").fetchone():
            self.conn.executemany(
                "INSERT INTO clients(code,cin,nom,prenom,telephone,ville,adresse,permis) VALUES(?,?,?,?,?,?,?,?)", [
                ("2170", "LB174163", "BENJMAL", "ABDERRAHIM", "067665608", "KSAR EL KEBIR", "HAY SALAM GR A RUE", "74/01891"),
                ("1819", "GN126931", "SAKOUK", "ABDELHADI", "0611223344", "TANGER", "AVENUE MOHAMMED VI", "B123456"),
            ])
        if not self.conn.execute("SELECT 1 FROM vehicles LIMIT 1").fetchone():
            self.conn.executemany("INSERT INTO vehicles(code,modele,immatriculation,chassis,compteur,prix,service,photo) VALUES(?,?,?,?,?,?,?,?)", [
                ("000005", "PEUGEOT NEW 208 GRF", "56034-A-42", "VR3UBYHT6RS131229", 92110, 300, 1, ""),
                ("000003", "DACIA LOGAN BA2", "53102-A-42", "UU14SDAW457670514", 265600, 250, 1, ""),
            ])
        self.conn.commit()

    def _automatic_backup(self):
        """Conserve une sauvegarde quotidienne récupérable de la base locale."""
        BACKUP_DIR.mkdir(exist_ok=True)
        destination = BACKUP_DIR / f"gestionpro_{datetime.now():%Y%m%d}.db"
        if not destination.exists():
            backup = sqlite3.connect(destination)
            try:
                self.conn.backup(backup)
            finally:
                backup.close()

    def _audit(self, action, module, reference="", details=""):
        self.conn.execute(
            "INSERT INTO audit_log(action,module,reference,details,created_at) VALUES(?,?,?,?,?)",
            (action, module, reference, details, datetime.now().isoformat(timespec="seconds"))
        )

    def _build_styles(self):
        style = ttk.Style()
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass
        # Fond 9-tranches : coins réellement transparents et bord arrondi sur tous
        # les champs Entry, sans dépendance graphique externe.
        self._rounded_entry_normal = self._rounded_field_image("#f8fbfd", "#9db7c8")
        self._rounded_entry_focus = self._rounded_field_image("#ffffff", BLUE)
        self._rounded_entry_yellow = self._rounded_field_image("#169447", "#0d6f34")
        try:
            style.element_create("GestionPro.Rounded.field", "image", self._rounded_entry_normal,
                                 ("focus", self._rounded_entry_focus), border=9, sticky="nsew")
            rounded_layout = [("GestionPro.Rounded.field", {"sticky": "nsew", "children": [
                ("Entry.padding", {"sticky": "nsew", "children": [("Entry.textarea", {"sticky": "nsew"})]})
            ]})]
            style.layout("GP.TEntry", rounded_layout)
            style.layout("Contract.TEntry", rounded_layout)
            style.element_create("GestionPro.YellowRounded.field", "image", self._rounded_entry_yellow,
                                 border=9, sticky="nsew")
            style.layout("ClientCode.TEntry", [("GestionPro.YellowRounded.field", {"sticky": "nsew", "children": [
                ("Entry.padding", {"sticky": "nsew", "children": [("Entry.textarea", {"sticky": "nsew"})]})
            ]})])
        except tk.TclError:
            # Le style clam conserve alors la bordure colorée configurée ci-dessous.
            pass
