        style.configure("Vehicle2D.Treeview.Heading", background="#4472c4", foreground="#ffffff", relief="flat",
                        borderwidth=1, font=("Segoe UI", 9, "bold"), padding=(7, 8))
        style.map("Vehicle2D.Treeview", background=[("selected", "#bfe4f7")], foreground=[("selected", "#17324d")])
