    def _rounded_field_image(self, fill, border, size=24, radius=8):
        image = tk.PhotoImage(master=self.root, width=size, height=size)
        image.put(fill, to=(0, 0, size, size))
        for y in range(size):
            for x in range(size):
                dx = max(radius - x, 0, x - (size - radius - 1))
                dy = max(radius - y, 0, y - (size - radius - 1))
                if dx and dy and dx * dx + dy * dy > radius * radius:
                    image.transparency_set(x, y, True)
                elif x < 1 or y < 1 or x >= size - 1 or y >= size - 1 or (
                    dx and dy and dx * dx + dy * dy > (radius - 2) * (radius - 2)
                ):
                    image.put(border, (x, y))
        return image

    def _build_reference_banner(self):
        """La maquette épurée affiche son en-tête dans le tableau de bord."""
        self.dashboard_today_return_items=[]
        self.dashboard_return_ticker_index=0
        self.dashboard_return_scroll=0
        self.dashboard_return_photo_cache={}
        self._update_banner_return_ticker=lambda:None

    def _global_reference_search(self,_event=None):
        term=self.global_search_var.get().strip()
        if not term or term.startswith("Recherche rapide"):return
        query=f"%{term}%";results=[]
        try:
            for r in self.conn.execute("SELECT code,nom,prenom FROM clients WHERE code LIKE ? OR nom LIKE ? OR prenom LIKE ? OR cin LIKE ? LIMIT 8",(query,)*4):
                results.append(("Client",str(r[0]),f"{r[1] or ''} {r[2] or ''}","clients"))
            for r in self.conn.execute("SELECT code,modele,immatriculation FROM vehicles WHERE code LIKE ? OR modele LIKE ? OR immatriculation LIKE ? LIMIT 8",(query,)*3):
                results.append(("Véhicule",str(r[0]),f"{r[1] or ''} · {r[2] or ''}","vehicles"))
            for r in self.conn.execute("SELECT numero,client_code,vehicle_code FROM contracts WHERE numero LIKE ? OR client_code LIKE ? OR vehicle_code LIKE ? ORDER BY created_at DESC LIMIT 8",(query,)*3):
                results.append(("Contrat",str(r[0]),f"Client {r[1] or '—'} · Véhicule {r[2] or '—'}","contract"))
        except sqlite3.Error:return
        win=self._secondary_window(self.root);win.title(f"Recherche — {term}");win.geometry("710x410")
        head=tk.Frame(win,bg="#eaf4ff");head.pack(fill="x")
        tk.Label(head,text=f"Résultats pour « {term} »",bg="#eaf4ff",fg="#0c3d9b",
             font=("Segoe UI",13,"bold")).pack(anchor="w",padx=15,pady=11)
        tree=ttk.Treeview(win,columns=("type","code","detail"),show="headings")
        for key,title,width in (("type","Type",110),("code","Référence",120),("detail","Détails",410)):
            tree.heading(key,text=title);tree.column(key,width=width,anchor="w")
        tree.pack(fill="both",expand=True,padx=12,pady=(8,12))
        for index,(kind,code,detail,page) in enumerate(results):tree.insert("","end",iid=str(index),values=(kind,code,detail))
        if not results:tree.insert("","end",values=("—","—","Aucun résultat"))
        def open_selected(_e=None):
            chosen=tree.selection()
            if chosen and chosen[0].isdigit() and int(chosen[0])<len(results):
                page=results[int(chosen[0])][3];win.destroy();self.show_page(page)
        tree.bind("<Double-1>",open_selected)

