    def _build_deferred_pages(self, module_definitions):
        """Construit les écrans secondaires progressivement après l'accueil."""
        if getattr(self, "_deferred_pages_started", False):
            return
        self._deferred_pages_started = True
        self._deferred_queue = [
            ("clients", self._build_embedded_clients_page),
            ("vehicles", self._build_vehicles_page),
            ("fleet_management", self._build_fleet_management_page),
            ("parking_deposits", self._build_parking_deposits_page),
            ("financial_center", self._build_financial_center),
        ]
        self._deferred_queue.extend(
            (key, lambda key=key, title=title, fields=fields: self._build_business_page(key, title, fields))
            for key, (title, fields) in module_definitions.items()
        )
        self._deferred_queue.extend((
            ("add_charge", self._build_add_charge_page),
            ("receivables", self._build_receivables_page),
            ("alerts", self._build_alerts_page),
            ("history", self._build_history_page),
            ("vehicle_analysis", self._build_vehicle_analysis_page),
            ("settings", self._build_settings_page),
        ))
        self._deferred_builders = dict(self._deferred_queue)
        self._build_next_deferred_page()

    def _build_next_deferred_page(self):
        """Construit une seule page par cycle pour garder Tkinter réactif."""
        if not getattr(self, "_deferred_queue", None):
            self._remove_legacy_frame_borders()
            return
        _name, builder = self._deferred_queue.pop(0)
        try:
            builder()
            self._remove_legacy_frame_borders()
            # Une page créée en arrière-plan ne doit jamais recouvrir la page
            # actuellement affichée (notamment le tableau de bord au démarrage).
            current=self.pages.get(getattr(self,"current_page_name","dashboard"))
            if current is not None:current.tkraise()
        except Exception:
            # Conserver une trace exploitable au lieu de laisser un écran blanc.
            self._log_page_error(_name)
            partial = self.pages.pop(_name, None)
            if partial is not None:
                try: partial.destroy()
                except tk.TclError: pass
        if self._deferred_queue:
            self.root.after(35, self._build_next_deferred_page)

    def _remove_legacy_frame_borders(self, parent=None):
        """Nettoie seulement les anciennes bordures, après construction complète."""
        parent = parent or self.root
        try: children = parent.winfo_children()
        except tk.TclError: return
        for child in children:
            if isinstance(child, tk.Frame):
                try:
                    if int(child.cget("highlightthickness")) > 0:
                        child.configure(highlightthickness=1,highlightbackground="#c7d9e5",relief="flat",bd=0)
                except (tk.TclError, ValueError):
                    pass
            self._remove_legacy_frame_borders(child)

    def _log_page_error(self, page_name):
        try:
            with (APP_DIR / "ERREUR_PAGES.txt").open("a", encoding="utf-8") as handle:
                handle.write(f"\n{datetime.now().isoformat(timespec='seconds')} — {page_name}\n")
                traceback.print_exc(file=handle)
        except OSError:
            pass

    @staticmethod
    def _is_descendant(widget, ancestor):
        current = widget
        while current is not None:
            if current is ancestor:
                return True
            try:
                current = current.master
            except Exception:
                return False
        return False

    def _build_parking_deposits_page(self):
        from depot_parc.parking_app import ParkingApp
        page=self._new_page('parking_deposits')
