    def show_page(self, name):
        if name == "locations":
            self._open_location_tabs()
            return
        # Le tableau de bord reste accessible, mais chaque module métier est
        # contrôlé à l'ouverture en plus de l'état visuel du bouton latéral.
        if name != "dashboard" and getattr(self,"_authenticated",False):
            permission=self._page_permission(name)
            if permission and not self._require_permission(permission):
                return
        if name == 'contract':
            number=self.vars['contract_no'].get().strip() if hasattr(self,'vars') else ''
            if not self.conn.execute('SELECT 1 FROM contracts WHERE numero=?',(number,)).fetchone():number=''
            return self.open_location_form(contract_number=number)
        page = self.pages.get(name)
        if page is None:
            # Si l'utilisateur ouvre rapidement un module encore en attente,
            # construire uniquement celui-ci plutôt que toute la pile.
            queue = getattr(self, "_deferred_queue", [])
            for index, (queued_name, builder) in enumerate(queue):
                if queued_name == name:
                    queue.pop(index)
                    try:
                        builder()
                        self._remove_legacy_frame_borders()
                        page = self.pages.get(name)
                    except Exception:
                        self._log_page_error(name)
                        partial=self.pages.pop(name,None)
                        if partial is not None:
                            try:partial.destroy()
                            except tk.TclError:pass
                    break
        if page is None:
            # Deuxième tentative sûre pour une page dont la construction différée
            # avait échoué. Le formulaire n'est ainsi jamais remplacé par du blanc.
            builder=getattr(self,"_deferred_builders",{}).get(name)
            if builder is not None:
                try:
                    builder(); self._remove_legacy_frame_borders(); page=self.pages.get(name)
                except Exception:
                    self._log_page_error(name)
                    partial=self.pages.pop(name,None)
                    if partial is not None:
                        try:partial.destroy()
                        except tk.TclError:pass
                    messagebox.showerror("Chargement du formulaire",
                        f"Le formulaire {name} n'a pas pu être chargé.\n\nLe diagnostic est enregistré dans :\n{APP_DIR / 'ERREUR_PAGES.txt'}")
        if page is None:
            return
        self.current_page_name=name
        if hasattr(self,"sidebar") and not self.sidebar.winfo_manager():
            self.sidebar.pack(side="left",fill="y",before=self.canvas.master)
        page.tkraise()
        if name in ("clients","location_integrated","financial_center","checks","receivables"):
            self.canvas.itemconfigure(self.page_window,height=max(1,self.canvas.winfo_height()))
        else:
            self.canvas.itemconfigure(self.page_window,height=0)
        if name=="contract" and hasattr(self,"contract_tabs"):
            self._select_contract_tab(0)
        self.canvas.yview_moveto(0)
        if name=="dashboard" and hasattr(self,"dashboard_scroll_canvas"):
            self.dashboard_scroll_canvas.yview_moveto(0)
        if name=="locations" and hasattr(self,"locations_tree"):
            self.refresh_locations_reference()
        # Aucun style 2D global : le style 2D sélectionné reste inchangé.
        if name == "receivables" and hasattr(self, "receivables_tree"):
            self.refresh_receivables()
        if name == "vehicles" and hasattr(self,"vehicle_notebook"):
            self.vehicle_notebook.select(0)
        if name == "fleet_management" and hasattr(self,"fleet_list_host"):
            self.refresh_fleet_management()
        if name == "parking_deposits" and hasattr(self,"parking_deposits_app"):
            self.parking_deposits_app._load_vehicles()
            self.parking_deposits_app.refresh()
        if name == "reservations" and hasattr(self,"reservation_reference_table"):
            self._refresh_reservation_reference()
        if name == "expenses" and "expenses" in getattr(self,"module_trees",{}):
            self._expense_reference_select("SYNTHESE")
        if name == "financial_center" and hasattr(self,"financial_center_month"):
            self._refresh_financial_center()
        for key, controls in self.nav_buttons.items():
            active = key == name
            for row, button in controls:
                row.configure(bg="#0b8df1" if active else "#102f59")
                if key in getattr(self,"nav_icons",{}):self.nav_icons[key].configure(bg="#0b8df1" if active else "#102f59")
                button.configure(bg="#0b8df1" if active else "#102f59",
                                 font=("Segoe UI", 9, "bold" if active else "normal"))

    def open_public_website(self):
        """Ouvre le site public configuré, sans exposer le jeton API."""
        if getattr(self,"_authenticated",False) and not self._require_permission("Site Web"):
            return
        config_path = APP_DIR / "sync_web_config.json"
        try:
            config = json.loads(config_path.read_text(encoding="utf-8"))
            url = str(config.get("base_url", "")).strip().rstrip("/")
        except (OSError, json.JSONDecodeError):
            url = ""
        if not re.match(r"^https?://[^\s]+$", url, re.IGNORECASE):
            messagebox.showwarning(
                "Site Web",
                "L’adresse du site n’est pas configurée.\n"
                "Renseignez base_url dans sync_web_config.json."
            )
            return
        webbrowser.open(url)

    def _attach_date_picker(self, widget, variable):
        """Ajoute un bouton calendrier visible à droite d'un champ date."""
        if not hasattr(self, "_calendar_buttons"):
            self._calendar_buttons = []
        button = tk.Button(widget.master, text="\ue787", command=lambda: self.open_date_picker(variable, widget),
                           bg="#e7f3fb", fg=NAVY, activebackground="#cfe9f8",
                           activeforeground=NAVY, relief="flat", bd=0,
                           font=("Segoe MDL2 Assets", 11), cursor="hand2")
        button.place(in_=widget, relx=1.0, rely=0.5, x=-3, anchor="e", width=27, height=24)
        button.lift()
        widget.bind("<Double-Button-1>", lambda _e: self.open_date_picker(variable, widget), add="+")
        self._calendar_buttons.append(button)

    def open_date_picker(self, variable, anchor=None):
        """Calendrier français moderne, autonome et utilisable sans module externe."""
        selected = self._parse_french_date(variable.get()) or datetime.now()
        state = {"year": selected.year, "month": selected.month}
        popup = self._secondary_window(self.root)
        popup.title("Calendrier GestionPro")
        popup.configure(bg=BG)
        popup.resizable(False, False)
        popup.transient(self.root)
        popup.grab_set()

        titlebar = tk.Frame(popup, bg=NAVY)
        titlebar.pack(fill="x")
        tk.Label(titlebar, text="\ue787", bg=NAVY, fg="white",
                 font=("Segoe MDL2 Assets", 16)).pack(side="left", padx=(14, 7), pady=11)
        tk.Label(titlebar, text="CHOISIR UNE DATE", bg=NAVY, fg="white",
                 font=("Segoe UI", 13, "bold")).pack(side="left", pady=11)

        navigation = tk.Frame(popup, bg=CARD)
        navigation.pack(fill="x", padx=12, pady=(12, 0))
        month_var = tk.StringVar()
        months = ("janvier", "février", "mars", "avril", "mai", "juin",
                  "juillet", "août", "septembre", "octobre", "novembre", "décembre")
        days = tk.Frame(popup, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        days.pack(fill="both", expand=True, padx=12, pady=8)

        def move_month(delta):
            value = state["month"] - 1 + delta
            state["year"] += value // 12
            state["month"] = value % 12 + 1
            draw_month()

        tk.Button(navigation, text="\ue76b", command=lambda: move_month(-1), bg=CARD, fg=NAVY,
                  activebackground="#dcecf6", relief="flat", font=("Segoe MDL2 Assets", 12),
                  padx=12, pady=7, cursor="hand2").pack(side="left")
        tk.Label(navigation, textvariable=month_var, bg=CARD, fg=TEXT,
                 font=("Segoe UI", 12, "bold")).pack(side="left", fill="x", expand=True)
        tk.Button(navigation, text="\ue76c", command=lambda: move_month(1), bg=CARD, fg=NAVY,
                  activebackground="#dcecf6", relief="flat", font=("Segoe MDL2 Assets", 12),
                  padx=12, pady=7, cursor="hand2").pack(side="right")

        def choose(day):
            variable.set(f"{day:02d}/{state['month']:02d}/{state['year']:04d}")
            popup.destroy()

        def draw_month():
            month_var.set(f"{months[state['month'] - 1].capitalize()} {state['year']}")
            for child in days.winfo_children(): child.destroy()
            for col, label in enumerate(("Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim")):
                tk.Label(days, text=label, bg="#e8f3fa", fg=NAVY,
                         font=("Segoe UI", 8, "bold"), width=5, pady=7).grid(row=0, column=col, sticky="nsew")
                days.grid_columnconfigure(col, weight=1)
            today = datetime.now()
            current_value = self._parse_french_date(variable.get())
            for row_index, week in enumerate(monthcalendar.Calendar(firstweekday=0).monthdayscalendar(state["year"], state["month"]), 1):
                for col, day in enumerate(week):
                    if day == 0:
                        tk.Label(days, text="", bg=CARD).grid(row=row_index, column=col, sticky="nsew", padx=1, pady=1)
                        continue
                    is_today = (day, state["month"], state["year"]) == (today.day, today.month, today.year)
                    is_selected = bool(current_value and (day, state["month"], state["year"]) ==
                                       (current_value.day, current_value.month, current_value.year))
                    color = BLUE if is_selected else ("#dff3e7" if is_today else CARD)
                    foreground = "white" if is_selected else (GREEN if is_today else TEXT)
                    tk.Button(days, text=str(day), command=lambda value=day: choose(value),
                              bg=color, fg=foreground, activebackground=BLUE, activeforeground="white",
                              relief="flat", bd=0, width=5, pady=7,
                              font=("Segoe UI", 9, "bold" if is_today or is_selected else "normal"),
                              cursor="hand2").grid(row=row_index, column=col, sticky="nsew", padx=1, pady=1)

        draw_month()
        footer = tk.Frame(popup, bg=BG); footer.pack(fill="x", padx=12, pady=(0, 12))
        tk.Button(footer, text="Aujourd’hui", command=lambda: (variable.set(datetime.now().strftime("%d/%m/%Y")), popup.destroy()),
                  bg=GREEN, fg="white", relief="flat", padx=14, pady=7,
                  font=("Segoe UI", 9, "bold"), cursor="hand2").pack(side="left")
        tk.Button(footer, text="Effacer", command=lambda: (variable.set(""), popup.destroy()),
                  bg=ORANGE, fg="white", relief="flat", padx=14, pady=7,
                  font=("Segoe UI", 9, "bold"), cursor="hand2").pack(side="left", padx=6)
        tk.Button(footer, text="Fermer", command=popup.destroy, bg="#647789", fg="white",
                  relief="flat", padx=14, pady=7, font=("Segoe UI", 9, "bold"),
                  cursor="hand2").pack(side="right")
        popup.bind("<Escape>", lambda _e: popup.destroy())
        popup.update_idletasks()
        if anchor:
            x = min(anchor.winfo_rootx(), popup.winfo_screenwidth() - popup.winfo_reqwidth() - 15)
            y = min(anchor.winfo_rooty() + anchor.winfo_height() + 4,
                    popup.winfo_screenheight() - popup.winfo_reqheight() - 45)
            popup.geometry(f"+{max(0, x)}+{max(0, y)}")

    def _new_page(self, name):
        page = tk.Frame(self.surface, bg=BG)
        page.grid(row=0, column=0, sticky="nsew")
        self.pages[name] = page
        from table_transfers import install_page_transfers
        page.after_idle(lambda:install_page_transfers(self,page,name))
        return page

    def _secondary_window(self, parent=None):
        """Crée une fenêtre secondaire cohérente sans intervenir pendant son montage."""
        win=_tk_dialog_factory(parent or self.root)
        try:
            win.configure(bg=BG)
            win.bind("<Escape>",lambda _event,w=win:w.destroy(),add="+")
            logo=self._company_logo_path()
            if logo.exists():
                from PIL import Image,ImageTk
                icon=Image.open(logo);icon.thumbnail((64,64),Image.LANCZOS)
                win._hbz_window_icon=ImageTk.PhotoImage(icon)
                win.iconphoto(False,win._hbz_window_icon)
            win.after_idle(lambda w=win:self._finalize_secondary_window(w))
        except tk.TclError:
            pass
        return win

    def _finalize_secondary_window(self, win):
        """Finalisation visuelle non intrusive après création complète du formulaire."""
        try:
            if not win.winfo_exists():return
            win.configure(bg=BG)
            win.update_idletasks()
            width=max(win.winfo_width(),win.winfo_reqwidth())
            height=max(win.winfo_height(),win.winfo_reqheight())
            x=max(0,min(win.winfo_x(),win.winfo_screenwidth()-width))
            y=max(0,min(win.winfo_y(),win.winfo_screenheight()-height-35))
            win.geometry(f"+{x}+{y}")
        except tk.TclError:
            pass

