    def _build_contract_summary(self):
        """Synthèse compacte identique aux formes Créances et Factures."""
        host=tk.Frame(self.page,bg=BG);host.pack(fill="x",padx=12,pady=(0,4))
        self.contract_metric_vars={key:tk.StringVar(value="0,00 MAD") for key in ("month_ca","client_ca","vehicle_ca","count","balance")}
        definitions=(("▤","CA du mois en cours","month_ca","#e5f2ff",BLUE),("👤","CA du client sélectionné","client_ca","#e7f7ed",GREEN),
                     ("🚗","CA global du véhicule","vehicle_ca","#eeeafb",PURPLE),("●","Nombre de contrats","count","#e8f6ed","#14753d"),
                     ("!","Reste global","balance","#fff1dc",ORANGE))
        for col,(icon,title,key,bg,fg) in enumerate(definitions):
            host.grid_columnconfigure(col,weight=1,uniform="contract_metrics")
            card=tk.Frame(host,bg=bg,highlightbackground=fg,highlightthickness=1);card.grid(row=0,column=col,sticky="nsew",padx=(0 if col==0 else 5,0))
            tk.Label(card,text=icon,bg=bg,fg=fg,font=("Segoe UI Symbol",17,"bold"),width=3).pack(side="left",padx=(7,1),pady=5)
            info=tk.Frame(card,bg=bg);info.pack(side="left",fill="both",expand=True,pady=5)
            tk.Label(info,text=title,bg=bg,fg=TEXT,font=("Segoe UI",7,"bold"),anchor="w").pack(fill="x")
            tk.Label(info,textvariable=self.contract_metric_vars[key],bg=bg,fg=fg,font=("Segoe UI",11,"bold"),anchor="w").pack(fill="x")
        self.vars["client_code"].trace_add("write",lambda *_:self._refresh_contract_summary())
        self.vars["vehicle_code"].trace_add("write",lambda *_:self._refresh_contract_summary())

    def _refresh_contract_summary(self, rows=None):
        if not hasattr(self,"contract_metric_vars"):return
        rows=rows if rows is not None else self.conn.execute("SELECT client_code,vehicle_code,date_depart,montant,reste FROM contracts").fetchall()
        now=datetime.now();client=self.vars["client_code"].get().split("|",1)[0].strip();vehicle=self.vars["vehicle_code"].get().split("|",1)[0].strip()
        month_ca=client_ca=vehicle_ca=balance=0.0
        for record in rows:
            amount=float(record["montant"] or 0);balance+=float(record["reste"] or 0)
            date=self._parse_french_date(record["date_depart"] or "")
            if date and date.month==now.month and date.year==now.year:month_ca+=amount
            if client and str(record["client_code"] or "")==client:client_ca+=amount
            if vehicle and str(record["vehicle_code"] or "")==vehicle:vehicle_ca+=amount
        self.contract_metric_vars["month_ca"].set(f"{month_ca:,.2f} MAD")
        self.contract_metric_vars["client_ca"].set(f"{client_ca:,.2f} MAD" if client else "Sélectionnez un client")
        self.contract_metric_vars["vehicle_ca"].set(f"{vehicle_ca:,.2f} MAD" if vehicle else "Sélectionnez un véhicule")
        self.contract_metric_vars["count"].set(str(len(rows)))
        self.contract_metric_vars["balance"].set(f"{balance:,.2f} MAD")

