    def _refresh_second_driver_stamp(self):
        """Affiche le cachet rouge uniquement lorsqu'aucun 2e conducteur n'est renseigné."""
        if not hasattr(self,"second_no_driver_stamp"):
            return
        has_second=bool(str(self.vars.get("second_code").get() if self.vars.get("second_code") else "").strip() or str(self.vars.get("second_last").get() if self.vars.get("second_last") else "").strip())
        show=(not has_second) or (hasattr(self,"second_disabled") and bool(self.second_disabled.get()))
        if not show:
            self.second_no_driver_stamp.grid_remove(); return
        self.second_no_driver_stamp.grid()
        asset=APP_DIR/"assets"/"HBZ_DEUXIEME_CONDUCTEUR_NON_AUTORISE_BLEU.png"
        self.second_no_driver_stamp_image=None
        try:
            from PIL import Image,ImageTk
            im=Image.open(asset); im.thumbnail((125,125))
            self.second_no_driver_stamp_image=ImageTk.PhotoImage(im)
            self.second_no_driver_stamp.configure(image=self.second_no_driver_stamp_image,text="")
        except Exception:
            self.second_no_driver_stamp.configure(image="",text="⛔  DEUXIÈME CONDUCTEUR — NON AUTORISÉ",fg="#175cd3",font=("Segoe UI",10,"bold"))

    def _refresh_contract_fuel_bars(self):
        """V102 — colore les segments de la jauge selon le niveau choisi."""
        if not hasattr(self,"contract_fuel_bars"): return
        level=(self.vars.get("fuel_level").get() if self.vars.get("fuel_level") else "½") or "½"
        count={"E":1,"⅛":2,"¼":2,"⅜":3,"½":4,"⅝":5,"¾":6,"Plein":8,"F":8}.get(level,4)
        # V104 — 8 portions : 1 rouge, 2 = rouge+orange, dès 3 toutes les portions actives vertes.
        for i,seg in enumerate(self.contract_fuel_bars):
            if i >= count: color="#d7e1e8"
            elif count == 1: color="#e53935"
            elif count == 2: color="#e53935" if i == 0 else "#f59e0b"
            else: color="#9ACD32"  # vert pistache dès le niveau supérieur au 3e trait
            seg.configure(bg=color)

    def _refresh_contract_vehicle_alerts(self,row=None):
        """Affiche dans le contrat les échéances proches du véhicule choisi."""
        if not hasattr(self,"contract_vehicle_alert_var"):
            return
        code=self.vars["vehicle_code"].get().split("|",1)[0].strip()
        if row is None and code:
            row=self.conn.execute("""SELECT service,compteur,assurance_fin,controle_technique,fin_service,
                adblue_restant,prochaine_vidange,prochaine_chaine FROM vehicles WHERE code=?""",(code,)).fetchone()

        def apply_style(soft,color,icon):
            self.contract_vehicle_alert_box.configure(bg=soft,highlightbackground=color)
            self.contract_vehicle_alert_icon.configure(text=icon,bg=soft,fg=color)
            self.contract_vehicle_alert_title.configure(bg=soft)
            self.contract_vehicle_alert_label.configure(bg=soft)

        if not row:
            self.contract_vehicle_alert_var.set("Sélectionnez un véhicule pour afficher ses alertes.")
            apply_style("#e5f2ff",BLUE,"⚠")
            return

        alerts=[];critical=False
        today=datetime.now().replace(hour=0,minute=0,second=0,microsecond=0)
        if not int(row["service"] or 0):
            alerts.append("Véhicule hors service")
            critical=True
        for key,label in (("assurance_fin","Assurance"),("controle_technique","Visite technique"),("fin_service","Fin de service")):
            due=self._parse_french_date(row[key] or "")
            if not due:
                continue
            days=(due-today).days
            if days<0:
                alerts.append(f"{label} expirée depuis {abs(days)} j")
                critical=True
            elif days<=30:
                alerts.append(f"{label} dans {days} j")

        current=int(self._number(self.vars["km_start"].get())) or int(row["compteur"] or 0)
        for key,label,threshold in (("prochaine_vidange","Vidange",1000),("prochaine_chaine","Chaîne",1000)):
            target=int(row[key] or 0)
            if not target:
                continue
            remaining=target-current
            if remaining<0:
                alerts.append(f"{label} dépassée de {abs(remaining)} km")
                critical=True
            elif remaining<=threshold:
                alerts.append(f"{label} dans {remaining} km")
        adblue=int(row["adblue_restant"] or 0)
        if adblue and adblue<=1000:
            alerts.append(f"AdBlue : {adblue} km restants")
            if adblue<=0:critical=True

        if alerts:
            self.contract_vehicle_alert_var.set("  •  ".join(alerts))
            apply_style("#ffe7ea" if critical else "#fff1dc",RED if critical else ORANGE,"⚠")
        else:
            self.contract_vehicle_alert_var.set("Aucune alerte proche pour ce véhicule.")
            apply_style("#e7f7ed",GREEN,"✓")

    def _choose_contract_vehicle_photo(self):
        code=self.vars["vehicle_code"].get().split("|")[0].strip()
        if not code:
            messagebox.showwarning("Photo véhicule","Sélectionnez d’abord un véhicule."); return
        source=filedialog.askopenfilename(filetypes=[("Images","*.png *.jpg *.jpeg *.gif")])
        if not source: return
        destination_dir=APP_DIR/"assets"/"vehicle_photos"; destination_dir.mkdir(parents=True,exist_ok=True)
        suffix=Path(source).suffix.lower() or ".jpg"
        destination=destination_dir/f"vehicule_{re.sub(r'[^0-9A-Za-z_-]+','_',code)}{suffix}"
        shutil.copy2(source,destination); self.conn.execute("UPDATE vehicles SET photo=? WHERE code=?",(str(destination),code)); self.conn.commit()
        self._display_contract_vehicle_photo(str(destination))

    def _display_contract_vehicle_photo(self,path):
        if not hasattr(self,"contract_vehicle_photo"): return
        self.contract_vehicle_photo_image=None
        if not path or not Path(path).exists(): self.contract_vehicle_photo.configure(text="🚘\nPHOTO DU VÉHICULE",image=""); return
        try:
            from PIL import Image,ImageTk
            # La colonne véhicule utilise un cadre 250x145. La photo entière est
            # conservée, centrée et entourée d'une marge blanche sans recadrage.
            im=Image.open(path).convert("RGB"); im.thumbnail((238,133),Image.LANCZOS)
            canvas=Image.new("RGB",(242,137),"white")
            canvas.paste(im,((242-im.width)//2,(137-im.height)//2))
            self.contract_vehicle_photo_image=ImageTk.PhotoImage(canvas); self.contract_vehicle_photo.configure(text="",image=self.contract_vehicle_photo_image)
        except Exception: self.contract_vehicle_photo.configure(text=f"🚘\n{Path(path).name}",image="")

