    def _filter_contract_history(self, _event=None):
        self.refresh_contract_history()

    def refresh_contract_history(self):
        if not hasattr(self,"contract_history_tree"): return
        rows=self.conn.execute("""SELECT c.numero,c.client_code,COALESCE(cl.nom,'') nom,COALESCE(cl.prenom,'') prenom,c.vehicle_code,COALESCE(v.modele,c.vehicle_code) modele,COALESCE(v.immatriculation,'') plate,c.date_depart,c.heure_depart,c.date_retour,c.heure_retour,c.duree,c.montant,c.reglement,c.reste,c.return_status,c.actual_return_date,c.actual_return_time FROM contracts c LEFT JOIN clients cl ON cl.code=c.client_code LEFT JOIN vehicles v ON v.code=c.vehicle_code""").fetchall()
        self._refresh_contract_summary(rows)
        clients=sorted({f"{r['client_code']} - {(r['nom']+' '+r['prenom']).strip()}" for r in rows if r['client_code']}); brands=sorted({str(r['modele']).split()[0] for r in rows if r['modele']})
        if hasattr(self,"contract_history_client_combo"): self.contract_history_client_combo.configure(values=["Tous les clients"]+clients)
        if hasattr(self,"contract_history_brand_combo"): self.contract_history_brand_combo.configure(values=["Toutes les marques"]+brands)
        mv=self.contract_history_month.get(); yv=self.contract_history_year.get(); cv=self.contract_history_client.get(); bv=self.contract_history_brand.get(); mn=("Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre")
        out=[]
        for r in rows:
            d=self._parse_french_date(r['date_depart'] or '')
            end_date=self._parse_french_date(r['date_retour'] or '')
            if mv!="Tous les mois" or yv!="Toutes les années":
                selected_month=mn.index(mv)+1 if mv in mn else None
                selected_year=int(yv) if str(yv).isdigit() else None
                if selected_month and selected_year:
                    period_start=datetime(selected_year,selected_month,1)
                    period_end=(period_start.replace(day=28)+timedelta(days=4)).replace(day=1)
                    if not d or d>=period_end or (end_date and end_date<period_start):continue
                elif selected_month and (not d or all(day.month!=selected_month for day in (d,end_date or d))):continue
                elif selected_year and (not d or d.year>selected_year or (end_date or d).year<selected_year):continue
            cdisp=f"{r['client_code']} - {(r['nom']+' '+r['prenom']).strip()}"
            if cv!="Tous les clients" and cdisp!=cv: continue
            if bv!="Toutes les marques" and not str(r['modele']).startswith(bv): continue
            out.append((r,cdisp))
        self.contract_history_tree.delete(*self.contract_history_tree.get_children()); today=datetime.now().date()
        for r,cdisp in out:
            end=self._parse_french_date(r['date_retour'] or '')
            rs=str(r['return_status'] or '').strip().upper()
            status=self._history_vehicle_status(r)
            tag=('annule' if status=='Annulé' else 'retard' if 'Retard' in status else
                 'termine' if 'confirmé' in status.lower() or 'anticipé' in status.lower() else
                 'prolonge' if 'Prolongé' in status else 'reserve' if status=='À venir' else 'en_cours')
            veh=f"{r['modele']} - {r['plate']}".strip(' -')
            indicator={'en_cours':'🔵','termine':'🟢','reserve':'🟡','retard':'🔴','annule':'⚫','prolonge':'🟣'}.get(tag,'⚪')
            actual=('—' if status=='Annulé' else
                    ' '.join(str(r[key] or '').strip() for key in ('actual_return_date','actual_return_time')).strip() or '—')
            self.contract_history_tree.insert('', 'end', values=(r['numero'],r['date_depart'],r['date_retour'],cdisp,veh,int(r['duree'] or 0),f"{float(r['montant'] or 0):.2f}",f"{float(r['reglement'] or 0):.2f}",f"{float(r['reste'] or 0):.2f}",f"{indicator} {status}",actual))
        if hasattr(self,"contract_history_summary"):
            filtered_ca=sum(float(record['montant'] or 0) for record,_client in out)
            filtered_paid=sum(float(record['reglement'] or 0) for record,_client in out)
            self.contract_history_summary.set(f"{len(out)} location(s)  •  CA filtré : {filtered_ca:,.2f} MAD  •  Réglé : {filtered_paid:,.2f} MAD")

        if hasattr(self,'_archive_contract_refresh'):self._archive_contract_refresh()
        if hasattr(self,'_contract_alarm_refresh'):self._contract_alarm_refresh()

    def _select_contract_history(self, _event=None):
        tree=getattr(self,"contract_history_tree",None)
        if tree is None or not tree.selection(): return
        values=tree.item(tree.selection()[0],"values")
        if not values: return
        self.contract_search_var.set(str(values[0])); self.load_contract_lookup()
        if _event and getattr(_event,"type",None)==tk.EventType.ButtonPress:
            self._select_contract_tab(0)

    @staticmethod
    def _is_confirmed_delay(status):
        return "RETARD CONFIRM" in str(status or "").upper()

    @staticmethod
    def _is_returned_contract(status):
        state=str(status or "").upper()
        return "RETOUR CONFIRM" in state or "ANTICIP" in state or "ANNUL" in state

    def _selected_contract_history_number(self):
        tree=getattr(self,"contract_history_tree",None)
        selected=tree.selection() if tree is not None else ()
        if not selected:
            self._professional_notice("Historique de location","Sélectionnez d’abord un contrat.","!",ORANGE)
            return ""
        values=tree.item(selected[0],"values")
        return str(values[0]).strip() if values else ""

    def confirm_contract_delay(self):
        """Un retard n'existe qu'après la confirmation explicite du responsable."""
        numero=self._selected_contract_history_number()
        if not numero:return
        row=self.conn.execute("SELECT numero,vehicle_code,date_depart,date_retour,heure_retour,return_status,actual_return_date FROM contracts WHERE numero=?",(numero,)).fetchone()
        if not row:return
        state=str(row["return_status"] or "").upper()
        if self._is_returned_contract(state) or row["actual_return_date"]:
            self._professional_notice("Retard de véhicule","Le véhicule est déjà revenu ou le contrat est annulé.","✓",GREEN);return
        if self._is_confirmed_delay(state):
            self._professional_notice("Retard de véhicule",f"Le retard du contrat {numero} est déjà confirmé.","!",ORANGE);return
        due=self._contract_datetime(row["date_retour"],row["heure_retour"],True)
        if not due or datetime.now()<=due:
            self._professional_notice("Retard de véhicule","La date et l’heure de retour prévues ne sont pas dépassées.","!",ORANGE);return
        candidates=self.conn.execute("SELECT numero,date_depart,heure_depart,return_status FROM contracts WHERE vehicle_code=?",(row["vehicle_code"],)).fetchall()
        current=[r for r in candidates if not self._is_returned_contract(r["return_status"])]
        latest=max(current,key=lambda r:self._contract_datetime(r["date_depart"],r["heure_depart"]) or datetime.min,default=None)
        if latest is None or str(latest["numero"])!=str(numero):
            self._professional_notice("Retard de véhicule","Ce contrat n’est pas la dernière location non clôturée de ce véhicule.","!",ORANGE);return
        message=(f"Le véhicule du contrat {numero} n’est pas rentré.\n\n"
                 f"Retour prévu : {row['date_retour']} à {row['heure_retour'] or '23:59'}.\n\n"
                 "Confirmer son retard ? Il sera alors indiqué comme loué et indisponible jusqu’à confirmation du retour.")
        if not self._professional_confirm("Confirmation spéciale du retard",message,"!",RED):return
        self.conn.execute("UPDATE contracts SET return_status='RETARD CONFIRMÉ' WHERE numero=?",(numero,))
        self._audit("RETARD CONFIRMÉ","CONTRAT",numero,"Retard confirmé manuellement depuis Historique de location")
        self.conn.commit();self.refresh_contract_history();self.refresh_dashboard()
        self._professional_notice("Retard confirmé",f"Le retard du contrat {numero} est confirmé. Le véhicule reste indisponible jusqu’à son retour.","!",RED)

    def confirm_contract_history_return(self):
        numero=self._selected_contract_history_number()
        if not numero:return
        self._confirm_history_return_for(numero)

    def _select_contract_tab(self,index):
        if not hasattr(self,"contract_tabs"):return
        self.contract_tabs.select(index)
        self._contract_tab_changed()

    def _contract_tab_changed(self,_event=None):
        if not hasattr(self,"contract_tabs"):return
        index=self.contract_tabs.index(self.contract_tabs.select())
        for i,button in enumerate(getattr(self,"contract_tab_buttons",())):
            accent=("#3177b3","#388674")[i]
            button.configure(bg=accent if i==index else ("#e6f1fa","#e5f5ee")[i],
                             fg="white" if i==index else accent)
        if index==1 and hasattr(self,"locations_tree"):
            self.refresh_locations_reference()

    def _navigate_contract_history(self, position):
        tree = getattr(self, "contract_history_tree", None)
        if tree is None: return
        items = tree.get_children()
        if not items: return
        current = tree.selection()[0] if tree.selection() else items[0]
        index = items.index(current)
        index = {"first":0, "prev":max(0,index-1), "next":min(len(items)-1,index+1), "last":len(items)-1}[position]
        tree.selection_set(items[index]); tree.focus(items[index]); tree.see(items[index])
        self._select_contract_history()

