    def _dashboard_financial_period(self):
        """Retourne le premier et le dernier instant du mois financier choisi."""
        months=("Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre")
        now=datetime.now();month_name=self.dashboard_fin_month.get() if hasattr(self,"dashboard_fin_month") else months[now.month-1]
        year_text=self.dashboard_fin_year.get() if hasattr(self,"dashboard_fin_year") else str(now.year)
        month=months.index(month_name)+1 if month_name in months else now.month
        year=int(year_text) if str(year_text).isdigit() else now.year
        start=datetime(year,month,1)
        next_month=datetime(year+1,1,1) if month==12 else datetime(year,month+1,1)
        return start,next_month-timedelta(seconds=1)

    def _refresh_dashboard_financial_cards(self):
        """Actualise les cinq cartes uniquement avec le mois et l'année choisis."""
        if not hasattr(self,"dashboard_top_fin_vars"):return
        start,end=self._dashboard_financial_period();totals=self._financial_totals(start,end)
        values={"month_revenue":totals.get("revenue",0),"month_expenses":totals.get("expenses",0),
                "receivables":totals.get("receivables",0),"bank":totals.get("bank",0),"cash":totals.get("cash",0),
                "credit_j10":self._hbz_credit_due_10d_total()}
        for key,value in values.items():self.dashboard_top_fin_vars[key].set(f"{float(value):,.2f}")

    def _set_dashboard_revenue_scope(self, scope):
        """Bascule le classement CA entre le mois et l'année en cours."""
        scope="Année" if scope=="Année" else "Mois"
        self.dashboard_rank_scope.set(scope)
        for name,button in getattr(self,"dashboard_rank_buttons",{}).items():
            active=name==scope;button.configure(bg=BLUE if active else "#f5f9fc",fg="white" if active else NAVY)
        if hasattr(self,"dashboard_rank_month_combo"):
            self.dashboard_rank_month_combo.configure(state="disabled" if scope=="Année" else "readonly")
        self._refresh_dashboard_revenue_rankings()

    def _dashboard_revenue_rankings(self, scope=None):
        """Retourne Top véhicules, Top clients et véhicules les moins rentables."""
        scope=scope or (self.dashboard_rank_scope.get() if hasattr(self,"dashboard_rank_scope") else "Mois")
        today=datetime.now();months=("Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre")
        year=self.dashboard_rank_year.get() if hasattr(self,"dashboard_rank_year") else str(today.year)
        if not str(year).isdigit():year=str(today.year)
        selected_month=self.dashboard_rank_month.get() if hasattr(self,"dashboard_rank_month") else months[today.month-1]
        month=f"{months.index(selected_month)+1:02d}" if selected_month in months else f"{today.month:02d}"
        if scope=="Année":
            condition="substr(c.date_depart,7,4)=?";params=(year,)
        else:
            condition="substr(c.date_depart,7,4)=? AND substr(c.date_depart,4,2)=?";params=(year,month)
        active="UPPER(COALESCE(c.return_status,'')) NOT LIKE '%ANNUL%'"
        top_vehicles=self.conn.execute(f"""
            SELECT c.vehicle_code,
                   COALESCE(NULLIF(TRIM(COALESCE(v.modele,'') || ' · ' || COALESCE(v.immatriculation,'')) ,''),c.vehicle_code) AS label,
                   SUM(COALESCE(c.montant,0)) AS revenue
            FROM contracts c LEFT JOIN vehicles v ON v.code=c.vehicle_code
            WHERE {condition} AND {active}
            GROUP BY c.vehicle_code ORDER BY revenue DESC,label LIMIT 3
        """,params).fetchall()
        top_clients=self.conn.execute(f"""
            SELECT c.client_code,
                   COALESCE(NULLIF(TRIM(COALESCE(cl.nom,'') || ' ' || COALESCE(cl.prenom,'')),''),c.client_code) AS label,
                   SUM(COALESCE(c.montant,0)) AS revenue
            FROM contracts c LEFT JOIN clients cl ON cl.code=c.client_code
            WHERE {condition} AND {active}
            GROUP BY c.client_code ORDER BY revenue DESC,label LIMIT 3
        """,params).fetchall()
        # Les véhicules en service sans location sur la période sont affichés à 0 MAD.
        low_vehicles=self.conn.execute(f"""
            SELECT v.code,
                   COALESCE(NULLIF(TRIM(COALESCE(v.modele,'') || ' · ' || COALESCE(v.immatriculation,'')),''),v.code) AS label,
                   COALESCE(SUM(COALESCE(c.montant,0)),0) AS revenue
            FROM vehicles v LEFT JOIN contracts c
              ON c.vehicle_code=v.code AND {condition} AND {active}
            WHERE v.service=1
            GROUP BY v.code ORDER BY revenue ASC,label LIMIT 3
        """,params).fetchall()
        return {"vehicles_top":top_vehicles,"clients_top":top_clients,"vehicles_low":low_vehicles}

    def _refresh_dashboard_revenue_rankings(self):
        if not hasattr(self,"dashboard_rank_vars"):return
        scope=self.dashboard_rank_scope.get() if hasattr(self,"dashboard_rank_scope") else "Mois"
        today=datetime.now();months=("Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre")
        year=self.dashboard_rank_year.get() if hasattr(self,"dashboard_rank_year") else str(today.year)
        month=self.dashboard_rank_month.get() if hasattr(self,"dashboard_rank_month") else months[today.month-1]
        self.dashboard_rank_period_label.set(f"Année {year}" if scope=="Année" else f"{month} {year}")
        rankings=self._dashboard_revenue_rankings(scope)
        for key,variables in self.dashboard_rank_vars.items():
            rows=rankings.get(key,())
            for index,var in enumerate(variables):
                if index<len(rows):
                    label=str(rows[index][1] or rows[index][0] or "—");amount=float(rows[index][2] or 0)
                    var.set(f"{label}  —  {amount:,.2f} MAD")
                else:var.set("—")

    def _set_dashboard_tab(self, name):
        self.dashboard_tab.set(name)
