    def _prepare_contract_output_data(self, contract_no):
        """Charge le contrat persisté sans recalculer ses montants corrigés."""
        row=self.conn.execute("SELECT * FROM contracts WHERE numero=?",(contract_no,)).fetchone()
        if not row:return False
        self.vars["contract_no"].set(row["numero"] or "")
        self.vars["client_code"].set(row["client_code"] or "");self.load_client()
        second_code=row["second_code"] or ""
        self.vars["second_code"].set(second_code)
        if second_code:
            second=self.conn.execute("SELECT * FROM clients WHERE code=?",(second_code,)).fetchone()
            if second:
                for target,source in {"second_cin":"cin","second_last":"nom","second_first":"prenom","second_license":"permis","second_phone":"telephone","second_birth_date":"date_naissance","second_license_date":"date_permis"}.items():
                    self.vars[target].set(second[source] or "")
                self.vars["second_age"].set(self._age_from_birth_date(second["date_naissance"] or ""))
                self.vars["second_license_age"].set(self._age_from_birth_date(second["date_permis"] or ""))
        else:
            for key in ("second_cin","second_last","second_first","second_license","second_phone","second_birth_date","second_age","second_license_date","second_license_age"):self.vars[key].set("")
        self.vars["vehicle_code"].set(row["vehicle_code"] or "");self.load_vehicle()
        mapping={"date_start":"date_depart","time_start":"heure_depart","date_end":"date_retour","time_end":"heure_retour","duration":"duree","daily_price":"prix","total":"montant","paid":"reglement","balance":"reste","km_start":"km_depart","km_return":"km_retour"}
        for target,source in mapping.items():self.vars[target].set("" if row[source] is None else str(row[source]))
        start=int(row["km_depart"] or 0);end=int(row["km_retour"] or 0)
        self.vars["km_used"].set(str(max(0,end-start)) if end else "")
        return True

    def _dashboard_contract_document(self, contract_no, action="preview"):
        """Produit l'aperçu, le PDF ou l'impression du contrat après modification."""
        if not self._prepare_contract_output_data(contract_no):
            self._professional_notice("Document du contrat","Contrat introuvable.","!",RED);return
        choice=self._choose_contract_style_for_print("Choisir le modèle du nouveau contrat")
        if not choice:return
        self.contract_output_model=choice;EXPORT_DIR.mkdir(exist_ok=True)
        safe=re.sub(r"[^0-9A-Za-z_-]+","_",contract_no)
        html_path=EXPORT_DIR/f"Contrat_actualise_{safe}.html"
        pdf_path=EXPORT_DIR/f"Contrat_actualise_{safe}.pdf"
        content=self._selected_contract_html()
        if action=="print":
            html_path.write_text(self._make_html_directly_printable(self._contract_html_with_verso(content)),encoding="utf-8")
            webbrowser.open(html_path.resolve().as_uri());return
        html_path.write_text(content,encoding="utf-8")
        if action=="save":
            selected=filedialog.asksaveasfilename(title="Enregistrer le nouveau contrat",defaultextension=".pdf",initialfile=pdf_path.name,filetypes=[("Document PDF","*.pdf")])
            if not selected:return
            pdf_path=Path(selected)
        self._create_pdf_preview(html_path,pdf_path,"Nouveau contrat actualisé",contract_verso=True)

