    def _dashboard_open_depot_rows(self, now=None):
        """Lire la même base que Dépôt de parc, sans créer ni modifier ses données."""
        now=now or datetime.now()
        from depot_parc.parking_app import DATA_DIR
        store=getattr(getattr(self,'parking_deposits_app',None),'store',None)
        path=Path(store.db_path) if store is not None else DATA_DIR/'parking.db'
        if not path.is_file():return []
        conn=None
        try:
            conn=sqlite3.connect(path.resolve().as_uri()+'?mode=ro',uri=True,timeout=2)
            conn.row_factory=sqlite3.Row
            deposits=conn.execute("""SELECT d.reference,d.vehicle_code,d.entry_at,d.daily_rate,d.place,
                        v.model,v.plate FROM deposits d LEFT JOIN vehicles v ON v.code=d.vehicle_code
                        WHERE d.status='EN DÉPÔT' ORDER BY d.id""").fetchall()
        except (sqlite3.Error,OSError):
            return []
        finally:
            if conn is not None:conn.close()
        rows=[]
        for row in deposits:
            try:
                entered=parse_when(str(row['entry_at']))
                days=0 if entered>now else duration_days(str(row['entry_at']),now.strftime('%d/%m/%Y %H:%M'))
                daily=float(row['daily_rate'] or 0)
            except (ValueError,TypeError):continue
            code=str(row['vehicle_code'] or '').strip()
            vehicle=self.conn.execute('SELECT modele,immatriculation FROM vehicles WHERE code=?',(code,)).fetchone()
            rows.append({'reference':str(row['reference'] or ''),'code':code,
                'model':str(vehicle['modele'] or code) if vehicle else str(row['model'] or code),
                'plate':str(vehicle['immatriculation'] or '') if vehicle else str(row['plate'] or ''),
                'entry_at':str(row['entry_at'] or ''),'place':str(row['place'] or ''),
                'days':days,'daily_rate':daily,'total':round(days*daily,2)})
        return rows

    def _open_dashboard_card_details(self, key):
        """V203/V241 — détail des cartes principales, avec suivi des véhicules au parc."""
        if key=="credit_j10":
            return self._open_financial_card_details("ÉCHÉANCES DUES ≤10 J","credit_j10",self._hbz_credit_due_10d_total())
        if key=="near_returns":
            self._set_dashboard_tab("Retours proches")
            return
        today=datetime.now().date(); rows=[]
        if key in ("service","available","rented"):
            active_codes=self._currently_rented_vehicle_codes()
            depot_rows=self._dashboard_open_depot_rows(datetime.now()) if key=="available" else []
            depot_by_code={item['code']:item for item in depot_rows}
            for r in self.conn.execute("SELECT code,COALESCE(modele,''),COALESCE(immatriculation,''),COALESCE(compteur,0),COALESCE(service,1) FROM vehicles ORDER BY modele,code"):
                if not r[4]: continue
                code=str(r[0] or "")
                if key=="available" and code in active_codes: continue
                if key=="rented" and code not in active_codes: continue
                status="EN SERVICE" if key=="service" else ("LOUÉ" if key=="rented" else ("⚠ AU PARC" if code in depot_by_code else "DISPONIBLE"))
                if key=="available" and code in depot_by_code:
                    d=depot_by_code[code]
                    rows.append((r[0],r[1],r[2],f"{d['days']} j · {d['daily_rate']:,.2f} MAD/j".replace(","," "),status, d['entry_at'], f"{d['total']:,.2f} MAD".replace(","," ")))
                else:
                    if key=="available":
                        rows.append((r[0],r[1],r[2],f"{int(r[3] or 0):,} km".replace(","," "),status,"",""))
                    else:
                        rows.append((r[0],r[1],r[2],f"{int(r[3] or 0):,} km".replace(","," "),status))
            title={"service":"VÉHICULES EN SERVICE","available":"VÉHICULES DISPONIBLES","rented":"VÉHICULES LOUÉS"}[key]
            if key=="available":
                headers=(("code","Code",85),("model","Marque / Modèle",220),("plate","Immatriculation",145),("km","Utilisation / Tarif",170),("status","Statut",115),("entry","Dépôt depuis",120),("total","Total jusqu'à aujourd'hui",165))
            else:
                headers=(("code","Code",100),("model","Marque / Modèle",260),("plate","Immatriculation",180),("km","Compteur",150),("status","Statut",140))
        elif key=="reservations":
            for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='reservations' ORDER BY created_at DESC"):
                try:q=json.loads(raw)
                except Exception:continue
                status=str(q.get("status","")).strip().upper()
                if status in ("ANNULÉ","ANNULE","TERMINÉ","TERMINE","CONVERTIE EN LOCATION"):continue
                client=" ".join(x for x in (str(q.get("last_name","")).strip(),str(q.get("first_name","")).strip()) if x) or str(q.get("client","") or "")
                vehicle=str(q.get("vehicle_model","") or q.get("vehicle","") or "")
                rows.append((q.get("reference") or rid,client,vehicle,q.get("start_date","") or "",q.get("end_date","") or "",q.get("status","") or "EN ATTENTE"))
            title="RÉSERVATIONS";headers=(("ref","N° réservation",130),("client","Client",210),("vehicle","Véhicule",210),("start","Départ",110),("end","Retour",110),("status","Statut",130))
        else:
            for level,category,ref,detail,due in self.collect_alerts(): rows.append((level,category,ref,detail,due))
            title="ALERTES";headers=(("level","Niveau",100),("category","Catégorie",210),("ref","Référence",130),("detail","Détail",360),("due","Échéance",150))
        win=self._secondary_window(self.root);win.title(f"Détail — {title}");win.geometry("1050x610");win.minsize(820,480);win.transient(self.root);win.configure(bg=BG)
        tk.Label(win,text=f"DÉTAIL • {title}",bg=NAVY,fg="white",font=("Segoe UI",16,"bold"),pady=12).pack(fill="x")
        tk.Label(win,text=f"{len(rows)} élément(s) affiché(s)",bg="#eaf4fb",fg=NAVY,font=("Segoe UI",11,"bold"),pady=7).pack(fill="x")
        frame=tk.Frame(win,bg=BG);frame.pack(fill="both",expand=True,padx=16,pady=14)
        cols=tuple(x[0] for x in headers);tree=ttk.Treeview(frame,columns=cols,show="headings")
        for c,h,w in headers:tree.heading(c,text=h);tree.column(c,width=w,anchor="center" if c not in ("model","client","vehicle","category","detail") else "w")
        sy=ttk.Scrollbar(frame,orient="vertical",command=tree.yview);sx=ttk.Scrollbar(frame,orient="horizontal",command=tree.xview);tree.configure(yscrollcommand=sy.set,xscrollcommand=sx.set)
        tree.grid(row=0,column=0,sticky="nsew");sy.grid(row=0,column=1,sticky="ns");sx.grid(row=1,column=0,sticky="ew");frame.grid_rowconfigure(0,weight=1);frame.grid_columnconfigure(0,weight=1)
        for row in rows:tree.insert("","end",values=row)
        if not rows:tree.insert("","end",values=("Aucun élément",)+("",)*(len(cols)-1))
        tk.Button(win,text="✕  Fermer",command=win.destroy,bg=NAVY,fg="white",relief="flat",padx=24,pady=8,font=("Segoe UI",9,"bold"),cursor="hand2").pack(pady=(0,14))

    def _contract_datetime(self, date_text, time_text, end=False):
        """Convertit date+heure contrat en datetime local, avec valeurs sûres si heure vide."""
        d=self._parse_french_date(date_text or "")
        if not d:return None
        raw=str(time_text or ("23:59" if end else "00:00")).strip().replace("h",":")
        try:
            parts=raw.split(":"); hh=int(parts[0]); mm=int(parts[1]) if len(parts)>1 else 0
            return d.replace(hour=max(0,min(23,hh)),minute=max(0,min(59,mm)),second=0,microsecond=0)
        except Exception:
            return d.replace(hour=23 if end else 0,minute=59 if end else 0,second=0,microsecond=0)

    def _currently_rented_vehicle_codes(self, moment=None):
        """Véhicules en location maintenant, ou dont le retard est confirmé."""
        moment=moment or datetime.now(); active=set()
        sql="""SELECT c.vehicle_code,c.date_depart,c.heure_depart,c.date_retour,c.heure_retour,
                      COALESCE(c.return_status,''),COALESCE(c.actual_return_date,'')
               FROM contracts c JOIN vehicles v ON v.code=c.vehicle_code WHERE v.service=1"""
        for r in self.conn.execute(sql):
            state=str(r[5] or "").upper()
            if self._is_returned_contract(state) or str(r[6] or '').strip():continue
            start=self._contract_datetime(r[1],r[2],False); end=self._contract_datetime(r[3],r[4],True)
            if start and ((end and start <= moment <= end) or (self._is_confirmed_delay(state) and start <= moment)):
                code=str(r[0] or "").strip()
                if code:active.add(code)
        return active

    def _dashboard_near_return_rows(self, moment=None):
        """Contrats actifs du parc dont le retour est prévu dans les 10 prochaines heures."""
        moment=moment or datetime.now()
        low=moment.strftime('%Y%m%d')
        high=(moment+timedelta(hours=10)).strftime('%Y%m%d')
        rows=self.conn.execute("""SELECT c.* FROM contracts c
            JOIN vehicles v ON v.code=c.vehicle_code AND v.service=1
            WHERE (substr(c.date_retour,7,4)||substr(c.date_retour,4,2)||substr(c.date_retour,1,2)) BETWEEN ? AND ?
            ORDER BY c.date_retour,c.heure_retour""",(low,high)).fetchall()
        selected={}
        for row in rows:
            if row['actual_return_date'] or self._is_returned_contract(row['return_status']):continue
            start=self._contract_datetime(row['date_depart'],row['heure_depart'])
            due=self._contract_datetime(row['date_retour'],row['heure_retour'],True)
            if not (start and due and start<=moment<due<=moment+timedelta(hours=10)):continue
            code=str(row['vehicle_code'] or '').strip()
            previous=selected.get(code)
            if previous is None or start>(self._contract_datetime(previous['date_depart'],previous['heure_depart']) or datetime.min):
                selected[code]=row
        return sorted(selected.values(),key=lambda row:self._contract_datetime(row['date_retour'],row['heure_retour'],True))

    def _set_dashboard_today_returns(self,rows):
        """Prépare les retours compris dans leur fenêtre de rappel de dix heures."""
        first_display=not self.dashboard_today_return_items
        items=[];seen=set()
        for row in rows:
            code=str(row["vehicle_code"] or "").strip()
            if not code or code in seen:continue
            vehicle=self.conn.execute("SELECT modele,photo FROM vehicles WHERE code=? AND service=1",(code,)).fetchone()
            if not vehicle:continue
            seen.add(code)
            items.append({"code":code,"modele":str(vehicle["modele"] or code),
                          "photo":str(vehicle["photo"] or ""),"date":str(row["date_retour"] or ""),
                          "heure":str(row["heure_retour"] or "23:59"),
                          "numero":str(row["numero"] or "")})
        self.dashboard_today_return_items=items
        if items:
            self.dashboard_return_ticker_index%=len(items)
            if first_display:
                canvas=getattr(self,"dashboard_return_ticker_canvas",None)
                self.dashboard_return_scroll=max(0,canvas.winfo_width()-12) if canvas is not None else 0
        else:self.dashboard_return_ticker_index=0;self.dashboard_return_scroll=0
        if hasattr(self,"_update_banner_return_ticker"):
            self._update_banner_return_ticker()
        if hasattr(self,"_draw_dashboard_header") and getattr(self,"dashboard_header_canvas",None) is not None:
            self._draw_dashboard_header()

    def _refresh_dashboard_return_ticker(self):
        """Afficher un retour de 10 h avant son échéance jusqu'à l'heure exacte.

        La prolongation décale naturellement la fenêtre ; un retour confirmé la ferme.
        """
        upcoming=self._dashboard_near_return_rows()
        self._set_dashboard_today_returns(upcoming)
        return upcoming

    def refresh_dashboard(self):
        if not hasattr(self, "dashboard_vars"): return
        today = datetime.now().date()
        service = self.conn.execute("SELECT COUNT(*) FROM vehicles WHERE service=1").fetchone()[0]
        # LOCATION.xlsx peut contenir plusieurs milliers d'anciennes locations.
        # Le tableau de bord ne doit parcourir que les contrats encore actifs ou
        # à venir, jamais tout l'historique à chaque navigation.
        cutoff=(today-timedelta(days=60)).strftime("%Y%m%d")
        contracts = self.conn.execute("""
            SELECT * FROM contracts
            WHERE ((substr(date_retour,7,4)||substr(date_retour,4,2)||substr(date_retour,1,2)) >= ?
                   OR UPPER(COALESCE(return_status,'')) LIKE 'RETARD CONFIRM%')
              AND UPPER(COALESCE(return_status,'')) NOT LIKE 'RETOUR CONFIRM%'
              AND UPPER(COALESCE(return_status,'')) NOT LIKE '%ANNUL%'
            ORDER BY (substr(date_depart,7,4)||substr(date_depart,4,2)||substr(date_depart,1,2)) DESC, created_at DESC
        """,(cutoff,)).fetchall()
        # V204 : disponibilité calculée à la date ET à l'heure courantes.
        # Un contrat futur ou déjà terminé à cette heure ne bloque pas le véhicule.
        moment=datetime.now()
        active_codes = self._currently_rented_vehicle_codes(moment)
        active_count = len(active_codes)
        near_returns=self._refresh_dashboard_return_ticker()
        near_numbers={str(row['numero']) for row in near_returns}
        available = max(0, service - len(active_codes))
        reservation_rows = self.conn.execute(
            "SELECT record_id,payload FROM module_records WHERE module='reservations'"
        ).fetchall()
        active_reservations=[]
        for reservation_row in reservation_rows:
            try:reservation=json.loads(reservation_row[1])
            except (json.JSONDecodeError,TypeError):continue
            reservation["_record_id"]=reservation_row[0]
            reservation_status=str(reservation.get("status","")).strip().upper()
            if reservation_status not in ("ANNULÉ","ANNULE","TERMINÉ","TERMINE","CONVERTIE EN LOCATION"):
                active_reservations.append(reservation)
        reservation_count = len(active_reservations)
        all_alerts = self.collect_alerts()
        alert_count = len(all_alerts)
        self.dashboard_vars[0].set(str(service))
        self.dashboard_vars[1].set(str(available))
        self.dashboard_vars[2].set(str(len(active_codes)))
        self.dashboard_vars[3].set(str(len(near_returns)))
        self.dashboard_vars[4].set(str(reservation_count))
        self.dashboard_vars[5].set(str(alert_count))
        if hasattr(self,"dashboard_reference_vars"):
            self._refresh_dashboard_reference(service,available,len(active_codes),contracts,
                                              active_reservations,all_alerts,near_returns)

        if hasattr(self, "dashboard_contracts_tree"):
            self.dashboard_contracts_tree.delete(*self.dashboard_contracts_tree.get_children())
            self.dashboard_row_photo_images={}
            selected_tab = self.dashboard_tab.get() if hasattr(self, "dashboard_tab") else "À venir"
            if selected_tab=="Réservations":
                def reservation_sort_key(payload):
                    parsed=self._parse_french_date(payload.get("start_date","") or "")
                    return parsed or datetime.max
                for index,payload in enumerate(sorted(active_reservations,key=reservation_sort_key)[:12]):
                    record_id=str(payload.get("_record_id","") or payload.get("reference","") or f"reservation-{index}")
                    reference=str(payload.get("reference","") or record_id)
                    client_text=(f"{payload.get('last_name','')} {payload.get('first_name','')}".strip()
                                 or str(payload.get("client","") or "—"))
                    vehicle_text=(str(payload.get("vehicle_model","") or "").strip()
                                  or str(payload.get("vehicle","") or "—"))
                    plate=str(payload.get("plate","") or "").strip()
                    if plate:vehicle_text=f"{vehicle_text} · {plate}"
                    start=self._parse_french_date(payload.get("start_date","") or "")
                    end=self._parse_french_date(payload.get("end_date","") or "")
                    duration=payload.get("duration","")
                    if not duration and start and end:duration=max(1,(end-start).days)
                    status=str(payload.get("status","") or "EN ATTENTE").upper()
                    tag="reservation_odd" if index%2 else "reservation_even"
                    row_iid=f"reservation:{record_id}"
                    vehicle_code=str(payload.get("vehicle_code","") or "").strip()
                    if not vehicle_code and plate:
                        found=self.conn.execute("SELECT code FROM vehicles WHERE immatriculation=? LIMIT 1",(plate,)).fetchone(); vehicle_code=str(found[0]) if found else ""
                    if vehicle_code and not self.conn.execute("SELECT 1 FROM vehicles WHERE code=?",(vehicle_code,)).fetchone():
                        found=self.conn.execute("SELECT code FROM vehicles WHERE modele=? OR immatriculation=? LIMIT 1",(vehicle_code,plate)).fetchone(); vehicle_code=str(found[0]) if found else ""
                    row_photo=self._dashboard_row_vehicle_photo(vehicle_code,row_iid)
                    self.dashboard_contracts_tree.insert("","end",iid=row_iid,image=row_photo,values=(
                        "▦  Ouvrir",reference,client_text,vehicle_text,payload.get("start_date",""),
                        payload.get("end_date",""),duration,status),tags=(tag,))
                visible=[]
            else:
                visible=[]
            for row in contracts:
                if selected_tab=="Réservations":break
                start=self._parse_french_date(row["date_depart"] or ""); end=self._parse_french_date(row["date_retour"] or "")
                state=(row["return_status"] or "").upper() if "return_status" in row.keys() else ""
                returned=self._is_returned_contract(state)
                if returned: continue
                if selected_tab=="À venir" and start and start.date()>today: visible.append(row)
                elif selected_tab=="Retours proches" and str(row['numero']) in near_numbers: visible.append(row)
                elif selected_tab=="En cours" and row["vehicle_code"] in active_codes and start and end and self._contract_datetime(row['date_depart'],row['heure_depart'])<=moment<=self._contract_datetime(row['date_retour'],row['heure_retour'],True): visible.append(row)
                elif selected_tab=="Retards confirmés" and self._is_confirmed_delay(state) and row["vehicle_code"] in active_codes: visible.append(row)
            for index,row in enumerate(visible[:12]):
                client = self.conn.execute("SELECT nom,prenom FROM clients WHERE code=?", (row["client_code"],)).fetchone()
                vehicle = self.conn.execute("SELECT modele,immatriculation FROM vehicles WHERE code=?", (row["vehicle_code"],)).fetchone()
                end = self._parse_french_date(row["date_retour"] or "")
                status = "À venir"
                if self._is_confirmed_delay(row["return_status"]): status = "RETARD CONFIRMÉ"
                elif "PROLONG" in (row["return_status"] or "").upper(): status = "PROLONGÉ"
                elif str(row['numero']) in near_numbers: status = "Retour proche"
                client_text = " ".join(client) if client else (row["client_code"] or "")
                vehicle_text = vehicle[0] if vehicle else (row["vehicle_code"] or "")
                start_date=self._parse_french_date(row["date_depart"] or "")
                days=max(0,(end-start_date).days) if end and start_date else ""
                modifiable=selected_tab in ("En cours","Retards confirmés")
                parity="odd" if index%2 else "even"
                tag=f"late_{parity}" if status=="RETARD CONFIRMÉ" else f"active_{parity}" if modifiable else f"excel_{parity}"
                row_iid=f"dashboard:{row['numero']}"
                row_photo=self._dashboard_row_vehicle_photo(row["vehicle_code"],row_iid)
                self.dashboard_contracts_tree.insert("", "end", iid=row_iid, image=row_photo, values=(
                    "✎  Modifier" if modifiable else "—",row["numero"], client_text, vehicle_text, row["date_depart"], row["date_retour"], days, status),tags=(tag,))

        if hasattr(self, "dashboard_fleet_text"):
            out_service = max(0, self.conn.execute("SELECT COUNT(*) FROM vehicles").fetchone()[0] - service)
            for var,value in zip(self.dashboard_fleet_vars,(service,len(active_codes),available)):
                var.set(f"{value:02d}")
            depot_rows=self._dashboard_open_depot_rows(datetime.now())
            depot_count=len(depot_rows)
            depot_total=sum(item['total'] for item in depot_rows)
            if depot_count:
                self.dashboard_available_title.set(f"Disponibles  ·  ⚠ {depot_count} AU PARC")
                # Affichage demandé : véhicule + frais journaliers + montant cumulé,
                # directement dans la carte supérieure « Véhicules disponibles ».
                notice_lines=[]
                for item in depot_rows[:2]:
                    model=item['model']
                    plate=f" · {item['plate']}" if item['plate'] else ""
                    notice_lines.append(
                        f"⚠ {model}{plate} — AU PARC\n"
                        f"{item['daily_rate']:,.2f} MAD/j · {item['days']} j · {item['total']:,.2f} MAD".replace(","," ")
                    )
                if depot_count>2:
                    notice_lines.append(f"+ {depot_count-2} autre(s) au parc")
                if hasattr(self,"dashboard_available_depot_notice"):
                    self.dashboard_available_depot_notice.set("\n".join(notice_lines))
                depot_details="   ·   AU PARC : " + ", ".join(
                    f"{item['model']} ({item['daily_rate']:,.0f} MAD/j · {item['total']:,.0f} MAD)".replace(","," ")
                    for item in depot_rows[:3])
                if depot_count>3: depot_details += f" · +{depot_count-3} autre(s)"
                self.dashboard_fleet_text.configure(text=(
                    f"Disponibles aujourd’hui : {available}   ·   Hors service : {out_service}   ·   ⚠ AU PARC : {depot_count}   ·   Frais en cours : {depot_total:,.2f} MAD".replace(","," ")
                    + depot_details))
            else:
                self.dashboard_available_title.set("Disponibles")
                if hasattr(self,"dashboard_available_depot_notice"):
                    self.dashboard_available_depot_notice.set("✓ Aucun véhicule actuellement au parc")
                self.dashboard_fleet_text.configure(text=(
                    f"Disponibles aujourd’hui : {available}   ·   Hors service : {out_service}"))
        if hasattr(self, "dashboard_alerts_text"):
            amount=self._hbz_credit_due_10d_total()
            lines=[f"▣  Échéances ≤10 jours · {amount:,.2f} DH".replace(","," ")]
            lines.extend(f"{'●' if a[0]=='CRITIQUE' else '◆'}  {a[1]} — {a[2]}" for a in all_alerts[:3])
            self.dashboard_alerts_text.configure(text="\n".join(lines),fg="#183247")

        if hasattr(self,"dashboard_fin_vars"):
            try:
                t=self._financial_totals(None,None)
                for k in self.dashboard_fin_vars:self.dashboard_fin_vars[k].set(f"{float(t.get(k,0)):,.2f}")
            except Exception:
                pass
        if hasattr(self,"dashboard_top_fin_vars"):
            try:
                self._refresh_dashboard_financial_cards()
            except Exception:
                pass
        if hasattr(self,"dashboard_rank_vars"):
            try:self._refresh_dashboard_revenue_rankings()
            except (sqlite3.Error,ValueError,TypeError):pass
        if hasattr(self,"dashboard_recent_text"):
            try:
                rows=self.conn.execute("SELECT action,entity,reference,created_at FROM audit_log ORDER BY created_at DESC LIMIT 5").fetchall()
                self.dashboard_recent_text.configure(text="    ·    ".join(f"{r[0]} — {r[1]} {r[2] or ''}" for r in rows[:3]) or "Aucune action récente")
            except Exception:
                self.dashboard_recent_text.configure(text="Activité récente disponible dans Historique")

    def _client_field(self, parent, label, key, row, column, readonly=False):
        tk.Label(parent, text=label, bg=CARD, fg="#3e596d", font=("Segoe UI", 9, "bold")).grid(
            row=row, column=column*2, sticky="w", padx=(4, 4), pady=2)
        code=key=="code";fill="#169447" if code else "#f8fbfd";border="#0d6f34" if code else "#9db7c8"
        canvas=tk.Canvas(parent,width=94 if code else 130,height=31,bg=CARD,highlightthickness=0)
        canvas.grid(row=row,column=column*2+1,sticky="w" if code else "ew",padx=(0,7),pady=2)
        entry=tk.Entry(canvas,textvariable=self.client_vars[key],relief="flat",bd=0,
                       bg=fill,readonlybackground=fill,fg="white" if code else TEXT,
                       font=("Segoe UI",15 if code else 9,"bold" if code else "normal"),
                       justify="center" if code else "left")
        slot=canvas.create_window(47 if code else 65,15,window=entry,width=73 if code else 105,height=22)
        def draw(event):
            canvas.delete("outline")
            width=max(36,event.width);height=30
            canvas.create_arc(1,1,19,height-1,start=90,extent=180,fill=border,outline=border,tags="outline")
            canvas.create_arc(width-19,1,width-1,height-1,start=270,extent=180,fill=border,outline=border,tags="outline")
            canvas.create_rectangle(10,1,width-10,height-1,fill=border,outline=border,tags="outline")
            canvas.create_arc(2,2,20,height-2,start=90,extent=180,fill=fill,outline=fill,tags="outline")
            canvas.create_arc(width-20,2,width-2,height-2,start=270,extent=180,fill=fill,outline=fill,tags="outline")
            canvas.create_rectangle(11,2,width-11,height-2,fill=fill,outline=fill,tags="outline")
            canvas.coords(slot,width/2,15);canvas.itemconfigure(slot,width=max(24,width-21));canvas.tag_raise(slot)
        canvas.bind("<Configure>",draw)
        if readonly:entry.configure(state="readonly")
        if key != "code" and not readonly:
            entry.bind("<KeyPress>", lambda _e:self._ensure_client_code(), add="+")
        parent.grid_columnconfigure(column*2+1, weight=1)
        if key in ("date_naissance", "date_permis", "validite_permis") and not readonly:
            self._attach_date_picker(entry, self.client_vars[key])
        return entry

    def _build_clients_page(self):
        page = self._new_page("clients")
        self.client_vars = {k:tk.StringVar() for k in (
            "code cin nom prenom date_naissance age adresse ville telephone permis date_permis permis_age "
            "lieu_permis categorie validite_permis sexe profession email observations photo date_enregistrement"
        ).split()}
        self.client_document_kind = tk.StringVar(value="CIN")
        self.client_document_path = tk.StringVar(value="Aucune pièce sélectionnée")
