    def _next_client_code(self):
        """Retourne le prochain code client numérique disponible et unique."""
        codes = [int(r[0]) for r in self.conn.execute("SELECT code FROM clients") if str(r[0]).isdigit()]
        candidate = max(codes or [0]) + 1
        while self.conn.execute("SELECT 1 FROM clients WHERE code=?", (str(candidate),)).fetchone():
            candidate += 1
        return str(candidate)

    def _ensure_client_code(self):
        """Génère le code dès la première saisie d'une nouvelle fiche, sans saisie manuelle."""
        if hasattr(self, "client_vars") and not self.client_vars["code"].get().strip():
            self.client_vars["code"].set(self._next_client_code())
            if not self.client_vars["date_enregistrement"].get().strip():
                self.client_vars["date_enregistrement"].set(datetime.now().strftime("%d/%m/%Y"))

    def new_client(self):
        for value in self.client_vars.values(): value.set("")
        self.client_vars["code"].set(self._next_client_code())
        self.client_vars["date_enregistrement"].set(datetime.now().strftime("%d/%m/%Y"))
        if hasattr(self, "client_photo_label"):
            self.client_photo_image = None
            self.client_photo_label.configure(text="👤\nAucune photo", image="")
        self.refresh_client_location_history("")

    def _client_values(self):
        self._update_client_age()
        keys = ("code", "cin", "nom", "prenom", "telephone", "ville", "adresse", "permis",
                "date_naissance", "date_permis", "lieu_permis", "categorie", "validite_permis", "sexe",
                "profession", "email", "observations", "photo", "date_enregistrement")
        return keys, [self.client_vars[k].get().strip() for k in keys]

    def _age_from_birth_date(self, value):
        """Retourne l'âge actuel calculé depuis une date de naissance, sans dépendre d'un champ DB age."""
        birth = self._parse_french_date(value)
        if not birth:
            return ""
        today = datetime.now()
        age = today.year - birth.year - ((today.month, today.day) < (birth.month, birth.day))
        return str(max(0, age))

    def _update_client_age(self):
        """Calcule l'âge et l'ancienneté du permis dès que leurs dates sont saisies."""
        self.client_vars["age"].set(self._age_from_birth_date(self.client_vars["date_naissance"].get()))
        if "permis_age" in self.client_vars:
            self.client_vars["permis_age"].set(self._age_from_birth_date(self.client_vars["date_permis"].get()))

    def _check_duplicate_client_cin(self, show_warning=False):
        """Refuse un CIN déjà affecté à un autre code client."""
        cin=re.sub(r"\s+","",self.client_vars["cin"].get().strip()).upper()
        current_code=self.client_vars["code"].get().strip()
        if not cin:
            return True
        self.client_vars["cin"].set(cin)
        duplicate=self.conn.execute(
            "SELECT code,cin,nom,prenom,telephone FROM clients "
            "WHERE UPPER(REPLACE(COALESCE(cin,''),' ',''))=? AND code<>? LIMIT 1",
            (cin,current_code)).fetchone()
        if not duplicate:
            return True
        if show_warning:
            self._professional_notice(
                "CIN déjà enregistré",
                f"Le numéro CIN {cin} appartient déjà à un autre client.\n\n"
                f"Code client : {duplicate['code']}\n"
                f"Client : {duplicate['nom']} {duplicate['prenom']}\n"
                f"Téléphone : {duplicate['telephone'] or 'non renseigné'}\n\n"
                "Le doublon est interdit. Utilisez la fiche existante ou corrigez le CIN.",
                "!",RED)
        return False

    def _build_client_identity_pdf(self, code, notify_missing=False):
        """Archive CIN recto/verso + permis recto/verso dans un PDF client unique."""
        code=str(code or "").strip()
        if not code:return None
        ordered=("CIN_RECTO","CIN_VERSO","PERMIS_RECTO","PERMIS_VERSO")
        pages=[];missing=[]
        for kind in ordered:
            row=self.conn.execute(
                "SELECT file_path FROM client_documents WHERE client_code=? AND document_type=? ORDER BY id DESC LIMIT 1",
                (code,kind)).fetchone()
            path=Path(str(row[0])) if row and row[0] else None
            if path and path.is_file():pages.append(path)
            else:missing.append(kind)
        if missing:
            if notify_missing:
                labels={"CIN_RECTO":"CIN recto","CIN_VERSO":"CIN verso","PERMIS_RECTO":"permis recto","PERMIS_VERSO":"permis verso"}
                messagebox.showwarning("Document PDF", "PDF unique non créé : il manque " + ", ".join(labels[x] for x in missing) + ".")
            return None
        folder=self._client_documents_folder(code)
        destination=folder/f"DOCUMENT_PDF_IDENTITE_{re.sub(r'[^0-9A-Za-z_-]+','_',code)}.pdf"
        # Remplace l'archive précédente pour garder un document PDF unique et à jour.
        old=self.conn.execute("SELECT id,file_path FROM client_documents WHERE client_code=? AND document_type='DOCUMENT_PDF' ORDER BY id DESC",(code,)).fetchall()
        for row in old:
            try:
                old_path=Path(str(row['file_path']))
                if old_path.is_file() and old_path.resolve()!=destination.resolve():old_path.unlink()
            except Exception:pass
        self.conn.execute("DELETE FROM client_documents WHERE client_code=? AND document_type='DOCUMENT_PDF'",(code,))
        result=self._archive_client_document_as_pdf(code,"DOCUMENT_PDF",pages,destination_path=destination)
        return result

    def save_client(self):
        if not self.client_vars["code"].get().strip():
            self.client_vars["code"].set(self._next_client_code())
        keys, values = self._client_values()
        if not values[2]: messagebox.showwarning("Client", "Nom client obligatoire."); return
        if not self._check_duplicate_client_cin(show_warning=True):return
        keys,values=self._client_values()
        try:
            self.conn.execute(f"INSERT INTO clients({','.join(keys)}) VALUES({','.join('?'*len(keys))})", values)
            self._audit("CRÉATION", "CLIENT", values[0], values[2] + " " + values[3])
            self.conn.commit();self._client_documents_folder(values[0]); self._build_client_identity_pdf(values[0]); self.refresh_clients(); self._load_search_values(); self.refresh_dashboard()
            messagebox.showinfo("Client", "Client enregistré.\n\nLes 4 faces CIN/permis sont archivées automatiquement dans un document PDF unique dès qu'elles sont disponibles.")
        except sqlite3.IntegrityError: messagebox.showwarning("Client", "Ce code client existe déjà.")

    @staticmethod
    def _tabular_filetypes():
        return [
            ("Excel", "*.xlsx"),
            ("CSV", "*.csv"),
            ("JSON", "*.json"),
            ("Tous les formats", "*.xlsx *.csv *.json"),
        ]

    def _write_tabular_file(self, path, headers, rows):
        """Écrit un tableau en Excel, CSV ou JSON selon l'extension choisie."""
        suffix = Path(path).suffix.lower()
        normalized = [["" if value is None else value for value in row] for row in rows]
        if suffix == ".csv":
            with open(path, "w", newline="", encoding="utf-8-sig") as stream:
                writer = csv.writer(stream, delimiter=";")
                writer.writerow(headers); writer.writerows(normalized)
        elif suffix == ".json":
            records = [dict(zip(headers, row)) for row in normalized]
            Path(path).write_text(json.dumps(records, ensure_ascii=False, indent=2), encoding="utf-8")
        elif suffix == ".xlsx":
            try:
                from openpyxl import Workbook
            except ImportError:
                self._write_xlsx_fallback(path, headers, normalized)
            else:
                book = Workbook(); sheet = book.active; sheet.title = "GestionPro"
                sheet.append(list(headers))
                for row in normalized: sheet.append(list(row))
                sheet.freeze_panes = "A2"; sheet.auto_filter.ref = sheet.dimensions
                for column in sheet.columns:
                    width = min(45, max(12, max(len(str(cell.value or "")) for cell in column) + 2))
                    sheet.column_dimensions[column[0].column_letter].width = width
                book.save(path)
        else:
            raise ValueError("Format non reconnu. Choisissez CSV, JSON ou Excel XLSX.")

    def _read_tabular_file(self, path):
        """Retourne une liste de dictionnaires depuis Excel, CSV ou JSON."""
        suffix = Path(path).suffix.lower()
        if suffix == ".csv":
            with open(path, newline="", encoding="utf-8-sig") as stream:
                return list(csv.DictReader(stream, delimiter=";"))
        if suffix == ".json":
            data = json.loads(Path(path).read_text(encoding="utf-8-sig"))
            if isinstance(data, dict): data = data.get("records", data.get("data", []))
            if not isinstance(data, list) or any(not isinstance(item, dict) for item in data):
                raise ValueError("Le fichier JSON doit contenir une liste d'enregistrements.")
            return data
        if suffix == ".xlsx":
            try:
                from openpyxl import load_workbook
            except ImportError:
                return self._read_xlsx_fallback(path)
            book = load_workbook(path, read_only=True, data_only=True); sheet = book.active
            iterator = sheet.iter_rows(values_only=True)
            headers = [str(value or "").strip() for value in next(iterator, ())]
            return [dict(zip(headers, row)) for row in iterator if any(value not in (None, "") for value in row)]
        raise ValueError("Format non reconnu. Choisissez CSV, JSON ou Excel XLSX.")

    @staticmethod
    def _xlsx_column_name(number):
        name = ""
        while number:
            number, remainder = divmod(number - 1, 26)
            name = chr(65 + remainder) + name
        return name

    def _write_xlsx_fallback(self, path, headers, rows):
        """Écriture XLSX minimale avec la bibliothèque standard uniquement."""
        values = [list(headers)] + [list(row) for row in rows]
        cells = []
        for row_index, row in enumerate(values, 1):
            parts = []
            for col_index, value in enumerate(row, 1):
                ref = f"{self._xlsx_column_name(col_index)}{row_index}"
                text_value = "" if value is None else str(value)
                escaped = html.escape(text_value)
                parts.append(f'<c r="{ref}" t="inlineStr"><is><t>{escaped}</t></is></c>')
            cells.append(f'<row r="{row_index}">' + "".join(parts) + "</row>")
        sheet_xml = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                     '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                     '<sheetData>' + "".join(cells) + '</sheetData></worksheet>')
        workbook_xml = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
                        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
                        '<sheets><sheet name="GestionPro" sheetId="1" r:id="rId1"/></sheets></workbook>')
        rels_xml = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
                    '</Relationships>')
        root_rels_xml = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                         '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                         '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
                         '</Relationships>')
        content_xml = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                       '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                       '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                       '<Default Extension="xml" ContentType="application/xml"/>'
                       '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
                       '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                       '</Types>')
        with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("[Content_Types].xml", content_xml)
            archive.writestr("_rels/.rels", root_rels_xml)
            archive.writestr("xl/workbook.xml", workbook_xml)
            archive.writestr("xl/_rels/workbook.xml.rels", rels_xml)
            archive.writestr("xl/worksheets/sheet1.xml", sheet_xml)

    def _read_xlsx_fallback(self, path):
        """Lecture XLSX simple (cellules texte et numériques) sans openpyxl."""
        with zipfile.ZipFile(path) as archive:
            names = archive.namelist()
            worksheet = next((name for name in names if name.startswith("xl/worksheets/") and name.endswith(".xml")), None)
            if not worksheet:
                raise ValueError("Le fichier Excel ne contient aucune feuille lisible.")
            xml = archive.read(worksheet)
            shared_strings = []
            if "xl/sharedStrings.xml" in names:
                shared_root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
                namespace = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
                for item in shared_root.findall(f"{namespace}si"):
                    shared_strings.append("".join(text.text or "" for text in item.iter(f"{namespace}t")))
        root = ET.fromstring(xml)
        namespace = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
        rows = []
        for row in root.findall(f".//{namespace}row"):
            values = []
            for cell in row.findall(f"{namespace}c"):
                # Les fichiers Excel standards peuvent utiliser sharedStrings
                # et les cellules peuvent être espacées (A1, C1, etc.).
                reference = cell.attrib.get("r", "")
                letters = "".join(character for character in reference if character.isalpha())
                column = 0
                for character in letters.upper():
                    column = column * 26 + ord(character) - 64
                while len(values) < max(0, column - 1):
                    values.append("")
                inline = cell.find(f"{namespace}is/{namespace}t")
                numeric = cell.find(f"{namespace}v")
                value = inline.text if inline is not None and inline.text is not None else (numeric.text if numeric is not None else "")
                if cell.attrib.get("t") == "s" and value != "":
                    try:
                        value = shared_strings[int(value)]
                    except (ValueError, IndexError):
                        value = ""
                values.append(value)
            rows.append(values)
        headers = [str(value or "").strip() for value in (rows[0] if rows else [])]
        return [dict(zip(headers, row)) for row in rows[1:] if any(value not in (None, "") for value in row)]

    def _export_sql_table(self, table, initial_name, order_by):
        path = filedialog.asksaveasfilename(defaultextension=".xlsx", filetypes=self._tabular_filetypes(),
                                            initialfile=initial_name)
        if not path: return
        try:
            columns = [row[1] for row in self.conn.execute(f"PRAGMA table_info({table})")]
            rows = self.conn.execute(f"SELECT {','.join(columns)} FROM {table} ORDER BY {order_by}").fetchall()
            self._write_tabular_file(path, columns, rows)
            messagebox.showinfo("Export", f"Export {Path(path).suffix.upper()[1:]} terminé.\n{path}")
        except (OSError, ValueError, RuntimeError) as exc:
            messagebox.showerror("Export", f"Export impossible : {exc}")

    def _import_sql_table(self, table, refresh_callback):
        path = filedialog.askopenfilename(filetypes=self._tabular_filetypes())
        if not path: return
        imported = 0
        try:
            columns = [row[1] for row in self.conn.execute(f"PRAGMA table_info({table})")]
            placeholders = ",".join("?" * len(columns))
            for row in self._read_tabular_file(path):
                lookup = self._normalize_import_row(table, row)
                values = [lookup.get(column.casefold(), "") for column in columns]
                if values and values[0] not in (None, ""):
                    self.conn.execute(f"INSERT OR REPLACE INTO {table}({','.join(columns)}) VALUES({placeholders})", values)
                    imported += 1
            self.conn.commit(); refresh_callback()
            messagebox.showinfo("Import", f"{imported} ligne(s) importée(s) depuis {Path(path).suffix.upper()[1:]}.")
        except (OSError, csv.Error, json.JSONDecodeError, ValueError, RuntimeError, sqlite3.Error) as exc:
            self.conn.rollback(); messagebox.showerror("Import", f"Import impossible : {exc}")

    @staticmethod
    def _normalize_import_row(table, row):
        """Traduit les en-têtes des fichiers CLIENT/VEHICULES/LOCATION."""
        raw = {str(key or "").strip().casefold(): value for key, value in row.items()}
        aliases = {
            "clients": {
                "code": ("code", "code_client"), "permis": ("permis", "num_permis"),
                "date_permis": ("date_permis", "date_delivrance"),
                "lieu_permis": ("lieu_permis", "lieu_delivrance_permis"),
                "categorie": ("categorie", "categorie_permis"),
            },
            "vehicles": {
                "code": ("code", "code_vehicule"), "modele": ("modele", "marque"),
                "chassis": ("chassis", "num_chassis"), "prix": ("prix", "prix_jour"),
                "assurance_fin": ("assurance_fin", "date_assurance"),
                "controle_technique": ("controle_technique", "date_visite_tech"),
                "mise_circulation": ("mise_circulation", "date_mise_circulation"),
                "fin_service": ("fin_service", "date_fin_service"),
                "adblue_restant": ("adblue_restant", "reste_km_adblue"),
                "prochaine_vidange": ("prochaine_vidange", "km_produit"),
            },
            "contracts": {
                "numero": ("numero", "code_location"), "client_code": ("client_code", "code_client"),
                "second_code": ("second_code", "dc_code_client"), "vehicle_code": ("vehicle_code", "code_vehicule"),
                "date_depart": ("date_depart",), "heure_depart": ("heure_depart",),
                "date_retour": ("date_retour",), "heure_retour": ("heure_retour",),
                "duree": ("duree",), "prix": ("prix",), "montant": ("montant",),
                "reglement": ("reglement",), "reste": ("reste",),
                "km_depart": ("km_depart", "compteur_actuel"), "km_retour": ("km_retour", "compteur_retour"),
            },
        }
        result = dict(raw)
        for target, names in aliases.get(table, {}).items():
            for name in names:
                if name in raw and raw[name] not in (None, ""):
                    result[target] = raw[name]
                    break
        if table == "vehicles":
            service = str(result.get("service", "")).strip().upper()
            result["service"] = 0 if service in ("0", "NON", "HORS SERVICE", "INACTIF") else 1
        return result

    def export_clients_csv(self):
        self._export_sql_table("clients", "clients.xlsx", "code")

    def import_clients_csv(self):
        self._import_sql_table("clients", lambda: (self.refresh_clients(), self._load_search_values(), self.refresh_dashboard()))

    def update_client(self):
        keys, values = self._client_values(); code = values[0]
        if not self._check_duplicate_client_cin(show_warning=True):return
        keys,values=self._client_values();code=values[0]
        assignments = ",".join(f"{k}=?" for k in keys[1:])
        cur = self.conn.execute(f"UPDATE clients SET {assignments} WHERE code=?", values[1:] + [code])
        if cur.rowcount: self._audit("MODIFICATION", "CLIENT", code)
        self.conn.commit()
        if cur.rowcount:self._build_client_identity_pdf(code)
        self.refresh_clients(); self._load_search_values()
        messagebox.showinfo("Client", "Client modifié. Document PDF d'identité actualisé si les 4 faces sont disponibles." if cur.rowcount else "Client introuvable.")

    def delete_client(self):
        code = self.client_vars["code"].get().strip()
        if code and messagebox.askyesno("Client", f"Supprimer le client {code} ?"):
            self.conn.execute("DELETE FROM clients WHERE code=?", (code,)); self._audit("SUPPRESSION", "CLIENT", code); self.conn.commit(); self.new_client(); self.refresh_clients(); self._load_search_values(); self.refresh_dashboard()

    def _client_filter_rows(self, query="", mode="Tous", limit=500):
        """Recherche ciblée et sûre utilisée par le tableau et l'autocomplétion."""
        field = {"Code client": "code", "CIN": "cin", "Nom": "nom",
                 "Prénom": "prenom", "Téléphone": "telephone"}.get(mode)
        sql = "SELECT code,cin,nom,prenom,telephone,ville,permis FROM clients"
        params = []
        if query:
            like = f"%{query.strip()}%"
            if field:
                sql += f" WHERE {field} LIKE ?"; params.append(like)
            else:
                sql += " WHERE code LIKE ? OR cin LIKE ? OR nom LIKE ? OR prenom LIKE ? OR telephone LIKE ?"
                params.extend([like] * 5)
        sql += " ORDER BY CASE WHEN code GLOB '[0-9]*' THEN CAST(code AS INTEGER) ELSE 2147483647 END, code LIMIT ?"; params.append(limit)
        return self.conn.execute(sql, params).fetchall()

    def refresh_clients(self, query="", mode="Tous"):
        if not hasattr(self, "clients_tree"): return
        self.clients_tree.delete(*self.clients_tree.get_children())
        rows = self._client_filter_rows(query, mode, 1000)
        for row in rows: self.clients_tree.insert("", "end", values=tuple(row))
        self._set_client_search_choices(rows, mode)

    def _set_client_search_choices(self, rows, mode="Tous"):
        """Présente d'abord la valeur recherchée tout en conservant le vrai code client."""
        lead_index={"Code client":0,"CIN":1,"Nom":2,"Prénom":3,"Téléphone":4}.get(mode,0)
        choices=[];self._client_search_code_by_choice={}
        for row in rows:
            lead=str(row[lead_index] or row[0])
            choice=f"{lead} | Code {row[0]} | {row[2]} {row[3]} | CIN {row[1]} | Tél. {row[4]}"
            choices.append(choice);self._client_search_code_by_choice[choice]=str(row[0])
        self.client_search_combo["values"]=choices

    def load_client_form(self, _event=None):
        raw = self.client_search_var.get().strip()
        code=getattr(self,"_client_search_code_by_choice",{}).get(raw,"")
        like = f"%{raw}%"
        if code:
            row = self.conn.execute("SELECT * FROM clients WHERE code=? LIMIT 1", (code,)).fetchone()
        else:
            field = {"Code client": "code", "CIN": "cin", "Nom": "nom",
                     "Prénom": "prenom", "Téléphone": "telephone"}.get(self.client_search_mode.get())
            if field:
                row = self.conn.execute(f"SELECT * FROM clients WHERE {field} LIKE ? ORDER BY nom,prenom LIMIT 1", (like,)).fetchone()
            else:
                row = self.conn.execute(
                    "SELECT * FROM clients WHERE code LIKE ? OR cin LIKE ? OR nom LIKE ? OR prenom LIKE ? OR telephone LIKE ? "
                    "ORDER BY nom,prenom LIMIT 1", (like, like, like, like, like)).fetchone()
        if not row: messagebox.showwarning("Client", "Client introuvable."); return
        self._populate_client_form(row)

    def _populate_client_form(self,row, update_search=True, update_history=True):
        """Charge immédiatement toute la fiche à partir d'un résultat de recherche."""
        for key in self.client_vars:
            if key in row.keys(): self.client_vars[key].set(row[key] or "")
        self._display_client_photo(self.client_vars["photo"].get())
        self._refresh_client_front_previews()
        # En recherche automatique on conserve le texte en cours de frappe.
        if update_search:
            self.client_search_var.set(str(row["code"] or ""))
        self.select_client_document_kind(self.client_document_kind.get())
        if update_history:self.refresh_client_location_history(row["code"])

    def _filter_client_search(self, _event=None):
        if not hasattr(self, "client_search_combo"): return
        raw = self.client_search_var.get().strip()
        mode = self.client_search_mode.get() if hasattr(self, "client_search_mode") else "Tous"
        rows = self._client_filter_rows(raw, mode, 100)
        self._set_client_search_choices(rows, mode)
        self.refresh_clients(raw, mode)
        if not raw:return
        field={"Code client":"code","CIN":"cin","Nom":"nom","Prénom":"prenom","Téléphone":"telephone"}.get(mode)
        if field:
            exact=self.conn.execute(f"SELECT * FROM clients WHERE UPPER({field})=UPPER(?) LIMIT 1",(raw,)).fetchone()
        else:
            exact=self.conn.execute("SELECT * FROM clients WHERE code=? OR UPPER(cin)=UPPER(?) OR UPPER(nom)=UPPER(?) OR UPPER(prenom)=UPPER(?) OR telephone=? LIMIT 1",(raw,raw,raw,raw,raw)).fetchone()
        if exact:
            self._populate_client_form(exact, update_search=False)
        elif len(rows) == 1 and len(raw) >= 2:
            # Une seule correspondance restante : remplissage immédiat de la fiche,
            # sans forcer l'utilisateur à appuyer sur Entrée ou Rechercher.
            only_code = str(rows[0][0] or "")
            only = self.conn.execute("SELECT * FROM clients WHERE code=? LIMIT 1", (only_code,)).fetchone()
            if only:
                self._populate_client_form(only, update_search=False)

    def _change_client_search_mode(self, _event=None):
        hints = {
            "Tous": "Code · CIN · nom · prénom · téléphone",
            "Code client": "Saisir ou choisir un code client",
            "CIN": "Saisir ou choisir un numéro CIN",
            "Nom": "Saisir ou choisir un nom",
            "Prénom": "Saisir ou choisir un prénom",
            "Téléphone": "Saisir ou choisir un téléphone",
        }
        self.client_search_hint.configure(text=hints.get(self.client_search_mode.get(), hints["Tous"]))
        self._filter_client_search(); self.client_search_combo.focus_set()

    def clear_client_filters(self):
        self.client_search_mode.set("Tous"); self.client_search_var.set("")
        self.client_search_hint.configure(text="Code · CIN · nom · prénom · téléphone")
        self._filter_client_search(); self.client_search_combo.focus_set()

    def select_client_tree(self, _event=None):
        selected = self.clients_tree.selection()
        if not selected:return
        values=self.clients_tree.item(selected[0], "values")
        if not values:return
        # La ligne contient un code exact. Passer par la recherche textuelle
        # pouvait charger un autre client selon le filtre actif (CIN, nom...).
        code=str(values[0]).strip()
        row=self.conn.execute("SELECT * FROM clients WHERE code=? LIMIT 1",(code,)).fetchone()
        if not row:return
        self._populate_client_form(row)
        if hasattr(self,"_select_client_tab"):self._select_client_tab("FICHE CLIENT")

    def select_client_location_tree(self, _event=None):
        """Une location charge la fiche de son conducteur dans le formulaire."""
        selected=self.client_locations_tree.selection()
        if not selected:return
        values=self.client_locations_tree.item(selected[0],"values")
        if len(values)<2:return
        contract=self.conn.execute("SELECT client_code,second_code FROM contracts WHERE numero=? LIMIT 1",(values[0],)).fetchone()
        if not contract:return
        code=contract["second_code"] if values[1]=="2e conducteur" else contract["client_code"]
        row=self.conn.execute("SELECT * FROM clients WHERE code=? LIMIT 1",(code,)).fetchone()
        if row:
            same_client=str(self.client_vars["code"].get()).strip()==str(code)
            self._populate_client_form(row,update_history=not same_client)
            if hasattr(self,"_select_client_tab"):self._select_client_tab("FICHE CLIENT")

    @staticmethod
    def _navigate_tree(tree, position):
        items = tree.get_children()
        if not items: return
        current = tree.selection()[0] if tree.selection() else items[0]
        index = items.index(current)
        index = {"first":0, "prev":max(0, index-1), "next":min(len(items)-1, index+1),
                 "last":len(items)-1}[position]
        tree.selection_set(items[index]); tree.focus(items[index]); tree.see(items[index])

    def refresh_client_location_history(self, client_code=None):
        if not hasattr(self, "client_locations_tree"): return
        self.client_locations_tree.delete(*self.client_locations_tree.get_children())
        code = str(client_code if client_code is not None else self.client_vars["code"].get()).strip()
        if not code:
            self.client_location_summary.set("Sélectionnez un client")
            return
        rows = self.conn.execute("""
            SELECT c.*, COALESCE(v.modele,''), COALESCE(v.immatriculation,'')
            FROM contracts c LEFT JOIN vehicles v ON v.code=c.vehicle_code
            WHERE c.client_code=? OR c.second_code=?
            ORDER BY substr(c.date_depart,7,4) DESC, substr(c.date_depart,4,2) DESC,
                     substr(c.date_depart,1,2) DESC
        """, (code, code)).fetchall()
        total = paid = balance = 0.0
        today = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
        for row in rows:
            total += float(row["montant"] or 0); paid += float(row["reglement"] or 0); balance += float(row["reste"] or 0)
            status = str(row["return_status"] or "").strip() if "return_status" in row.keys() else ""
            if not status:
                end = self._parse_french_date(row["date_retour"])
                status = "TERMINÉ" if end and end < today else "EN COURS"
            role = "Principal" if str(row["client_code"] or "") == code else "2e conducteur"
            self.client_locations_tree.insert("", "end", values=(
                row["numero"], role, row["vehicle_code"], row[-2], row[-1],
                row["date_depart"], row["date_retour"], f"{int(row['duree'] or 0)} j",
                f"{float(row['montant'] or 0):.2f}", f"{float(row['reglement'] or 0):.2f}",
                f"{float(row['reste'] or 0):.2f}", status))
        from signed_contracts import refresh_signed_column
        refresh_signed_column(self.client_locations_tree)
        self.client_location_summary.set(
            f"{len(rows)} location(s)  •  Total {total:,.2f} MAD  •  Réglé {paid:,.2f}  •  Reste {balance:,.2f}")

