    def use_cin_front_as_client_photo(self):
        """Utilise la première face image de la CIN comme portrait du client."""
        code=self.client_vars["code"].get().strip()
        row=self.conn.execute("SELECT file_path FROM client_documents WHERE client_code=? AND document_type IN ('CIN_RECTO','CIN') ORDER BY CASE WHEN document_type='CIN_RECTO' THEN 0 ELSE 1 END,id DESC LIMIT 1",(code,)).fetchone() if code else None
        if not row or not Path(row[0]).exists():
            messagebox.showwarning("Photo client","Aucun recto CIN image enregistré pour ce client. Importez d’abord la première face de la carte nationale.");return
        path=Path(row[0])
        if path.suffix.lower()==".pdf":
            messagebox.showwarning("Photo client","Le recto CIN est un PDF. Importez sa première face au format JPG ou PNG pour l’utiliser comme photo.");return
        self.client_vars["photo"].set(str(path))
        self.conn.execute("UPDATE clients SET photo=? WHERE code=?",(str(path),code));self.conn.commit()
        self._display_client_photo(str(path))
        self._audit("MISE À JOUR","PHOTO CLIENT",code,"Recto CIN utilisé comme photo")
        self.conn.commit()
        messagebox.showinfo("Photo client","Le recto de la carte nationale a été appliqué comme photo du client.")

    def _client_front_image(self,code,kind):
        """Dernière image de la face 1, indépendante des PDF multi-pages existants."""
        if not code or kind not in ("CIN","PERMIS"):return ""
        row=self.conn.execute(
            "SELECT file_path FROM client_documents WHERE client_code=? AND document_type=? ORDER BY id DESC LIMIT 1",
            (code,f"{kind}_RECTO")).fetchone()
        raw=str(row[0] or "") if row else ""
        if not raw:return ""
        path=Path(raw)
        if path.is_file():return str(path)
        filename=raw.replace("\\","/").split("/")[-1]
        portable=APP_DIR/"assets"/"client_documents"/str(code)/filename
        return str(portable) if portable.is_file() else ""

    def _open_client_front_image(self,kind,code=""):
        if not code and hasattr(self,"client_vars"):code=self.client_vars["code"].get().strip()
        path=self._client_front_image(code,kind)
        if path:webbrowser.open(Path(path).resolve().as_uri())

    def scan_client_front_image(self,code,kind,on_complete=None,face="RECTO"):
        """Numérise la face 1 en image et l'utilise comme photo du client."""
        code=str(code or "").strip()
        if face not in ("RECTO","VERSO"):return
        if kind not in ("CIN","PERMIS") or not self.conn.execute("SELECT 1 FROM clients WHERE code=?",(code,)).fetchone():
            messagebox.showwarning("Document client","Enregistrez ou sélectionnez un client avant de numériser.");return
        folder=self._client_documents_folder(code)
        destination=folder/f"{kind}_{face}_{datetime.now():%Y%m%d_%H%M%S_%f}.jpg"
        scanned=False
        if os.name=="nt":
            ps=('$d=New-Object -ComObject WIA.CommonDialog; $i=$d.ShowAcquireImage(1,2,131072,"{B96B3CAE-0728-11D3-9D7B-0000F81EF32E}",$true,$true,$false); '
                +f"if($i){{$i.SaveFile('{str(destination).replace(chr(39),chr(39)*2)}')}}")
            try:
                result=subprocess.run(["powershell.exe","-NoProfile","-STA","-Command",ps],capture_output=True,text=True,timeout=120)
                scanned=result.returncode==0 and destination.is_file()
            except (OSError,subprocess.TimeoutExpired):pass
        if not scanned:
            if not messagebox.askyesno("Scanner la première face", "Scanner indisponible ou numérisation annulée. Importer une image JPG ou PNG à la place ?"):
                destination.unlink(missing_ok=True);return
            source=filedialog.askopenfilename(title=f"Face 1 — {kind}",filetypes=[("Images","*.jpg *.jpeg *.png *.bmp *.tif *.tiff")])
            if not source:return
            try:
                from PIL import Image
                with Image.open(source) as image:
                    image.convert("RGB").save(destination,"JPEG",quality=93)
            except Exception as exc:
                messagebox.showerror("Document client",f"Impossible d'importer l'image :\n{exc}");return
        try:
            from PIL import Image
            with Image.open(destination) as image:image.verify()
            self.conn.execute("INSERT INTO client_documents(client_code,document_type,file_path,created_at) VALUES(?,?,?,?)",
                              (code,f"{kind}_{face}",str(destination),datetime.now().isoformat(timespec="seconds")))
            if face=="RECTO":
                self.conn.execute("UPDATE clients SET photo=? WHERE code=?",(str(destination),code))
                if hasattr(self,"client_vars") and self.client_vars["code"].get().strip()==code:
                    self.client_vars["photo"].set(str(destination));self._display_client_photo(str(destination))
            self.conn.commit()
            if on_complete:on_complete(str(destination))
            if hasattr(self,"client_vars") and self.client_vars["code"].get().strip()==code:
                self._refresh_client_front_previews()
                self.select_client_document_kind(kind)
            messagebox.showinfo("Document client",f"Face {'1' if face=='RECTO' else '2'} du {'CIN' if kind=='CIN' else 'permis'} enregistrée en image.")
        except Exception as exc:
            destination.unlink(missing_ok=True)
            messagebox.showerror("Document client",f"Enregistrement impossible :\n{exc}")

    def _refresh_client_front_previews(self):
        previews=getattr(self,"client_front_previews",{})
        self._client_front_thumbnails={}
        code=self.client_vars["code"].get().strip() if hasattr(self,"client_vars") else ""
        for kind,label in previews.items():
            path=self._client_front_image(code,kind)
            if not path:label.configure(image="",text=("Face 1 CIN" if kind=="CIN" else "Face 1 permis")+"\nAucune image");continue
            try:
                from PIL import Image,ImageTk
                with Image.open(path) as source:
                    picture=source.copy();picture.thumbnail((145,69),Image.LANCZOS)
                self._client_front_thumbnails[kind]=ImageTk.PhotoImage(picture)
                label.configure(image=self._client_front_thumbnails[kind],text="")
            except Exception:label.configure(image="",text=Path(path).name)

    def select_client_document_kind(self, kind):
        self.client_document_kind.set(kind)
        code = self.client_vars["code"].get().strip()
        row = self.conn.execute(
            "SELECT file_path FROM client_documents WHERE client_code=? AND document_type IN (?,?) "
            "ORDER BY CASE WHEN document_type=? THEN 0 ELSE 1 END,id DESC LIMIT 1",
            (code,f"{kind}_RECTO",kind,f"{kind}_RECTO")).fetchone() if code else None
        if row and Path(row[0]).exists():
            self.client_document_path.set(f"▤  {kind}\n{Path(row[0]).name}")
            self._display_client_document(row[0],kind)
        else:
            self.client_document_path.set(f"▤  {kind}\nAucune pièce sélectionnée")
            self._display_client_document("",kind)

    def _display_client_document(self,path,kind):
        """Affiche la pièce réelle dans la zone CIN/permis, avec ouverture complète au clic."""
        if not hasattr(self,"client_document_preview"):return
        self.client_document_image=None
        if not path or not Path(path).exists():
            self.client_document_preview.configure(image="",text=f"▤  {kind}\nAucune pièce sélectionnée");return
        suffix=Path(path).suffix.lower()
        if suffix==".pdf":
            self.client_document_preview.configure(image="",text=f"📄  DOCUMENT PDF — {kind}\n{Path(path).name}\n\nCliquer pour ouvrir le document",fg=BLUE)
            return
        try:
            from PIL import Image,ImageTk
            image=Image.open(path);image.thumbnail((360,170),Image.LANCZOS)
            self.client_document_image=ImageTk.PhotoImage(image)
            self.client_document_preview.configure(image=self.client_document_image,text=f"{kind} — cliquer pour agrandir",compound="top",fg=BLUE)
        except Exception:
            self.client_document_preview.configure(image="",text=f"▤  {kind}\n{Path(path).name}\nCliquer pour ouvrir",fg=BLUE)

