    def _client_documents_folder(self, client_code, create=True):
        """Retourne le dossier documentaire unique du client, nommé par son code."""
        safe_code=re.sub(r"[^0-9A-Za-z_-]+","_",str(client_code or "").strip())
        if not safe_code:raise ValueError("Code client obligatoire.")
        folder=CLIENT_DOCUMENTS_DIR/safe_code
        if create:folder.mkdir(parents=True,exist_ok=True)
        return folder

    def _organize_client_documents(self, client_code):
        """Copie sans perte les anciennes pièces isolées dans le dossier du client."""
        folder=self._client_documents_folder(client_code)
        changed=False
        for row in self.conn.execute("SELECT id,file_path FROM client_documents WHERE client_code=?",(client_code,)).fetchall():
            source=Path(row["file_path"] or "")
            if not source.exists():continue
            try:
                if source.parent.resolve()==folder.resolve():continue
            except OSError:pass
            destination=folder/source.name
            if destination.exists() and destination.resolve()!=source.resolve():
                destination=folder/f"{source.stem}_{row['id']}{source.suffix}"
            if not destination.exists():shutil.copy2(source,destination)
            self.conn.execute("UPDATE client_documents SET file_path=? WHERE id=?",(str(destination),row["id"]));changed=True
        if changed:self.conn.commit()
        return folder

    def open_client_documents_folder(self):
        """Ouvre le dossier du client sélectionné depuis la gestion des clients."""
        code=self.client_vars["code"].get().strip() if hasattr(self,"client_vars") else ""
        if not code:
            messagebox.showwarning("Dossier client","Sélectionnez ou enregistrez d’abord un client.");return
        if not self.conn.execute("SELECT 1 FROM clients WHERE code=?",(code,)).fetchone():
            messagebox.showwarning("Dossier client","Le code client sélectionné n’est pas enregistré.");return
        folder=self._organize_client_documents(code)
        if sys.platform.startswith("win"):os.startfile(str(folder))
        elif sys.platform=="darwin":subprocess.Popen(["open",str(folder)])
        else:subprocess.Popen(["xdg-open",str(folder)])

    def _archive_client_document_as_pdf(self, client_code, document_type, sources, destination_path=None):
        """Convertit plusieurs pages en un PDF, avec chemin choisi ou dossier client par défaut."""
        safe_code = re.sub(r"[^0-9A-Za-z_-]+", "_", client_code.strip())
        safe_kind = re.sub(r"[^0-9A-Za-z_-]+", "_", document_type.strip().upper()) or "DOCUMENT"
        destination_dir = self._client_documents_folder(safe_code)
        if destination_path:
            destination=Path(destination_path).expanduser()
            if destination.suffix.lower()!=".pdf":destination=destination.with_suffix(".pdf")
            destination.parent.mkdir(parents=True,exist_ok=True)
        else:
            destination = destination_dir / f"{safe_kind}_{datetime.now():%Y%m%d_%H%M%S}.pdf"
        paths = [Path(item) for item in sources if item and Path(item).exists()]
        if not paths:
            raise ValueError("Aucune page valide à enregistrer.")
        if len(paths) == 1 and paths[0].suffix.lower() == ".pdf":
            shutil.copy2(paths[0], destination)
        else:
            images = []
            pdf_sources = [path for path in paths if path.suffix.lower() == ".pdf"]
            image_sources = [path for path in paths if path.suffix.lower() != ".pdf"]
            if pdf_sources:
                try:
                    from pypdf import PdfReader, PdfWriter
                    writer = PdfWriter()
                    for source in pdf_sources:
                        for page in PdfReader(str(source)).pages: writer.add_page(page)
                    if image_sources:
                        from PIL import Image
                        temp_pdf = destination.parent / f"_pages_{datetime.now():%f}.pdf"
                        for source in image_sources:
                            image = Image.open(source).convert("RGB"); images.append(image.copy()); image.close()
                        images[0].save(temp_pdf, "PDF", save_all=True, append_images=images[1:], resolution=200)
                        for page in PdfReader(str(temp_pdf)).pages: writer.add_page(page)
                        temp_pdf.unlink(missing_ok=True)
                    with destination.open("wb") as stream: writer.write(stream)
                finally:
                    for image in images: image.close()
            else:
                from PIL import Image
                for source in image_sources:
                    image = Image.open(source).convert("RGB"); images.append(image.copy()); image.close()
                images[0].save(destination, "PDF", save_all=True, append_images=images[1:], resolution=200)
                for image in images: image.close()
        self.conn.execute(
            "INSERT INTO client_documents(client_code,document_type,file_path,created_at) VALUES(?,?,?,?)",
            (client_code, document_type, str(destination), datetime.now().isoformat(timespec="seconds")))
        self._audit("NUMÉRISATION", "DOCUMENT CLIENT", client_code, f"{document_type} / {destination.name}")
        self.conn.commit()
        return destination

