    def _vehicle_fuel_editor(self, parent, variable, background="white"):
        """Sélecteur partagé : huit segments persistants de vide (0) à plein (8)."""
        box=tk.Frame(parent,bg=background);box.pack(fill="x",padx=8,pady=(9,5))
        tk.Label(box,text="⛽ Carburant  /  8",bg=background,fg="#0759a5",font=("Segoe UI",8,"bold")).pack(anchor="w")
        segments=tk.Frame(box,bg=background);segments.pack(fill="x",pady=(4,2))
        buttons=[]
        def paint(*_):
            try: level=max(0,min(8,int(variable.get())))
            except (ValueError,TypeError): level=4
            for index,button in enumerate(buttons):
                button.configure(bg=("#e94a52" if level<=2 else "#f5a623" if level<=4 else "#23aa68") if index<level else "#d9e4eb")
        for index in range(8):
            button=tk.Button(segments,text="",width=1,height=1,relief="flat",bd=0,
                             cursor="hand2",command=lambda n=index:variable.set(str(n+1)))
            button.pack(side="left",fill="x",expand=True,padx=1);buttons.append(button)
        tk.Button(box,text="E  ·  vider",command=lambda:variable.set("0"),bg=background,fg="#61778e",relief="flat",font=("Segoe UI",7)).pack(side="left")
        tk.Label(box,text="F  ·  plein",bg=background,fg="#61778e",font=("Segoe UI",7)).pack(side="right")
        variable.trace_add("write",paint);paint()
        return box

    def _refresh_vehicle_service_badge(self):
        """Met à jour le badge 2D de service de la fiche véhicule."""
        if not hasattr(self,"vehicle_service_badge") or not hasattr(self,"vehicle_form_vars"):
            return
        state=self.vehicle_form_vars["service"].get().strip().upper()
        if state=="HORS SERVICE":
            self.vehicle_service_badge.configure(text="●  HORS SERVICE",bg="#dc3545")
        else:
            self.vehicle_service_badge.configure(text="●  EN SERVICE",bg="#16a34a")
    def new_vehicle(self):
        for value in self.vehicle_form_vars.values(): value.set("")
        codes = [int(r[0]) for r in self.conn.execute("SELECT code FROM vehicles") if str(r[0]).isdigit()]
        self.vehicle_form_vars["code"].set(f"{max(codes or [0])+1:06d}"); self.vehicle_form_vars["service"].set("EN SERVICE");self.vehicle_form_vars["fuel_eighths"].set("4");self._refresh_vehicle_lifecycle_vars()
        if hasattr(self,"vehicle_alert_var"):
            self.vehicle_alert_var.set("Alertes : aucune sélection")
        if hasattr(self,"vehicle_remaining_card_vars"):
            for value in self.vehicle_remaining_card_vars.values():value.set("— km")
        self._display_vehicle_photo("")
        self._set_sidebar_vehicle_photo()
        self._refresh_vehicle_service_badge()
        if hasattr(self, "vehicle_history_vehicle"):
            self.vehicle_history_vehicle.set("Véhicule sélectionné")
            self.refresh_vehicle_location_history("")
        if hasattr(self,'vehicle_maintenance_tree'):
            self._vehicle_maintenance_new();self._refresh_vehicle_maintenance_tab()

    def save_vehicle_counter(self):
        """La fiche principale est verrouillée : seul le compteur peut être enregistré ici."""
        code=self.vehicle_form_vars["code"].get().strip() if hasattr(self,"vehicle_form_vars") else ""
        if not code or not self.conn.execute("SELECT 1 FROM vehicles WHERE code=?",(code,)).fetchone():
            messagebox.showwarning("Compteur véhicule","Sélectionnez d’abord un véhicule dans le tableau.");return
        counter=int(self._number(self.vehicle_form_vars["compteur"].get()))
        if counter<0:messagebox.showwarning("Compteur véhicule","Le compteur ne peut pas être négatif.");return
        self.conn.execute("UPDATE vehicles SET compteur=? WHERE code=?",(counter,code))
        self._refresh_vehicle_remaining_values(code);self._audit("MODIFICATION","COMPTEUR VÉHICULE",code,f"Compteur : {counter} km")
        self.conn.commit();self.refresh_vehicles();updated=self.conn.execute("SELECT * FROM vehicles WHERE code=?",(code,)).fetchone()
        if updated:self._populate_vehicle_form(updated)
        self.refresh_dashboard();self.schedule_web_sync();messagebox.showinfo("Compteur véhicule",f"Compteur enregistré : {counter:,} km")

    def _vehicle_values(self):
        v = self.vehicle_form_vars
        self._refresh_vehicle_lifecycle_vars()
        return (v["code"].get().strip(), v["modele"].get().strip(), v["immatriculation"].get().strip(),
                v["chassis"].get().strip(), int(self._number(v["compteur"].get())), self._number(v["prix"].get()),
                1 if v["service"].get() == "EN SERVICE" else 0, v["photo"].get().strip(),
                v["assurance_fin"].get().strip(),v["controle_technique"].get().strip(),v["mise_circulation"].get().strip(),
                v["fin_service"].get().strip(),int(self._number(v["adblue_restant"].get())),int(self._number(v["prochaine_vidange"].get())),
                v["remarque"].get().strip(),int(self._number(v["age_mois"].get())),int(self._number(v["reste_service_mois"].get())))

    def _validate_vehicle_form(self):
        v=self.vehicle_form_vars
        if not v["code"].get().strip() or not v["modele"].get().strip():return "Code et marque/modèle obligatoires."
        for key,label in (("mise_circulation","mise en circulation"),("assurance_fin","assurance"),("controle_technique","contrôle technique"),("fin_service","fin de service")):
            if v[key].get().strip() and not self._parse_french_date(v[key].get()):return f"Date {label} invalide. Utilisez JJ/MM/AAAA."
        if self._number(v["compteur"].get())<0 or self._number(v["prix"].get())<0:return "Le compteur et le prix ne peuvent pas être négatifs."
        if not v["fuel_eighths"].get().isdigit() or not 0<=int(v["fuel_eighths"].get())<=8:return "Choisissez un niveau de carburant entre 0 et 8 barres."
        return ""

    def save_vehicle(self):
        values = self._vehicle_values()
        error=self._validate_vehicle_form()
        if error: messagebox.showwarning("Véhicule",error); return
        try:
            self.conn.execute("""INSERT INTO vehicles(code,modele,immatriculation,chassis,compteur,prix,service,photo,assurance_fin,controle_technique,mise_circulation,fin_service,adblue_restant,prochaine_vidange,remarque,age_mois,reste_service_mois) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", values); self.conn.execute("UPDATE vehicles SET fuel_eighths=? WHERE code=?",(int(self.vehicle_form_vars["fuel_eighths"].get()),values[0])); self._audit("CRÉATION", "VÉHICULE", values[0], values[1]); self.conn.commit(); self.refresh_vehicles(); self._load_search_values(); self.refresh_dashboard(); self.schedule_web_sync(); messagebox.showinfo("Véhicule", "Véhicule enregistré.")
        except sqlite3.IntegrityError: messagebox.showwarning("Véhicule", "Code ou immatriculation déjà utilisé.")

    def export_vehicles_csv(self):
        self._export_sql_table("vehicles", "vehicules.xlsx", "code")

    def import_vehicles_csv(self):
        self._import_sql_table("vehicles", lambda: (self.refresh_vehicles(), self._load_search_values(), self.refresh_dashboard()))

    def update_vehicle(self):
        error=self._validate_vehicle_form()
        if error:messagebox.showwarning("Véhicule",error);return
        v = self._vehicle_values(); cur = self.conn.execute("UPDATE vehicles SET modele=?,immatriculation=?,chassis=?,compteur=?,prix=?,service=?,photo=?,assurance_fin=?,controle_technique=?,mise_circulation=?,fin_service=?,adblue_restant=?,prochaine_vidange=?,remarque=?,age_mois=?,reste_service_mois=? WHERE code=?", v[1:] + (v[0],))
        if cur.rowcount:
            self.conn.execute("UPDATE vehicles SET fuel_eighths=? WHERE code=?",(int(self.vehicle_form_vars["fuel_eighths"].get()),v[0]));self._refresh_vehicle_remaining_values(v[0]);self._audit("MODIFICATION", "VÉHICULE", v[0], v[1])
        self.conn.commit(); self.refresh_vehicles(); self._load_search_values(); self.refresh_dashboard(); self.schedule_web_sync(); messagebox.showinfo("Véhicule", "Véhicule modifié." if cur.rowcount else "Véhicule introuvable.")

    def delete_vehicle(self):
        code = self.vehicle_form_vars["code"].get().strip()
        if code and messagebox.askyesno("Véhicule", f"Supprimer le véhicule {code} ?"):
            linked = self.conn.execute("SELECT 1 FROM contracts WHERE vehicle_code=? LIMIT 1", (code,)).fetchone()
            if linked:
                messagebox.showwarning("Véhicule", "Suppression impossible : ce véhicule possède un historique de contrats."); return
            self.conn.execute("DELETE FROM vehicles WHERE code=?", (code,)); self._audit("SUPPRESSION", "VÉHICULE", code); self.conn.commit(); self.new_vehicle(); self.refresh_vehicles(); self._load_search_values(); self.refresh_dashboard(); self.schedule_web_sync()

    def open_vehicle_photo_dropdown(self):
        """Liste déroulante personnalisée avec photo miniature et filtre de service."""
        if not hasattr(self, "vehicle_search_display"):
            return
        old=getattr(self,"_vehicle_dropdown",None)
        if old is not None:
            try:
                if old.winfo_exists(): old.destroy()
            except Exception:
                pass
        win=self._secondary_window(self.root)
        self._vehicle_dropdown=win
        win.overrideredirect(True)
        win.configure(bg="#8daabd")
        try:
            x=self.vehicle_search_display.winfo_rootx()
            y=self.vehicle_search_display.winfo_rooty()+self.vehicle_search_display.winfo_height()+4
            win.geometry(f"520x360+{x}+{y}")
        except Exception:
            win.geometry("520x360")
        outer=tk.Frame(win,bg="#ffffff",highlightbackground="#0b79b7",highlightthickness=2)
        outer.pack(fill="both",expand=True,padx=2,pady=2)
        head=tk.Frame(outer,bg="#07558a"); head.pack(fill="x")
        tk.Label(head,text="🚘  SÉLECTIONNER UN VÉHICULE",bg="#07558a",fg="white",font=("Segoe UI",10,"bold"),padx=10,pady=7).pack(side="left")
        tk.Button(head,text="✕",command=win.destroy,bg="#07558a",fg="white",activebackground="#ef4e52",activeforeground="white",relief="flat",bd=0,font=("Segoe UI",10,"bold")).pack(side="right",padx=6)
        canvas=tk.Canvas(outer,bg="#f5fbff",highlightthickness=0)
        scroll=ttk.Scrollbar(outer,orient="vertical",command=canvas.yview)
        rows=tk.Frame(canvas,bg="#f5fbff")
        rows.bind("<Configure>",lambda e:canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.create_window((0,0),window=rows,anchor="nw",width=492)
        canvas.configure(yscrollcommand=scroll.set)
        canvas.pack(side="left",fill="both",expand=True); scroll.pack(side="right",fill="y")
        filt=self.vehicle_search_service_filter.get() if hasattr(self,"vehicle_search_service_filter") else "TOUS"
        query="SELECT code,modele,immatriculation,photo,service FROM vehicles ORDER BY modele,code"
        data=list(self.conn.execute(query))
        self._vehicle_dropdown_images=[]
        shown=0
        for row in data:
            state="EN SERVICE" if row[4] else "HORS SERVICE"
            if filt!="TOUS" and state!=filt:
                continue
            shown+=1
            bg="#eef9f2" if row[4] else "#fff0f0"
            card=tk.Frame(rows,bg=bg,highlightbackground="#d4e5ef",highlightthickness=1,cursor="hand2")
            card.pack(fill="x",padx=6,pady=4)
            photo_label=tk.Label(card,text="🚘",bg="#d9e8f1",fg="#537085",font=("Segoe UI Emoji",20),width=6,height=2)
            photo_label.pack(side="left",padx=6,pady=5)
            from vehicle_brands import logo
            mark=logo(self,row[1]); tk.Label(card,image=mark,bg=bg).pack(side="left",padx=3)
            photo=row[3] or ""
            if photo:
                try:
                    from PIL import Image,ImageTk
                    pp=Path(photo)
                    if not pp.is_absolute(): pp=APP_DIR/pp
                    if pp.exists():
                        im=Image.open(pp).convert("RGB"); im.thumbnail((72,48),Image.LANCZOS)
                        img=ImageTk.PhotoImage(im); self._vehicle_dropdown_images.append(img)
                        photo_label.configure(image=img,text="",width=72,height=48)
                except Exception:
                    pass
            txt=tk.Frame(card,bg=bg); txt.pack(side="left",fill="both",expand=True,padx=4,pady=5)
            tk.Label(txt,text=f"{row[1] or 'Sans modèle'}",bg=bg,fg="#103d5b",font=("Segoe UI",10,"bold"),anchor="w").pack(fill="x")
            tk.Label(txt,text=f"Code : {row[0]}     •     Immat. : {row[2] or '-'}",bg=bg,fg="#5a7180",font=("Segoe UI",8),anchor="w").pack(fill="x",pady=(3,0))
            badge=tk.Label(card,text=state,bg=("#1f9b4b" if row[4] else "#d84949"),fg="white",font=("Segoe UI",8,"bold"),padx=8,pady=4)
            badge.pack(side="right",padx=8)
            def choose(_e=None,code=row[0],model=row[1],immat=row[2]):
                full=self.conn.execute("SELECT * FROM vehicles WHERE code=?",(code,)).fetchone()
                if full:
                    self._populate_vehicle_form(full)
                    self.vehicle_quick_search.set(f"{model}  •  {code}  •  {immat}")
                try: win.destroy()
                except Exception: pass
            for w in (card,photo_label,txt,badge): w.bind("<Button-1>",choose)
            for w in txt.winfo_children(): w.bind("<Button-1>",choose)
        if not shown:
            tk.Label(rows,text="Aucun véhicule pour ce filtre",bg="#f5fbff",fg="#7b8d99",font=("Segoe UI",10,"bold"),pady=25).pack(fill="x")
        win.bind("<Escape>",lambda e:win.destroy())
        win.focus_force()

    def _render_vehicle_cards(self, rows):
        """V206 — cartes véhicule informatives, inspirées de la page Entretien."""
        if not hasattr(self,"vehicle_cards_inner"):return
        for child in self.vehicle_cards_inner.winfo_children():child.destroy()
        self._vehicle_card_images=[]
        active=self._currently_rented_vehicle_codes(datetime.now())
        availability=(self.vehicle_availability_filter.get() if hasattr(self,"vehicle_availability_filter") else "TOUS")
        visible=[]
        for row in rows:
            code=str(row["code"] or "").strip(); rented=code in active
            if availability=="DISPONIBLES" and (rented or not int(row["service"] or 0)):continue
            if availability=="LOUÉS" and not rented:continue
            visible.append(row)
        for c in range(3):self.vehicle_cards_inner.grid_columnconfigure(c,weight=1,uniform="fleetcards")
        for i,row in enumerate(visible):
            code=str(row["code"] or "").strip(); rented=code in active; service=bool(row["service"])
            status="Hors service" if not service else ("Loué" if rented else "Disponible")
            status_bg="#64748b" if not service else ("#ef4444" if rented else "#16a34a")
            card=tk.Frame(self.vehicle_cards_inner,bg="white",highlightbackground="#2388e8" if self.vehicle_form_vars["code"].get()==code else "#cbdde9",highlightthickness=2 if self.vehicle_form_vars["code"].get()==code else 1,bd=0,cursor="hand2")
            card.grid(row=i//3,column=i%3,sticky="nsew",padx=6,pady=6)
            top=tk.Frame(card,bg="#edf6fc",height=118);top.pack(fill="x",padx=8,pady=(8,4));top.pack_propagate(False)
            from vehicle_brands import logo
            mark=logo(self,row["modele"]); brand_badge=tk.Label(top,image=mark,bg="#edf6fc"); brand_badge.place(relx=.02,rely=.05,anchor="nw")
            pic=tk.Label(top,text="🚘",bg="#edf6fc",fg="#55758c",font=("Segoe UI Emoji",30));pic.pack(fill="both",expand=True)
            pp=self._resolve_vehicle_photo_path(row["photo"] if "photo" in row.keys() else "",code)
            if pp:
                try:
                    from PIL import Image,ImageTk
                    im=Image.open(pp);im.thumbnail((250,105),Image.LANCZOS);ph=ImageTk.PhotoImage(im);self._vehicle_card_images.append(ph);pic.configure(image=ph,text="")
                except Exception:pass
            brand_badge.lift()
            tk.Label(top,text=status,bg=status_bg,fg="white",font=("Segoe UI",8,"bold"),padx=10,pady=4).place(relx=.98,rely=.05,anchor="ne")
            info=tk.Frame(card,bg="white");info.pack(fill="x",padx=10,pady=(1,5))
            tk.Label(info,text=(row["modele"] or "VÉHICULE").upper(),bg="white",fg="#10243b",font=("Segoe UI",11,"bold"),anchor="w").pack(fill="x")
            tk.Label(info,text=f"Code : {code}     •     Immat : {row['immatriculation'] or '-'}",bg="white",fg="#35546d",font=("Segoe UI",8,"bold"),anchor="w").pack(fill="x",pady=(2,0))
            counter_line=tk.Frame(info,bg="white");counter_line.pack(fill="x",pady=(2,0))
            tk.Label(counter_line,text="◴",bg="white",fg="#0759a5",font=("Segoe UI Symbol",11,"bold")).pack(side="left")
            counter_var=tk.StringVar(value=str(int(row["compteur"] or 0)))
            # Compteur : 4 cm environ, centré, gras et protégé tant que Modifier n'est pas activé.
            counter_entry=tk.Entry(counter_line,textvariable=counter_var,bg="#eaf4ff",fg="#0759a5",justify="center",font=("Segoe UI",10,"bold"),relief="solid",bd=1,width=15,state="readonly",readonlybackground="#eaf4ff")
            counter_entry.pack(side="left",padx=5,ipady=3)
            tk.Label(counter_line,text="km",bg="white",fg="#35546d",font=("Segoe UI",8,"bold")).pack(side="left")
            def save_card_counter(_e=None,c=code,v=counter_var,e=counter_entry):
                try: value=max(0,int(float(str(v.get()).replace(' ','').replace(',','.'))))
                except Exception:
                    messagebox.showwarning("Compteur véhicule","Saisissez un kilométrage numérique valide.");return
                self.conn.execute("UPDATE vehicles SET compteur=? WHERE code=?",(value,c));self._refresh_vehicle_remaining_values(c);self.conn.commit();self._audit("MODIFICATION","COMPTEUR VÉHICULE",c,f"Compteur : {value} km")
                if self.vehicle_form_vars["code"].get()==c:self.vehicle_form_vars["compteur"].set(str(value))
                e.configure(state="readonly");self.refresh_dashboard();self.schedule_web_sync();self.refresh_vehicles()
            def edit_card_counter(c=code,e=counter_entry):
                e.configure(state="normal");e.focus_set();e.selection_range(0,"end")
            tk.Button(counter_line,text="✎ Modifier",command=edit_card_counter,bg="#0879e8",fg="white",font=("Segoe UI",7,"bold"),relief="flat",padx=7,pady=3,cursor="hand2").pack(side="left",padx=(6,2))
            tk.Button(counter_line,text="✓ Enregistrer",command=save_card_counter,bg="#16a34a",fg="white",font=("Segoe UI",7,"bold"),relief="flat",padx=7,pady=3,cursor="hand2").pack(side="left",padx=2)
            counter_entry.bind("<Return>",save_card_counter)
            maint=tk.Frame(card,bg="#f8fbfd");maint.pack(fill="x",padx=8,pady=4)
            vals=(("Vidange",row["vidange_restant"] or 0,"#b45309"),("AdBlue",row["adblue_restant"] or 0,"#155eab"),("Chaîne",row["chaine_restant"] or 0,"#475569"))
            for j,(lab,val,col) in enumerate(vals):
                maint.grid_columnconfigure(j,weight=1);cell=tk.Frame(maint,bg="#f8fbfd",highlightbackground="#dbe7ef",highlightthickness=1);cell.grid(row=0,column=j,sticky="ew",padx=2)
                tk.Label(cell,text=lab,bg="#f8fbfd",fg=col,font=("Segoe UI",7,"bold")).pack();tk.Label(cell,text=f"{int(val):,} km".replace(',', ' '),bg="#f8fbfd",fg="#172b3a",font=("Segoe UI",7,"bold")).pack()
            quick=tk.Frame(card,bg="white");quick.pack(fill="x",padx=8,pady=(3,3))
            def qbtn(text,color,cmd):
                b=tk.Button(quick,text=text,bg=color,fg="white",activeforeground="white",font=("Segoe UI",7,"bold"),relief="flat",bd=0,padx=4,pady=5,cursor="hand2",command=cmd);b.pack(side="left",fill="x",expand=True,padx=1);return b
            qbtn("🔧 Entretien","#16a34a",lambda c=code:self._select_vehicle_and_maintenance(c))
            qbtn("📁 Documents","#f59e0b",lambda c=code:self.open_vehicle_documents(c))
            qbtn("▦ Crédit","#7c3aed",lambda:self.open_hbz_credit_app())
            qbtn("↶ Historique","#1683e0",lambda c=code:self._select_vehicle_history(c))
            qbtn("▤ Imprimer","#475569",lambda c=code:self._select_vehicle_and_preview(c))
            admin=tk.Frame(card,bg="white");admin.pack(fill="x",padx=9,pady=(3,8))
            admin_text=f"Assurance : {row['assurance_fin'] or '—'}   •   CT : {row['controle_technique'] or '—'}\nMise en service : {row['mise_circulation'] or '—'}   •   Retrait : {row['fin_service'] or '—'}"
            tk.Label(admin,text=admin_text,bg="white",fg="#50687a",font=("Segoe UI",7,"bold"),justify="left",anchor="w").pack(fill="x")
            def choose(_e=None,c=code):
                r=self.conn.execute("SELECT * FROM vehicles WHERE code=?",(c,)).fetchone()
                if r:self._populate_vehicle_form(r);self._render_vehicle_cards(rows)
            for w in (card,top,pic,info,maint,admin):w.bind("<Button-1>",choose)
            for parent in (info,maint,admin):
                for w in parent.winfo_children():w.bind("<Button-1>",choose)
        if not visible:tk.Label(self.vehicle_cards_inner,text="Aucun véhicule pour les filtres sélectionnés",bg="#f3f8fc",fg="#6b7f8e",font=("Segoe UI",11,"bold"),pady=35).grid(row=0,column=0,columnspan=3,sticky="ew")
        if hasattr(self,"vehicle_filter_count"):self.vehicle_filter_count.set(f"{len(visible)} véhicule(s) affiché(s)")

    def refresh_vehicles(self):
        if not hasattr(self, "vehicles_tree"): return
        self._refresh_vehicle_lifecycle_database()
        self._refresh_vehicle_remaining_values()
        self.conn.commit()
        self.vehicles_tree.delete(*self.vehicles_tree.get_children())
        selected_filter=(self.vehicle_search_service_filter.get() if hasattr(self,"vehicle_search_service_filter") else (self.vehicle_service_filter.get() if hasattr(self,"vehicle_service_filter") else "TOUS"))
        if hasattr(self,"vehicle_service_filter") and hasattr(self,"vehicle_search_service_filter"):
            self.vehicle_service_filter.set(selected_filter)
        displayed=0
        q=""  # V15 : la sélection se fait par la liste déroulante avec photos.
        matches=[]
        card_rows=[]
        for r in self.conn.execute("""SELECT * FROM vehicles ORDER BY modele"""):
            state="EN SERVICE" if r[6] else "HORS SERVICE"
            if selected_filter!="TOUS" and state!=selected_filter:continue
            if q and q not in f"{r[0]} {r[1]} {r[2]}".casefold():continue
            matches.append(r);card_rows.append(r)
            age = self._vehicle_age_months(r["mise_circulation"])
            if not r["service"]: row_tag="out"
            else: row_tag="service"
            self.vehicles_tree.insert("", "end", values=(r["code"],r["modele"],r["immatriculation"],r["chassis"],r["compteur"],r["prix"],age,r["fin_service"] or "",f"{int(r['reste_service_mois'] or 0)} mois",("EN SERVICE" if r["service"] else "HORS SERVICE")), tags=(row_tag,))
            displayed+=1
        if q and len(matches)==1:
            self._populate_vehicle_form(self.conn.execute("SELECT * FROM vehicles WHERE code=?",(matches[0][0],)).fetchone())
        self._render_vehicle_cards(card_rows)
        if hasattr(self,"vehicle_filter_count"):
            self.vehicle_filter_count.set(f"{displayed} véhicule(s) affiché(s)")
        if hasattr(self,"vehicle_metric_vars"):
            total=self.conn.execute("SELECT COUNT(*) FROM vehicles").fetchone()[0]
            service_count=self.conn.execute("SELECT COUNT(*) FROM vehicles WHERE service=1").fetchone()[0]
            selected=self.vehicle_form_vars["code"].get().strip() if hasattr(self,"vehicle_form_vars") else ""
            ca=self.conn.execute("SELECT COALESCE(SUM(montant),0) FROM contracts WHERE vehicle_code=?",(selected,)).fetchone()[0] if selected else 0
            fleet_ca=self.conn.execute("SELECT COALESCE(SUM(montant),0) FROM contracts").fetchone()[0]
            self.vehicle_metric_vars["total"].set(str(total));self.vehicle_metric_vars["service"].set(str(service_count));self.vehicle_metric_vars["out"].set(str(max(0,total-service_count)))
            self.vehicle_metric_vars["fleet_turnover"].set(f"{float(fleet_ca or 0):,.2f} MAD")
            self.vehicle_metric_vars["turnover"].set(f"{float(ca or 0):,.2f} MAD" if selected else "Sélectionnez")
        if hasattr(self, "vehicle_model_combo"):
            self.vehicle_model_combo["values"] = [r[0] for r in self.conn.execute("SELECT DISTINCT modele FROM vehicles WHERE modele<>'' ORDER BY modele")]

    def select_vehicle_tree(self, _event=None):
        selected = self.vehicles_tree.selection()
        if not selected: return
        code = self.vehicles_tree.item(selected[0], "values")[0]; row = self.conn.execute("SELECT * FROM vehicles WHERE code=?", (code,)).fetchone()
        if row:
            self._populate_vehicle_form(row)

    def _select_vehicle_code_v207(self, code):
        row=self.conn.execute("SELECT * FROM vehicles WHERE code=?",(str(code),)).fetchone()
        if row:self._populate_vehicle_form(row)
        return row

    def _select_vehicle_and_maintenance(self, code):
        if self._select_vehicle_code_v207(code): self.open_selected_vehicle_maintenance()

    def _select_vehicle_and_preview(self, code):
        if self._select_vehicle_code_v207(code): self.preview_vehicle()

    def _select_vehicle_history(self, code):
        row=self._select_vehicle_code_v207(code)
        if row and hasattr(self,"vehicle_history_vehicle"):
            self.vehicle_history_vehicle.set(f"{row['code']} | {row['modele']}");self.refresh_vehicle_location_history(str(code))

    def open_vehicle_documents(self, code=None):
        code=str(code or self.vehicle_form_vars["code"].get() or "").strip()
        if not code:return
        folder=APP_DIR / "documents_vehicules" / code
        folder.mkdir(parents=True,exist_ok=True)
        try:
            os.startfile(str(folder))
        except Exception:
            webbrowser.open(folder.as_uri())

    def _build_attachment_panel(self, parent, collection, reference_var, label, actions_parent=None):
        """Pièces jointes locales, consultables dans la fiche et archivées avec l'application."""
        large_preview=collection=="documents_cheques" and actions_parent is None
        area=tk.Frame(parent,bg="white")
        area.pack(fill="both" if large_preview else "x",expand=large_preview,padx=12,pady=(8,8))
        listing=tk.Listbox(area,height=4,exportselection=False,font=("Segoe UI",9),relief="flat",bg="#f1f7fc")
        listing.pack(side="left",fill="y" if large_preview else "both",expand=not large_preview,padx=(3,12))
        if large_preview:listing.configure(width=27,height=10,bg="#eef6ff",font=("Segoe UI",10))
        viewer=tk.Label(area,text="Sélectionnez un document pour le consulter ici.",bg="#f1f7fc",fg=NAVY,
                        width=35,height=5,wraplength=270,justify="center")
        viewer.pack(side="left",fill="both",expand=True)
        action_bg="#eef6fb" if actions_parent is not None else "white"
        actions=tk.Frame(actions_parent or parent,bg=action_bg)
        if actions_parent is None:actions.pack(side="bottom",fill="x",padx=12,pady=(8,14))
        else:actions.pack(side="left")
        files=[]
        def folder(create=False):
            code=reference_var.get().split("|",1)[0].strip()
            if not code:return None
            # La référence est limitée aux caractères qui ne peuvent quitter le dossier.
            safe=re.sub(r"[^\w.-]","_",code)
            if safe in (".","..") or not safe:return None
            path=APP_DIR/collection/safe
            if create:path.mkdir(parents=True,exist_ok=True)
            return path
        def refresh(*_):
            files.clear();listing.delete(0,"end");path=folder()
            if path and path.exists():
                files.extend(sorted((p for p in path.iterdir() if p.is_file()),key=lambda p:p.stat().st_mtime,reverse=True))
            for p in files:listing.insert("end",p.name)
            viewer.configure(image="",text=f"{len(files)} document(s) — {label}");viewer.image=None
            if large_preview and files:
                listing.selection_set(0);parent.after_idle(preview)
        def selected():
            indexes=listing.curselection()
            return files[indexes[0]] if indexes and indexes[0]<len(files) else None
        def preview(_event=None):
            path=selected()
            if path is None:return
            try:
                from PIL import Image,ImageTk
                if path.suffix.lower()==".pdf":
                    import fitz
                    document=fitz.open(str(path))
                    try:
                        pix=document[0].get_pixmap(matrix=fitz.Matrix(1.3,1.3),alpha=False)
                        im=Image.frombytes("RGB",(pix.width,pix.height),pix.samples)
                    finally:document.close()
                else:im=Image.open(path)
                if large_preview:
                    parent.update_idletasks()
                    bounds=(max(100,viewer.winfo_width()-32),max(80,viewer.winfo_height()-32))
                else:bounds=(350,175)
                im.thumbnail(bounds,Image.LANCZOS)
                photo=ImageTk.PhotoImage(im);viewer.configure(image=photo,text="");viewer.image=photo
            except Exception:
                viewer.configure(image="",text=f"{path.name}\nOuvrir pour consulter le document.");viewer.image=None
        def open_file(_event=None):
            path=selected()
            if path:
                try:
                    if sys.platform.startswith("win"):os.startfile(str(path))
                    else:webbrowser.open(path.as_uri())
                except Exception as exc:messagebox.showerror("Document",str(exc))
        def archive(source):
            destination_dir=folder(True)
            if not destination_dir:
                messagebox.showwarning("Documents",f"Sélectionnez d'abord un {label}.");return
            if collection=="documents_cheques" and not self.conn.execute("SELECT 1 FROM module_records WHERE module='checks' AND record_id=?",(reference_var.get().strip(),)).fetchone():
                messagebox.showwarning("Documents","Enregistrez d'abord le chèque ou la traite.");return
            source=Path(source)
            safe_name=re.sub(r"[^\w.-]","_",source.name)
            target=destination_dir/f"{datetime.now():%Y%m%d_%H%M%S_%f}_{safe_name}"
            if source.resolve()!=target.resolve():shutil.copy2(source,target)
            refresh();listing.selection_set(0);preview()
        def import_files():
            paths=filedialog.askopenfilenames(title=f"Documents du {label}",filetypes=[("Documents et images","*.pdf *.png *.jpg *.jpeg *.tif *.tiff *.bmp"),("Tous les fichiers","*.*")])
            for path in paths:archive(path)
        def add_file():
            path=filedialog.askopenfilename(title=f"Ajouter un document du {label}",filetypes=[("Documents et images","*.pdf *.png *.jpg *.jpeg *.tif *.tiff *.bmp"),("Tous les fichiers","*.*")])
            if path:archive(path)
        def scan():
            if not sys.platform.startswith("win"):
                messagebox.showinfo("Scanner","Le scan WIA nécessite Windows. Vous pouvez importer un fichier déjà numérisé.");return
            target_dir=folder(True)
            if not target_dir:messagebox.showwarning("Scanner",f"Sélectionnez d'abord un {label}.");return
            if collection=="documents_cheques" and not self.conn.execute("SELECT 1 FROM module_records WHERE module='checks' AND record_id=?",(reference_var.get().strip(),)).fetchone():
                messagebox.showwarning("Scanner","Enregistrez d'abord le chèque ou la traite.");return
            target=target_dir/f"scan_{datetime.now():%Y%m%d_%H%M%S_%f}.jpg"
            quoted=str(target).replace("'","''")
            ps=('$d=New-Object -ComObject WIA.CommonDialog; $i=$d.ShowAcquireImage(1,2,131072,"{B96B3CAE-0728-11D3-9D7B-0000F81EF32E}",$true,$true,$false); '+f"if($i){{$i.SaveFile('{quoted}')}}")
            result=subprocess.run(["powershell.exe","-NoProfile","-STA","-Command",ps],capture_output=True,text=True)
            if result.returncode or not target.exists():messagebox.showwarning("Scanner",result.stderr.strip() or "Numérisation annulée.");return
            refresh();listing.selection_set(0);preview()
        listing.bind("<<ListboxSelect>>",preview);listing.bind("<Double-1>",open_file)
        if actions_parent is not None:
            tk.Label(actions,text="📁  Documents  ",bg=action_bg,fg="#375571",font=("Segoe UI",8,"bold")).pack(side="left")
        for text_,cmd_,bg,fg in (("＋ Ajouter",add_file,"#e5f5ec","#196747"),("⇧ Importer",import_files,"#e5f0ff","#245d9d"),
                                 ("▣ Scanner",scan,"#ecebfa","#585595"),("◉ Ouvrir",open_file,"#fff1df","#986315"),
                                 ("↻ Actualiser",refresh,"#e9f1f5","#405f72")):
            tk.Button(actions,text=text_,command=cmd_,bg=bg,fg=fg,activebackground=bg,
                      activeforeground=fg,relief="flat",bd=0,padx=9 if actions_parent is not None else 12,pady=5,
                      cursor="hand2",font=("Segoe UI Symbol",10 if large_preview else 8,"bold")).pack(side="left",padx=3)
        if large_preview:
            tk.Button(actions,text="✕ Fermer",command=parent.destroy,bg="#193e68",fg="white",relief="flat",padx=16,pady=9,font=("Segoe UI",10,"bold")).pack(side="right")
            viewer.bind("<Configure>",lambda event:preview())
            viewer.bind("<Double-1>",open_file)
        refresh()
        if large_preview and files:
            listing.selection_set(0);parent.after_idle(preview)
        return refresh

    def open_selected_vehicle_maintenance(self):
        """Ouvre les fiches d'entretien du véhicule sélectionné, sans contrôle de conflit."""
        code=self.vehicle_form_vars["code"].get().strip() if hasattr(self,"vehicle_form_vars") else ""
        if not code:
            messagebox.showwarning("Fiches entretien","Sélectionnez d’abord un véhicule dans la liste.")
            return
        row=self.conn.execute("SELECT code,modele,immatriculation,service FROM vehicles WHERE code=?",(code,)).fetchone()
        if not row:return
        self.show_page("maintenance")
        def select_maintenance_vehicle():
            if "maintenance" not in getattr(self,"module_vars",{}):return
            if hasattr(self,"maintenance_service_filter"):
                self.maintenance_service_filter.set("En service" if int(row["service"] or 0) else "Hors service")
                self._apply_maintenance_global_filter()
            self.module_vars["maintenance"]["vehicle"].set(f"{row['code']} | {row['modele']} | {row['immatriculation']}")
            self._load_maintenance_vehicle_pro()
            if hasattr(self,"maintenance_search"):
                self.maintenance_search.set(str(row["code"]));self._refresh_maintenance_history_filtered()
        self.root.after(80,select_maintenance_vehicle)

    def _build_vehicle_maintenance_tab(self, parent):
        self.vehicle_maintenance_vars={key:tk.StringVar() for key in ('date','service','current_counter','mileage','product_km','next_mileage','remaining_km','product','amount','payment_method')}
        self.vehicle_maintenance_reference=None
        headline=tk.Frame(parent,bg='#f0ebff');headline.pack(fill='x',padx=9,pady=(10,7))
        tk.Label(headline,text='⚙  INTERVENTIONS DU VÉHICULE',bg='#f0ebff',fg='#604296',font=('Segoe UI',13,'bold')).pack(side='left',padx=12,pady=10)
        tk.Button(headline,text='↗  Fiche entretien détaillée',command=self.open_selected_vehicle_maintenance,
                  bg='#e3d7f7',fg='#604296',relief='flat',font=('Segoe UI',9,'bold'),padx=12,pady=6).pack(side='right',padx=10)
        quick=tk.Frame(parent,bg='#f7fbfe');quick.pack(fill='x',padx=9,pady=(0,7))
        for title,color in (('Vidange','#d98322'),('AdBlue','#1985cb'),('Chaîne','#ae4e81')):
            tk.Button(quick,text=f'＋  {title}',command=lambda kind=title:self._vehicle_maintenance_new(kind),
                      bg=color,fg='white',font=('Segoe UI',9,'bold'),relief='flat',pady=7).pack(side='left',fill='x',expand=True,padx=4)
        box=tk.Frame(parent,bg='white',highlightbackground='#d6cbe9',highlightthickness=1);box.pack(fill='x',padx=9,pady=(0,8))
        fields=(('Date de l’opération','date'),('Type d’intervention','service'),('Compteur actuel (km)','current_counter'),
                ('Km intervention','mileage'),('Km produit','product_km'),('Prochaine intervention (km)','next_mileage'),
                ('Kilométrage restant','remaining_km'),('Produit','product'),('Montant (MAD)','amount'),('Paiement','payment_method'))
        for col in range(5):box.grid_columnconfigure(col,weight=1,uniform='vehicle_maintenance')
        self.vehicle_maintenance_widgets={}
        for i,(title,key) in enumerate(fields):
            r,c=divmod(i,5);cell=tk.Frame(box,bg='white');cell.grid(row=r,column=c,sticky='ew',padx=9,pady=8)
            tk.Label(cell,text=title,bg='white',fg='#284461',font=('Segoe UI',8,'bold')).pack(anchor='w')
            if key=='service':widget=ttk.Combobox(cell,textvariable=self.vehicle_maintenance_vars[key],values=('Vidange','AdBlue','Chaîne'),state='readonly')
            elif key=='payment_method':widget=ttk.Combobox(cell,textvariable=self.vehicle_maintenance_vars[key],values=('ESPÈCES','CHÈQUE','À CRÉDIT'),state='readonly')
            else:widget=ttk.Entry(cell,textvariable=self.vehicle_maintenance_vars[key])
            widget.pack(fill='x',pady=(3,0),ipady=4);self.vehicle_maintenance_widgets[key]=widget
            if key=='date':self._attach_date_picker(widget,self.vehicle_maintenance_vars[key])
        self._vehicle_maintenance_calculating=False
        for key in ('current_counter','mileage','product_km'):
            self.vehicle_maintenance_vars[key].trace_add('write',lambda *_:self._vehicle_maintenance_calculate())
        for key in ('next_mileage','remaining_km'):
            self.vehicle_maintenance_widgets[key].bind('<FocusOut>',lambda _e,k=key:self._vehicle_maintenance_calculate(k))
        commands=tk.Frame(parent,bg='#f7fbfe');commands.pack(fill='x',padx=9,pady=(0,7))
        for label,command,color in (('＋  Nouvelle',self._vehicle_maintenance_new,'#229566'),
                                    ('▣  Enregistrer',self._vehicle_maintenance_save,'#2681c6'),
                                    ('✎  Modifier la sélection',self._vehicle_maintenance_edit_selected,'#df922c'),
                                    ('↻  Actualiser',self._refresh_vehicle_maintenance_tab,'#7452ad')):
            tk.Button(commands,text=label,command=command,bg=color,fg='white',font=('Segoe UI',8,'bold'),
                      relief='flat',padx=10,pady=7).pack(side='left',padx=4)
        tbl=tk.Frame(parent,bg='white',highlightbackground='#d6cbe9',highlightthickness=1);tbl.pack(fill='both',expand=True,padx=9,pady=(0,9))
        columns=('ref','date','service','counter','mileage','product','next','remaining','cost')
        tree=ttk.Treeview(tbl,columns=columns,show='headings',height=9)
        for key,label,width in zip(columns,('Référence','Date','Intervention','Compteur','Km intervention','Km produit','Prochaine','Restant','Montant MAD'),
                                   (126,92,105,95,103,90,95,90,105)):
            tree.heading(key,text=label);tree.column(key,width=width,anchor='center')
        tree.pack(side='left',fill='both',expand=True)
        sb=ttk.Scrollbar(tbl,orient='vertical',command=tree.yview);sb.pack(side='right',fill='y');tree.configure(yscrollcommand=sb.set)
        tree.bind('<Double-1>',lambda _e:self._vehicle_maintenance_edit_selected())
        self.vehicle_maintenance_tree=tree
        self._vehicle_maintenance_new()

    def _vehicle_maintenance_calculate(self,changed=None):
        if getattr(self,'_vehicle_maintenance_calculating',False):return
        self._vehicle_maintenance_calculating=True
        try:
            v=self.vehicle_maintenance_vars
            current=self._number(v['current_counter'].get());mileage=self._number(v['mileage'].get())
            if changed=='next_mileage':
                next_km=self._number(v['next_mileage'].get())
                v['product_km'].set(str(max(0,int(next_km-mileage))) if next_km else '')
            elif changed=='remaining_km':
                next_km=current+self._number(v['remaining_km'].get())
                v['next_mileage'].set(str(int(next_km)) if next_km else '')
                v['product_km'].set(str(max(0,int(next_km-mileage))) if next_km else '')
            else:
                product=self._number(v['product_km'].get())
                next_km=mileage+product
                v['next_mileage'].set(str(int(next_km)) if product>0 else '')
            v['remaining_km'].set(str(max(0,int(next_km-current))) if next_km else '')
        finally:self._vehicle_maintenance_calculating=False

    def _vehicle_maintenance_new(self,service='Vidange'):
        if not hasattr(self,'vehicle_maintenance_vars'):return
        self.vehicle_maintenance_reference=None
        v=self.vehicle_maintenance_vars
        for var in v.values():var.set('')
        current=self.vehicle_form_vars['compteur'].get().strip() or '0'
        v['date'].set(datetime.now().strftime('%d/%m/%Y'))
        v['service'].set(service);v['current_counter'].set(current);v['mileage'].set(current)
        v['amount'].set('0');v['payment_method'].set('ESPÈCES')

    def _refresh_vehicle_maintenance_tab(self):
        tree=getattr(self,'vehicle_maintenance_tree',None)
        if tree is None:return
        tree.delete(*tree.get_children())
        code=self.vehicle_form_vars['code'].get().strip()
        if not self.conn.execute('SELECT 1 FROM vehicles WHERE code=?',(code,)).fetchone():return
        counter=self._number(self.vehicle_form_vars['compteur'].get())
        for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='maintenance' ORDER BY created_at DESC,rowid DESC"):
            try:p=json.loads(raw)
            except (ValueError,TypeError):continue
            if str(p.get('vehicle','')).split('|')[0].strip()!=code:continue
            nxt=self._number(p.get('next_mileage'))
            tree.insert('','end',iid=rid,values=(rid,p.get('date'),p.get('service'),p.get('current_counter'),p.get('mileage'),
                        p.get('product_km'),p.get('next_mileage'),int(max(0,nxt-counter)) if nxt else '—',p.get('amount')))

    def _vehicle_maintenance_edit_selected(self):
        tree=self.vehicle_maintenance_tree; selected=tree.selection()
        if not selected:messagebox.showinfo('Entretien','Sélectionnez une intervention.');return
        row=self.conn.execute("SELECT payload FROM module_records WHERE module='maintenance' AND record_id=?",(selected[0],)).fetchone()
        if not row:return
        data=json.loads(row[0]);self.vehicle_maintenance_reference=selected[0]
        for key,var in self.vehicle_maintenance_vars.items():
            value=data.get(key,'')
            var.set(str(value) if value is not None else '')
        self._vehicle_maintenance_calculate()

    def _vehicle_maintenance_save(self):
        code=self.vehicle_form_vars['code'].get().strip()
        vehicle=self.conn.execute('SELECT code,modele,immatriculation FROM vehicles WHERE code=?',(code,)).fetchone()
        if not vehicle:messagebox.showwarning('Entretien','Sélectionnez un véhicule enregistré.');return
        v=self.vehicle_maintenance_vars
        for key in ('current_counter','mileage','product_km','amount'):
            if not re.fullmatch(r'\d+(?:[.,]\d+)?',v[key].get().strip()):
                messagebox.showwarning('Entretien',f'Valeur invalide : {key}.');return
        self._vehicle_maintenance_calculate()
        reference=self.vehicle_maintenance_reference or f"ENT{datetime.now():%Y%m%d%H%M%S%f}"
        old_row=self.conn.execute("SELECT payload FROM module_records WHERE module='maintenance' AND record_id=?",(reference,)).fetchone()
        old=json.loads(old_row[0]) if old_row else None
        payload=dict(old or {})
        payload.update({key:var.get().strip() for key,var in v.items()})
        payload.update({'reference':reference,'vehicle':f"{vehicle['code']} | {vehicle['modele']} | {vehicle['immatriculation']}",
                        'supplier':payload.get('supplier',''),'product_ref':payload.get('product_ref',''),
                        'quantity':payload.get('quantity') or '1','notes':payload.get('notes','')})
        error=self._validate_maintenance(payload)
        if error:messagebox.showwarning('Entretien',error);return
        stamp=datetime.now().isoformat(timespec='seconds')
        if old:
            self.conn.execute("UPDATE module_records SET payload=?,created_at=? WHERE module='maintenance' AND record_id=?",
                              (json.dumps(payload,ensure_ascii=False),stamp,reference))
        else:
            self.conn.execute('INSERT INTO module_records VALUES(?,?,?,?)',('maintenance',reference,json.dumps(payload,ensure_ascii=False),stamp))
        current_payload=dict(payload)
        if old and str(old.get('current_counter',''))==payload['current_counter']:current_payload.pop('current_counter',None)
        self._sync_maintenance_vehicle(current_payload);self._sync_maintenance_finance(reference,payload)
        self._audit('MODIFICATION' if old else 'CRÉATION','ENTRETIEN',reference)
        self.conn.commit();self.vehicle_maintenance_reference=reference
        actual_counter=self.conn.execute('SELECT compteur FROM vehicles WHERE code=?',(code,)).fetchone()
        if actual_counter:self.vehicle_form_vars['compteur'].set(str(actual_counter[0] or 0))
        self._refresh_vehicle_maintenance_tab();self.refresh_business_records('maintenance')
        messagebox.showinfo('Entretien',f"Intervention {reference} enregistrée.")

    def _populate_vehicle_form(self,row):
        for key in ("code", "modele", "immatriculation", "chassis", "compteur", "prix", "photo", "assurance_fin", "controle_technique", "mise_circulation", "fin_service", "age_mois", "reste_service_mois", "adblue_restant", "prochaine_vidange", "prochaine_chaine", "prochaine_adblue", "vidange_restant", "chaine_restant", "fuel_eighths", "remarque"):
            self.vehicle_form_vars[key].set(row[key] if row[key] is not None else "")
        self._refresh_vehicle_lifecycle_vars()
        self.vehicle_form_vars["service"].set("EN SERVICE" if row["service"] else "HORS SERVICE")
        if hasattr(self,"vehicle_quick_search"):
            self.vehicle_quick_search.set(f"{row['modele'] or 'Sans modèle'}  •  {row['code']}  •  {row['immatriculation'] or '-'}")
        self._refresh_vehicle_service_badge()
        if hasattr(self,"vehicle_photo_title_var"):
            model=(row["modele"] or "VÉHICULE").strip()
            brand=model.split()[0].upper() if model else "VÉHICULE"
            self.vehicle_photo_title_var.set(brand)
        # La fiche Véhicules alimente les champs du contrat sans ouvrir le
        # dialogue de disponibilité. Ce contrôle reste actif dans Location.
        self.vars["vehicle_code"].set(row["code"] or "");self.load_vehicle(check_conflict=False)
        self._display_vehicle_photo(row["photo"] or "");self.refresh_selected_vehicle_status();self._set_sidebar_vehicle_photo()
        if hasattr(self,"vehicle_documents_refresh"):self.vehicle_documents_refresh()
        if hasattr(self,"vehicle_history_vehicle"):
            self.vehicle_history_vehicle.set(f"{row['code']} | {row['modele']}");self.refresh_vehicle_location_history(row["code"])
        if hasattr(self,"vehicle_metric_vars"):
            ca=self.conn.execute("SELECT COALESCE(SUM(montant),0) FROM contracts WHERE vehicle_code=?",(row["code"],)).fetchone()[0]
            self.vehicle_metric_vars["turnover"].set(f"{float(ca or 0):,.2f} MAD")
        if hasattr(self,'vehicle_maintenance_tree'):
            self._vehicle_maintenance_new();self._refresh_vehicle_maintenance_tab()

    def load_vehicle_form_by_model(self,_event=None):
        raw=self.vehicle_form_vars["modele"].get().split("|",1)[0].strip()
        row=self.conn.execute("SELECT * FROM vehicles WHERE UPPER(modele)=UPPER(?) OR code=? OR immatriculation=? ORDER BY service DESC,code LIMIT 1",(raw,raw,raw)).fetchone()
        if row:self._populate_vehicle_form(row)

    def _vehicle_model_autofill(self,event=None):
        if event and event.keysym in ("Up","Down","Left","Right","Escape","Tab","Return"):return
        raw=self.vehicle_form_vars["modele"].get().strip();rows=self.conn.execute("SELECT code,modele,immatriculation FROM vehicles WHERE ?='' OR modele LIKE ? OR code LIKE ? OR immatriculation LIKE ? ORDER BY modele,code LIMIT 100",(raw,f"%{raw}%",f"%{raw}%",f"%{raw}%")).fetchall()
        self.vehicle_model_combo.configure(values=[f"{r['modele']} | {r['code']} | {r['immatriculation']}" for r in rows])
        exact=self.conn.execute("SELECT * FROM vehicles WHERE UPPER(modele)=UPPER(?) OR code=? OR immatriculation=? ORDER BY service DESC,code LIMIT 1",(raw,raw,raw)).fetchone()
        if exact:self._populate_vehicle_form(exact)

    @staticmethod
    def _vehicle_age_months(value):
        """Calcule l'âge d'un véhicule en mois depuis sa mise en circulation."""
        if not value:
            return 0
        try:
            start = datetime.strptime(str(value).strip(), "%d/%m/%Y").date()
        except ValueError:
            try:
                start = datetime.fromisoformat(str(value).strip()).date()
            except ValueError:
                return 0
        today = datetime.now().date()
        months = (today.year - start.year) * 12 + today.month - start.month
        if today.day < start.day:
            months -= 1
        return max(0, months)

    @staticmethod
    def _vehicle_retirement_date(value, lifetime_months=60):
        """Retourne la date de retrait calculée après la durée de vie prévue."""
        if not value:
            return ""
        try:
            start=datetime.strptime(str(value).strip(),"%d/%m/%Y").date()
        except ValueError:
            try:start=datetime.fromisoformat(str(value).strip()).date()
            except ValueError:return ""
        total=start.year*12+(start.month-1)+int(lifetime_months)
        year,month=divmod(total,12);month+=1
        day=min(start.day,monthcalendar.monthrange(year,month)[1])
        return datetime(year,month,day).strftime("%d/%m/%Y")

    def _refresh_vehicle_lifecycle_vars(self):
        """Calcule âge, retrait à 60 mois et service restant dans la fiche véhicule."""
        if not hasattr(self,"vehicle_form_vars"):return
        start=self.vehicle_form_vars["mise_circulation"].get().strip()
        age=self._vehicle_age_months(start) if self._parse_french_date(start) else 0
        self.vehicle_form_vars["age_mois"].set(str(age))
        self.vehicle_form_vars["reste_service_mois"].set(str(max(0,60-age)))
        self.vehicle_form_vars["fin_service"].set(self._vehicle_retirement_date(start,60))

    def _refresh_vehicle_lifecycle_database(self, code=""):
        """Maintient les valeurs calculées de cycle de vie dans la table véhicules."""
        rows=self.conn.execute("SELECT code,mise_circulation FROM vehicles"+(" WHERE code=?" if code else ""),(code,) if code else ()).fetchall()
        for row in rows:
            start=row["mise_circulation"] or "";age=self._vehicle_age_months(start) if self._parse_french_date(start) else 0
            self.conn.execute("UPDATE vehicles SET fin_service=?,age_mois=?,reste_service_mois=? WHERE code=?",
                (self._vehicle_retirement_date(start,60),age,max(0,60-age),row["code"]))

    def _refresh_vehicle_remaining_values(self, code=""):
        """Recalcule les kilomètres restants depuis le compteur actuel."""
        where=" WHERE code=?" if code else "";params=(str(code),) if code else ()
        self.conn.execute(f"""UPDATE vehicles SET
            vidange_restant=CASE WHEN prochaine_vidange>0 THEN MAX(prochaine_vidange-compteur,0) ELSE 0 END,
            chaine_restant=CASE WHEN prochaine_chaine>0 THEN MAX(prochaine_chaine-compteur,0) ELSE 0 END,
            adblue_restant=CASE WHEN prochaine_adblue>0 THEN MAX(prochaine_adblue-compteur,0) ELSE adblue_restant END
            {where}""",params)

