        tk.Button(fleet_bar,text="✎  Modifier",command=lambda:save_record(),bg="#f59e0b",fg="white",activebackground="#c97905",activeforeground="white",font=("Segoe UI",9,"bold"),relief="flat",bd=0,padx=13,pady=7,cursor="hand2").pack(side="left",padx=4,pady=7)
