    def _display_vehicle_photo(self, path):
        if not hasattr(self, "vehicle_photo_label"): return
        self.vehicle_photo_image = None
        code=self.vehicle_form_vars.get("code").get().strip() if hasattr(self,"vehicle_form_vars") else ""
        resolved=self._resolve_vehicle_photo_path(path,code) if hasattr(self,"_resolve_vehicle_photo_path") else None
        path=str(resolved) if resolved else str(path or "")
        if not path or not Path(path).exists():
            self.vehicle_photo_label.configure(text="🚘\nAucune photo", image="")
            return
        try:
            from PIL import Image, ImageTk
            image = Image.open(path); image.thumbnail((220, 125))
            self.vehicle_photo_image = ImageTk.PhotoImage(image)
            self.vehicle_photo_label.configure(text="", image=self.vehicle_photo_image)
        except Exception:
            self.vehicle_photo_label.configure(text=f"🚘\n{Path(path).name}", image="")

    def _set_sidebar_vehicle_photo(self, photo_override=None):
        if not hasattr(self, "sidebar_vehicle_photo"):
            return
        code=self.vehicle_form_vars.get("code").get().strip() if hasattr(self,"vehicle_form_vars") else ""
        if not code:
            self.sidebar_vehicle_photo.configure(text="🚘\nAucune photo", image="")
            self.sidebar_vehicle_caption.configure(text="Sélectionnez un véhicule")
            return
        row=self.conn.execute("SELECT modele,photo FROM vehicles WHERE code=?",(code,)).fetchone()
        if not row:
            self.sidebar_vehicle_photo.configure(text="🚘\nAucune photo", image="");self.sidebar_vehicle_caption.configure(text=code);return
        photo_path=str(photo_override or row["photo"] or "").strip()
        if photo_path and Path(photo_path).exists():
            try:
                from PIL import Image, ImageTk
                image=Image.open(photo_path); image.thumbnail((170, 90))
                self._sidebar_vehicle_image=ImageTk.PhotoImage(image)
                self.sidebar_vehicle_photo.configure(image=self._sidebar_vehicle_image,text="")
            except Exception:
                self.sidebar_vehicle_photo.configure(text=f"🚘\n{Path(photo_path).name}",image="")
        else:
            self.sidebar_vehicle_photo.configure(text="🚘\nAucune photo",image="")
        self.sidebar_vehicle_caption.configure(text=f"{code} — {row['modele'] or 'Véhicule'}")

    def _last_vehicle_contract_conflict(self, code, start_date, end_date, current="", start_time="00:00", end_time="23:59", reservation_days=False):
        """Retourne uniquement un chevauchement réel de date + heure.

        Un contrat annulé, un retour confirmé/anticipé, ou un contrat dont
        l'heure de retour est antérieure ou égale au nouveau départ ne bloque
        jamais le véhicule.
        """
        rows=self.conn.execute(
            """SELECT numero,date_depart,heure_depart,date_retour,heure_retour,
                      return_status,actual_return_date,actual_return_time,created_at
               FROM contracts
               WHERE vehicle_code=? AND numero<>?
               ORDER BY created_at DESC""", (code,current)).fetchall()
        def at(day, clock, fallback):
            if not day: return None
            try:
                d=self._parse_french_date(day)
                if not d: return None
                t=str(clock or fallback).strip() or fallback
                hh,mm=(t.split(":",1)+["00"])[:2]
                return d.replace(hour=int(hh),minute=int(mm),second=0,microsecond=0)
            except Exception:
                return None
        requested_start=at(start_date.strftime("%d/%m/%Y") if isinstance(start_date,datetime) else start_date,start_time,"00:00")
        requested_end=at(end_date.strftime("%d/%m/%Y") if isinstance(end_date,datetime) else end_date,end_time,"23:59")
        if not requested_start or not requested_end: return None
        candidates=[]
        for row in rows:
            status=str(row["return_status"] or "").strip().upper()
            if self._is_returned_contract(status):
                continue
            occupied_start=at(row["date_depart"],row["heure_depart"],"00:00")
            occupied_end=(datetime.max if self._is_confirmed_delay(status) else
                          at(row["actual_return_date"] or row["date_retour"],
                             row["actual_return_time"] or row["heure_retour"],"23:59"))
            if not occupied_start or not occupied_end: continue
            # Réservations : le jour du retour est disponible, quelle que soit l'heure.
            if reservation_days:
                if requested_start.date() >= occupied_end.date() or requested_end.date() <= occupied_start.date():
                    continue
            # Locations : conserver le contrôle précis des heures.
            elif requested_start >= occupied_end or requested_end <= occupied_start:
                continue
            candidates.append((occupied_end,occupied_start,row))
        if not candidates: return None
        candidates.sort(key=lambda item:(item[0],item[1]), reverse=True)
        return candidates[0][2]

    def _vehicle_free_on(self,code,target):
        target_text=target.strftime("%d/%m/%Y")
        clash=self._last_vehicle_contract_conflict(code,target,target)
        if clash:return False,f"contrat {clash['numero']}"
        for record_id,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='reservations'"):
            try:p=json.loads(raw)
            except json.JSONDecodeError:continue
            if str(p.get("vehicle","")).split("|")[0].strip()!=code or str(p.get("status","")).upper() in ("ANNULÉ","ANNULE","TERMINÉ","TERMINE"):continue
            start=self._parse_french_date(p.get("start_date"));end=self._parse_french_date(p.get("end_date"))
            if start and end and start<=target<=end:return False,f"réservation {record_id}"
        return True,target_text

    def refresh_selected_vehicle_status(self):
        """Actualise seulement les alertes techniques de la fiche véhicule."""
        if not hasattr(self,"vehicle_alert_var"):return
        code=self.vehicle_form_vars["code"].get().strip()
        if not code:return
        today=datetime.now().replace(hour=0,minute=0,second=0,microsecond=0)
        alerts=[];current=int(self._number(self.vehicle_form_vars["compteur"].get()))
        for key,label in (("assurance_fin","Assurance"),("controle_technique","Contrôle technique")):
            due=self._parse_french_date(self.vehicle_form_vars[key].get())
            if due and due<=today+timedelta(days=30):alerts.append(f"{label} {self.vehicle_form_vars[key].get()}")
        oil=int(self._number(self.vehicle_form_vars["vidange_restant"].get()))
        if oil and oil<=500:alerts.append(f"Vidange dans {oil} km")
        chain=int(self._number(self.vehicle_form_vars["chaine_restant"].get()))
        if chain and chain<=1000:alerts.append(f"Chaîne dans {chain} km")
        adblue=int(self._number(self.vehicle_form_vars["adblue_restant"].get()))
        if adblue and adblue<=500:alerts.append(f"AdBlue {adblue} km")
        self.vehicle_alert_var.set("Alertes : "+(" • ".join(alerts) if alerts else "aucune alerte proche"))
        if hasattr(self,"vehicle_maintenance_text"):
            self.vehicle_maintenance_text.set(f"Vidange restante : {oil:,} km\nChaîne restante : {chain:,} km\nAdBlue restant : {adblue:,} km\nCycle de vie : {self.vehicle_form_vars['reste_service_mois'].get() or '0'} mois")
        if hasattr(self,"vehicle_remaining_card_vars"):
            self.vehicle_remaining_card_vars["vidange"].set(f"{oil:,} km".replace(","," "))
            self.vehicle_remaining_card_vars["chaine"].set(f"{chain:,} km".replace(","," "))
            self.vehicle_remaining_card_vars["adblue"].set(f"{adblue:,} km".replace(","," "))

    def preview_vehicle(self):
        p={key:html.escape(var.get()) for key,var in self.vehicle_form_vars.items()}
        if not p["code"]:messagebox.showwarning("Véhicule","Sélectionnez un véhicule.");return
        contracts=self.conn.execute("SELECT COUNT(*),COALESCE(SUM(montant),0),COALESCE(SUM(km_retour-km_depart),0) FROM contracts WHERE vehicle_code=?",(self.vehicle_form_vars["code"].get(),)).fetchone()
        maintenance=[]
        for record_id,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='maintenance'"):
            try:item=json.loads(raw)
            except json.JSONDecodeError:continue
            if str(item.get("vehicle","")).split("|")[0].strip()==self.vehicle_form_vars["code"].get():maintenance.append((record_id,item))
        maintenance_rows="".join(f"<tr><td>{html.escape(str(item.get('date','')))}</td><td>{html.escape(str(item.get('service','')))}</td><td>{html.escape(str(item.get('mileage','')))}</td><td>{html.escape(str(item.get('cost','')))} MAD</td></tr>" for _ref,item in maintenance[:12]) or "<tr><td colspan='4'>Aucun entretien enregistré</td></tr>"
        company=html.escape(self._get_setting("company_name","HBZ Rent Car"))
        content=f"""<!doctype html><html><head><meta charset='utf-8'><title>Fiche véhicule {p['code']}</title><style>@page{{size:A4;margin:12mm}}body{{font:15px/1.45 Arial;color:#1d3548}}h1{{color:#0e5a91;border-bottom:4px solid #168bd0;padding-bottom:8px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}}.card{{border:1.5px solid #a9bfce;border-radius:13px;padding:13px}}.metric{{background:#0e5a91;color:white;text-align:center;font-size:18px}}table{{width:100%;border-collapse:collapse;margin-top:16px}}th{{background:#0e5a91;color:white;padding:8px}}td{{border-bottom:1px solid #dce6ed;padding:7px}}</style></head><body>{self._print_logo_html()}<h1>FICHE VÉHICULE — {company}</h1><div class='grid'><div class='card'><b>IDENTITÉ</b><p>Code : {p['code']}<br>Modèle : {p['modele']}<br>Immatriculation : {p['immatriculation']}<br>Châssis : {p['chassis']}</p></div><div class='card'><b>EXPLOITATION</b><p>Compteur : {p['compteur']} km<br>Prix/jour : {p['prix']} MAD<br>État : {p['service']}</p></div><div class='card metric'><b>{contracts[0]}</b><br>LOCATION(S)<br><b>{float(contracts[1] or 0):.2f} MAD</b><br>Chiffre d’affaires</div></div><h2>Historique entretien</h2><table><tr><th>Date</th><th>Intervention</th><th>Compteur</th><th>Coût</th></tr>{maintenance_rows}</table></body></html>"""
        EXPORT_DIR.mkdir(exist_ok=True);path=EXPORT_DIR/f"Fiche_Vehicule_{self.vehicle_form_vars['code'].get()}.html";path.write_text(content,encoding="utf-8");webbrowser.open(path.as_uri())

    def _build_receivables_page_legacy(self):
        """Créances calculées depuis les contrats, avec règlements et situation client."""
        page=self._new_page("receivables")
        self._page_title(page,"GESTION DES CRÉANCES","Soldes clients, règlements et suivi par contrat")
        self._action_bar(page,(
            ("↻ Actualiser",self.refresh_receivables),
            ("＋ Enregistrer un règlement",self.open_receivable_payment),
            ("▦ Situation du client",self.open_client_statement),
            ("⇧ Exporter",self.export_receivables),
            ("▣ Imprimer",self.open_client_statement),
        ))
        metrics=tk.Frame(page,bg=BG);metrics.pack(fill="x",padx=16,pady=(0,7))
        self.receivable_metric_vars={key:tk.StringVar(value="0,00 MAD") for key in ("total","paid","balance")}
        for col,(title,key,color) in enumerate((("MONTANT FACTURÉ","total",GREEN),("TOTAL RÉGLÉ","paid",BLUE),("RESTE À PAYER","balance",RED))):
            card=tk.Frame(metrics,bg=color);card.grid(row=0,column=col,sticky="ew",padx=(0 if col==0 else 5,0),pady=2)
            tk.Label(card,text=title,bg=color,fg="white",font=("Segoe UI",8,"bold")).pack(pady=(9,2))
