    def _apply_maintenance_global_filter(self, _event=None):
        """Applique En service/Hors service/Tous à toute la page Entretien."""
        mode=getattr(self,"maintenance_service_filter",None)
        mode=mode.get() if mode else "En service"
        if mode=="En service": where="WHERE service=1"
        elif mode=="Hors service": where="WHERE service=0"
        else: where=""
        rows=self.conn.execute(f"SELECT code,modele,immatriculation FROM vehicles {where} ORDER BY modele,code").fetchall()
        choices=[f"{r['code']} | {r['modele']} | {r['immatriculation']}" for r in rows]
        if hasattr(self,"maintenance_vehicle_top"): self.maintenance_vehicle_top.configure(values=choices)
        vals=self.module_vars.get("maintenance",{})
        current=vals.get("vehicle").get().split("|")[0].strip() if vals.get("vehicle") else ""
        allowed={r["code"] for r in rows}
        if current and current not in allowed:
            vals["vehicle"].set("")
            if "current_counter" in vals: vals["current_counter"].set("")
            self.maintenance_vehicle_info.set("Choisissez un véhicule")
            try:self.maintenance_photo.configure(image="",text="🚗")
            except Exception:pass
        self._refresh_maintenance_history_filtered()

    def _refresh_maintenance_history_filtered(self):
        tree=getattr(self,"module_trees",{}).get("maintenance")
        if tree is None:return
        for item in tree.get_children():tree.delete(item)
        mode=getattr(self,"maintenance_service_filter",None); mode=mode.get() if mode else "En service"
        allowed=None
        if mode!="Tous":
            flag=1 if mode=="En service" else 0
            allowed={r["code"] for r in self.conn.execute("SELECT code FROM vehicles WHERE service=?",(flag,))}
        q=getattr(self,"maintenance_search",None);q=(q.get().strip().lower() if q else "")
        fields=self.module_fields.get("maintenance",())
        rows=self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='maintenance' ORDER BY created_at DESC").fetchall()
        visible_count=0;visible_cost=0.0;visible_vehicles=set();critical_count=0
        for rec in rows:
            try:data=json.loads(rec["payload"])
            except Exception:continue
            code=str(data.get("vehicle","")).split("|")[0].strip()
            if allowed is not None and code not in allowed:continue
            vals=[str(data.get(k,"")) for _lab,k in fields]
            typ=str(data.get("service","")).strip(); tf=getattr(self,"maintenance_type_filter",None); wanted=tf.get() if tf else "Tous"
            if wanted!="Tous" and typ.casefold()!=wanted.casefold(): continue
            if q and q not in " ".join(vals).lower():continue
            visible_count+=1;visible_cost+=max(0.0,self._number(data.get("amount")))
            if code:visible_vehicles.add(code)
            next_km=self._number(data.get("next_mileage"));remaining=self._number(data.get("remaining_km"))
            if next_km>0 and remaining<=1000:critical_count+=1
            # Badge visuel coloré par type dans la colonne Type.
            badge={"adblue":"🔵 AdBlue","vidange":"🟠 Vidange","chaîne":"🟣 Chaîne","chaine":"🟣 Chaîne","freins":"🔴 Freins"}.get(typ.casefold(),typ)
            try: vals[[k for _l,k in fields].index("service")]=badge
            except ValueError: pass
            tree.insert("","end",iid=rec["record_id"],values=vals+["✎ Modifier   🗑 Supprimer"])
        summary=getattr(self,"maintenance_summary_vars",{})
        if summary:
            summary["interventions"].set(str(visible_count));summary["cost"].set(f"{visible_cost:,.2f} MAD")
            summary["vehicles"].set(str(len(visible_vehicles)));summary["critical"].set(str(critical_count))
        vals=self.module_vars.get("maintenance",{})
        raw=vals.get("vehicle").get() if vals.get("vehicle") else ""
        code=raw.split("|")[0].strip()
        if code:self._refresh_maintenance_service_cards(code)

    def _resolve_vehicle_photo_path(self, raw_path, vehicle_code=""):
        """V205 — retrouve la photo même si la base contient un ancien chemin absolu."""
        raw=str(raw_path or "").strip(); code=str(vehicle_code or "").strip()
        names=[]
        if raw:
            # Un ancien chemin Windows reste exploitable après déplacement du dossier.
            normalized=raw.replace("\\","/")
            names.append(normalized.rsplit("/",1)[-1])
        if code:
            names.extend([f"vehicule_{code}.png",f"vehicule_{code}.jpg",f"vehicule_{code}.jpeg",f"vehicle_{code}.png",f"vehicle_{code}.jpg"])
        candidates=[]
        if raw:candidates.append(Path(raw))
        for name in dict.fromkeys(n for n in names if n):
            candidates.extend([APP_DIR/"assets"/"vehicle_photos"/name,APP_DIR/"assets"/name,APP_DIR/name])
        for candidate in candidates:
            try:
                if candidate.exists() and candidate.is_file():return candidate
            except Exception:pass
        return None

    def _load_maintenance_vehicle_pro(self, _event=None):
        values=self.module_vars.get("maintenance",{}); raw=values.get("vehicle").get() if values.get("vehicle") else "";code=raw.split("|")[0].strip()
        row=self.conn.execute("SELECT * FROM vehicles WHERE code=?",(code,)).fetchone() if code else None
        if not row:return
        values["vehicle"].set(row["code"])
        values["current_counter"].set(str(row["compteur"] or 0))
        self.maintenance_vehicle_info.set(f"{row['modele']}\nImmatriculation : {row['immatriculation']}\nCode : {row['code']}   •   Kilométrage : {row['compteur'] or 0} km")
        try:
            from PIL import Image,ImageTk,ImageOps
            path=self._resolve_vehicle_photo_path(row["photo"] or "", row["code"])
            if path:
                with Image.open(path) as original:
                    im=ImageOps.exif_transpose(original).convert("RGB")
                im.thumbnail((160,96),Image.Resampling.LANCZOS)
                self._maintenance_photo_image=ImageTk.PhotoImage(im)
                self.maintenance_photo.configure(image=self._maintenance_photo_image,text="")
            else:self.maintenance_photo.configure(image="",text="🚗")
        except Exception:self.maintenance_photo.configure(image="",text="🚗")
        self._calculate_maintenance_km()
        self._refresh_maintenance_service_cards(row["code"])

    def _maintenance_open_new_intervention(self, service):
        """Ouvre Nouvelle intervention depuis une carte en conservant le véhicule sélectionné."""
        vals=self.module_vars.get("maintenance",{})
        raw=vals.get("vehicle").get() if vals.get("vehicle") else ""
        code=raw.split("|")[0].strip()
        if not code:
            messagebox.showwarning("Entretien véhicule","Sélectionnez d’abord un véhicule.")
            return
        row=self.conn.execute("SELECT code,modele,immatriculation FROM vehicles WHERE code=?",(code,)).fetchone()
        self.new_business_record("maintenance")
        if row:
            vals["vehicle"].set(f"{row['code']} | {row['modele']} | {row['immatriculation']}")
            self._load_maintenance_vehicle_pro()
        vals["service"].set(service)
        try:self.maintenance_status.set(f"Nouvelle intervention {service} — complétez puis cliquez sur Enregistrer")
        except Exception:pass
        try:
            # Amène le formulaire dans la zone visible, sans changer de page.
            self.pages["maintenance"].update_idletasks()
        except Exception:pass

    def _refresh_maintenance_service_cards(self, code):
        """Alimente Vidange / AdBlue / Chaîne avec la dernière intervention du véhicule."""
        cards=getattr(self,"maintenance_service_card_vars",{})
        if not cards:return
        vehicle=self.conn.execute("SELECT compteur FROM vehicles WHERE code=?",(code,)).fetchone()
        current=int(self._number(vehicle["compteur"])) if vehicle else 0
        latest={}
        rows=self.conn.execute("SELECT payload FROM module_records WHERE module='maintenance' ORDER BY created_at DESC,rowid DESC").fetchall()
        for rec in rows:
            try:item=json.loads(rec["payload"])
            except Exception:continue
            if str(item.get("vehicle","")).split("|")[0].strip()!=code:continue
            key=str(item.get("service","")).strip().casefold().replace("î","i")
            if key in cards and key not in latest:latest[key]=item
        for key,vars_ in cards.items():
            item=latest.get(key)
            if not item:
                for k in vars_:vars_[k].set("—")
                continue
            nxt=int(self._number(item.get("next_mileage")))
            remaining=max(0,nxt-current) if nxt else int(self._number(item.get("remaining_km")))
            vars_["date"].set(str(item.get("date") or "—"))
            vars_["mileage"].set(f"{int(self._number(item.get('mileage'))):,} km".replace(","," "))
            vars_["next"].set((f"{nxt:,} km".replace(","," ")) if nxt else "—")
            vars_["remaining"].set((f"{remaining:,} km".replace(","," ")) if nxt or remaining else "—")

    def _maintenance_choose_photo(self):
        """Ajoute/remplace la photo du véhicule sélectionné depuis un dossier du PC."""
        vals=self.module_vars.get("maintenance",{}); raw=vals.get("vehicle").get() if vals.get("vehicle") else ""; code=raw.split("|")[0].strip()
        if not code:
            messagebox.showwarning("Entretien véhicule","Sélectionnez d’abord un véhicule."); return
        path=filedialog.askopenfilename(title="Choisir la photo du véhicule",filetypes=[("Images","*.png *.jpg *.jpeg *.webp *.bmp"),("Tous les fichiers","*.*")])
        if not path:return
        source=Path(path); destination_dir=APP_DIR/"assets"/"vehicle_photos"; destination_dir.mkdir(parents=True,exist_ok=True)
        safe_name=re.sub(r"[^0-9A-Za-z_.-]+","_",f"{code}_{source.name}")
        destination=destination_dir/safe_name
        try:shutil.copy2(source,destination)
        except Exception:destination=source
        stored=str(destination.relative_to(APP_DIR)) if str(destination).startswith(str(APP_DIR)) else str(destination)
        self.conn.execute("UPDATE vehicles SET photo=? WHERE code=?",(stored,code)); self.conn.commit(); self._load_maintenance_vehicle_pro(); self.refresh_vehicles()

    def _maintenance_history_action_click(self,event):
        tree=self.module_trees.get("maintenance");
        if tree is None:return
        action_column=f"#{len(self.module_fields.get('maintenance',()))+1}"
        if tree.identify_region(event.x,event.y)!="cell" or tree.identify_column(event.x)!=action_column: return
        iid=tree.identify_row(event.y)
        if not iid:return
        tree.selection_set(iid); self.select_business_record("maintenance")
        box=tree.bbox(iid,"actions")
        if not box:return
        rel=event.x-box[0]
        if rel < box[2]*0.48:
            # Modifier : charge la ligne dans le formulaire ; l'utilisateur valide avec le bouton Modifier.
            try:self.maintenance_status.set("Intervention chargée : modifiez les champs puis cliquez sur Modifier")
            except Exception:pass
        else: self.delete_business_record("maintenance")

