    def _sync_maintenance_vehicle(self,payload):
        """Répercute l'intervention validée dans la fiche véhicule et ses alertes."""
        code=str(payload.get('vehicle','')).split('|')[0].strip()
        if not code:return
        # Le compteur saisi dans Entretien est autorisé et devient le compteur courant du véhicule.
        if "current_counter" in payload and str(payload.get("current_counter","")).strip() != "":
            counter=max(0,int(self._number(payload.get("current_counter"))))
            self.conn.execute("UPDATE vehicles SET compteur=? WHERE code=?",(counter,code))
        self._resync_vehicle_maintenance(code)
        self.refresh_vehicles();self.refresh_dashboard()

    def _resync_vehicle_maintenance(self,code):
        """Centralise les dernières interventions de chaque type dans vehicles."""
        code=str(code or '').strip()
        vehicle=self.conn.execute("SELECT compteur FROM vehicles WHERE code=?",(code,)).fetchone()
        if not vehicle:return
        rows=self.conn.execute("SELECT payload FROM module_records WHERE module='maintenance' ORDER BY created_at DESC,rowid DESC").fetchall()
        latest=None;by_service={}
        for rec in rows:
            try:item=json.loads(rec['payload'])
            except (TypeError,json.JSONDecodeError):continue
            if str(item.get('vehicle','')).split('|')[0].strip()!=code:continue
            if latest is None:latest=item
            key=str(item.get('service','')).strip().casefold().replace('î','i')
            if key not in by_service:by_service[key]=item
        current=int(self._number(vehicle['compteur']))
        def target(*names):
            for name in names:
                item=by_service.get(name)
                if item:return int(self._number(item.get('next_mileage')))
            return 0
        oil=target('vidange');chain=target('chaîne','chaine');adblue=target('adblue')
        self.conn.execute("""UPDATE vehicles SET entretien_date=?,entretien_type=?,entretien_km_intervention=?,
            entretien_km_produit=?,entretien_prochaine=?,entretien_km_restant=?,prochaine_vidange=?,prochaine_chaine=?,
            prochaine_adblue=?,vidange_restant=?,chaine_restant=?,adblue_restant=? WHERE code=?""",
            ((latest or {}).get('date',''),(latest or {}).get('service',''),int(self._number((latest or {}).get('mileage'))),
             int(self._number((latest or {}).get('product_km'))),int(self._number((latest or {}).get('next_mileage'))),
             max(0,int(self._number((latest or {}).get('next_mileage')))-current) if latest else 0,
             oil,chain,adblue,max(0,oil-current) if oil else 0,max(0,chain-current) if chain else 0,
             max(0,adblue-current) if adblue else 0,code))

    def _sync_maintenance_finance(self,record_id,payload):
        """Crée ou retire la dette fournisseur liée à un entretien à crédit."""
        purchase_id=f"ENT-{record_id}"
        self.conn.execute("DELETE FROM module_records WHERE module='supplier_purchases' AND record_id=?",(purchase_id,))
        mode=str(payload.get('payment_method','')).strip().upper()
        if mode!="À CRÉDIT":return
        supplier_raw=str(payload.get('supplier','')).strip();supplier=supplier_raw.split('|')[0].strip()
        supplier_name=supplier_raw.split('|',1)[1].strip() if '|' in supplier_raw else supplier_raw
        amount=max(0.0,self._number(payload.get('amount')))
        purchase={"reference":purchase_id,"date":payload.get('date',''),"invoice":record_id,
            "category":"ENTRETIEN / MÉCANIQUE","description":f"{payload.get('service','Entretien')} — {payload.get('vehicle','')}",
            "quantity":"1","unit_price":f"{amount:.2f}","total":f"{amount:.2f}","due_date":"",
            "status":"NON RÉGLÉ","notes":payload.get('notes',''),"supplier":supplier,"supplier_name":supplier_name,
            "source_maintenance":record_id}
        self.conn.execute("INSERT INTO module_records VALUES(?,?,?,?)",('supplier_purchases',purchase_id,
            json.dumps(purchase,ensure_ascii=False),datetime.now().isoformat(timespec='seconds')))

    def _hbz_credit_db_path(self):
        return APP_DIR / "HBZ_Credit_App" / "hbz_credit.db"

    def _sync_recurring_charges(self):
        new=self.recurring_charges.synchronize()
        for reference in new:self._audit('EXÉCUTION','CHARGE MENSUELLE',reference)
        if new:self.conn.commit()
        return bool(new)

    def _recurring_charges_clock(self):
        before=self.conn.total_changes
        self._sync_pending_drafts()
        self._sync_recurring_charges()
        if self.conn.total_changes>before:
            if 'expenses' in getattr(self,'module_trees',{}):self.refresh_business_records('expenses')
            self.refresh_dashboard()
        if self.root.winfo_exists():self.root.after(60000,self._recurring_charges_clock)

    def _sync_pending_drafts(self):
        """Synchronise les effets sans comptabiliser un chèque avant son échéance."""
        today=datetime.now().date(); changed=False
        rows=self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='checks'").fetchall()
        for record_id,raw in rows:
            try:q=json.loads(raw)
            except Exception:continue
            kind=str(q.get("type","")).strip().upper()
            if kind not in ("TRAITE","CHÈQUE","CHEQUE"):continue
            due=self._parse_french_date(q.get("due_date",""))
            amount=max(0.0,self._number(q.get("amount")))
            if not due or amount<=0:continue
            expense_id=f"{'TRAITE' if kind=='TRAITE' else 'CHEQUE'}-{record_id}"
            if str(q.get("status","")).upper() in ("REJETÉ","REJETE","ANNULÉ","ANNULE") or (kind!="TRAITE" and due.date()>today+timedelta(days=3)):
                if self.conn.execute("DELETE FROM module_records WHERE module='expenses' AND record_id=?",(expense_id,)).rowcount:changed=True
                continue
            executed=due.date()<=today
            received=str(q.get("direction","ÉMIS")).upper() in ("REÇU","RECU")
            status=("ENCAISSÉ" if received else "PAYÉ") if executed else "EN ATTENTE"
            # La même ligne historique est mise à jour : jamais de doublon.
            ep={"reference":expense_id,"type":"PRODUIT" if received else "CHARGE","category":"TRAITE BANCAIRE" if kind=='TRAITE' else "CHÈQUE À ÉCHÉANCE",
                "date":q.get("due_date", ""),"vehicle":"","party":q.get("client", ""),
                "description":f"{'Traite' if kind=='TRAITE' else 'Chèque'} {q.get('number') or record_id} — {q.get('bank','')}"+(" · INFORMATIF" if not executed else ""),
                "payment_method":"BANQUE","amount":f"{amount:.2f}","document":q.get("number", ""),
                "status":status,"notes":q.get("notes", ""),"source_check":record_id,"direction":"REÇU" if received else "ÉMIS"}
            old=self.conn.execute("SELECT payload FROM module_records WHERE module='expenses' AND record_id=?",(expense_id,)).fetchone()
            if old:
                try:oldp=json.loads(old[0])
                except Exception:oldp={}
                # Ne réécrit que si nécessaire afin de conserver une trace stable.
                if any(str(oldp.get(k,""))!=str(ep.get(k,"")) for k in ep):
                    self.conn.execute("UPDATE module_records SET payload=? WHERE module='expenses' AND record_id=?",(json.dumps(ep,ensure_ascii=False),expense_id));changed=True
            else:
                self.conn.execute("INSERT INTO module_records VALUES(?,?,?,?)",("expenses",expense_id,json.dumps(ep,ensure_ascii=False),datetime.now().isoformat(timespec="seconds")));changed=True
            desired_check=status
            if str(q.get("status","")).upper()!=desired_check:
                q["status"]=desired_check
                self.conn.execute("UPDATE module_records SET payload=? WHERE module='checks' AND record_id=?",(json.dumps(q,ensure_ascii=False),record_id));changed=True
        if changed:self.conn.commit()

    def _pending_drafts_total(self, within_days=None):
        """Effets informatifs dès J−3, retirés le jour de leur exécution."""
        self._sync_pending_drafts();self._sync_hbz_credit_monthly_bank()
        total=0.0;today=datetime.now().date()
        for date,ref,party,label,amount,status in self._draft_period_info_rows():
            due=self._parse_french_date(date).date()
            if within_days is None or due<=today+timedelta(days=within_days):total+=amount
        return total

    def _pending_checks_total(self):
        """Chèques informatifs entre J−3 et la veille de leur exécution."""
        return sum(amount for _reference,_due,amount in self._pending_checks_rows())

    def _pending_checks_rows(self):
        """Une ligne par chèque en attente pour une synthèse de hauteur variable."""
        self._sync_pending_drafts()
        today=datetime.now().date();rows=[]
        for reference,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='checks'"):
            try:q=json.loads(raw)
            except (TypeError,json.JSONDecodeError):continue
            if str(q.get("type","")).upper() not in ("CHÈQUE","CHEQUE") or str(q.get("status","")).upper()!="EN ATTENTE":continue
            if str(q.get("direction","ÉMIS")).upper() in ("REÇU","RECU"):continue
            due=self._parse_french_date(q.get("due_date",""))
            if due and today<due.date()<=today+timedelta(days=3):
                rows.append((str(q.get("number") or reference),due.strftime("%d/%m/%Y"),max(0.0,self._number(q.get("amount")))))
        return sorted(rows,key=lambda row:(datetime.strptime(row[1],"%d/%m/%Y"),row[0]))

    def _hbz_credit_due_10d_total(self):
        """Montant global des échéances HBZ Crédit dues entre aujourd’hui et J+10."""
        db_path=self._hbz_credit_db_path()
        if not db_path.exists(): return self._pending_drafts_total(10)
        today=datetime.now().date(); limit=today+timedelta(days=10); total=0.0
        con=sqlite3.connect(str(db_path))
        try:
            for date_text,amount in con.execute("SELECT date_ech,COALESCE(echeance,0) FROM echeances"):
                try: due=datetime.strptime(str(date_text)[:10],"%Y-%m-%d").date()
                except Exception: continue
                if today <= due <= limit: total += max(0.0,float(amount or 0))
        finally: con.close()
        # Inclure les chèques seulement dès J-3, sans comptabilisation avant échéance.
        # Ne pas utiliser _pending_drafts_total(10) ici : cette fonction inclut aussi
        # les échéances HBZ Crédit synchronisées dans expenses, ce qui doublait leur
        # montant alors qu'elles proviennent déjà de la base HBZ Crédit ci-dessus.
        for (raw,) in self.conn.execute("SELECT payload FROM module_records WHERE module='checks'"):
            try:q=json.loads(raw)
            except Exception:continue
            kind=str(q.get("type","")).upper()
            if kind not in ("TRAITE","CHÈQUE","CHEQUE") or str(q.get("status","")).upper()!="EN ATTENTE":continue
            due=self._parse_french_date(q.get("due_date",""))
            if not due or due.date()<today or due.date()>limit:continue
            if kind!="TRAITE" and due.date()>today+timedelta(days=3):continue
            total += max(0.0,self._number(q.get("amount")))
        return total

    def _hbz_credit_snapshot(self):
        """Lit HBZ Crédit et calcule une synthèse sans dépendre des anciennes tables GestionPro."""
        db_path=self._hbz_credit_db_path()
        result={"rows":[],"capital":0.0,"paid":0.0,"remaining":0.0,"monthly":0.0,"global_monthly":0.0,"count":0}
        if not db_path.exists(): return result
        con=sqlite3.connect(str(db_path))
        try:
            rows=con.execute("SELECT ref,COALESCE(organisme,''),COALESCE(montant_credit,0),date_ech,COALESCE(echeance,0),COALESCE(capital_restant,0) FROM echeances ORDER BY ref,date_ech,id").fetchall()
        finally: con.close()
        today=datetime.now().date(); month_key=(today.year,today.month); grouped={}
        for ref,org,capital,date_text,payment,remaining in rows:
            try: d=datetime.strptime(str(date_text)[:10],"%Y-%m-%d").date()
            except Exception: continue
            grouped.setdefault((str(ref),str(org)),[]).append((d,float(payment or 0),float(remaining or 0),float(capital or 0)))
        display=[]
        for (ref,org),items in grouped.items():
            items.sort(key=lambda x:x[0]); initial=max((x[3] for x in items),default=0.0)
            current=next((x for x in items if x[0]>=today),None)
            if current is None: continue
            cur_date,cur_payment,cur_remaining,_=current
            month_payment=sum(x[1] for x in items if (x[0].year,x[0].month)==month_key)
            paid=max(0.0,initial-cur_remaining)
            result["capital"]+=initial; result["paid"]+=paid; result["remaining"]+=cur_remaining
            result["monthly"]+=cur_payment; result["global_monthly"]+=month_payment
            display.append((ref,org,initial,cur_payment,cur_remaining,paid,cur_date.strftime("%d/%m/%Y")))
        result["rows"]=display; result["count"]=len(display)
        return result

    def _sync_hbz_credit_monthly_bank(self):
        """Synchronise les échéances bancaires à leur date réelle, tous les jours du mois."""
        db_path = self._hbz_credit_db_path()
        if not db_path.exists():
            return 0.0
        today = datetime.now().date()
        total_debited = 0.0
        # Conserver les lignes et leur date de création pour l'historique financier.
        active_ids = set()
        con = sqlite3.connect(str(db_path))
        try:
            rows = con.execute(
                "SELECT id,ref,COALESCE(organisme,''),date_ech,COALESCE(echeance,0) "
                "FROM echeances ORDER BY date(date_ech),id"
            ).fetchall()
        finally:
            con.close()
        stamp = datetime.now().isoformat(timespec="seconds")
        for echeance_id, ref, organisme, date_text, amount_raw in rows:
            try:
                due = datetime.strptime(str(date_text)[:10], "%Y-%m-%d").date()
            except (ValueError, TypeError):
                continue
            # Banque : conserver la véritable date d’échéance, y compris du 1er au 5.
            visible_from = due - timedelta(days=3)
            amount = max(0.0, float(amount_raw or 0))
            if amount <= 0 or today < visible_from:
                continue
            executed = today >= due
            status = "PAYÉ" if executed else "EN ATTENTE"
            safe_ref = str(ref or "CREDIT").strip().replace(" ", "-")
            record_id = f"HBZ-CREDIT-ECH-{safe_ref}-{echeance_id}-{due:%Y%m%d}"
            active_ids.add(record_id)
            payload = {
                "reference": record_id,
                "type": "CHARGE",
                "category": "CRÉDIT HBZ / ÉCHÉANCE",
                # La date affichée est toujours la vraie date d'exécution, jamais J-3.
                "date": due.strftime("%d/%m/%Y"),
                "vehicle": "",
                "party": str(organisme or "HBZ Crédit"),
                "description": f"Échéance HBZ Crédit {ref} — exécution le {due:%d/%m/%Y}",
                "payment_method": "BANQUE",
                "amount": f"{amount:.2f}",
                "document": f"HBZ-{safe_ref}-{due:%Y%m%d}",
                "status": status,
                "notes": ("Informatif : non comptabilisé avant la date d'exécution" if not executed
                          else "Exécuté à la date d'échéance ; déduction Banque comptabilisée")
            }
            old = self.conn.execute(
                "SELECT payload FROM module_records WHERE module='expenses' AND record_id=?", (record_id,)
            ).fetchone()
            if old:
                try: old_payload = json.loads(old[0])
                except Exception: old_payload = {}
                if old_payload != payload:
                    self.conn.execute(
                        "UPDATE module_records SET payload=? WHERE module='expenses' AND record_id=?",
                        (json.dumps(payload, ensure_ascii=False), record_id)
                    )
            else:
                self.conn.execute(
                    "INSERT INTO module_records VALUES(?,?,?,?)",
                    ("expenses", record_id, json.dumps(payload, ensure_ascii=False), stamp)
                )
            if executed:
                total_debited += amount
        # Retirer seulement les projections devenues obsolètes après édition du crédit.
        for (old_id,) in self.conn.execute("SELECT record_id FROM module_records WHERE module='expenses' AND record_id LIKE 'HBZ-CREDIT-ECH-%'").fetchall():
            if old_id not in active_ids:
                self.conn.execute("DELETE FROM module_records WHERE module='expenses' AND record_id=?", (old_id,))
        self.conn.commit()
        return total_debited

    def _open_hbz_credit_target(self,page="dashboard",reference=""):
        app_dir=APP_DIR / "HBZ_Credit_App"; app_py=app_dir / "app.py"
        if not app_py.exists():
            self._professional_notice("HBZ Crédit","Le module HBZ_Credit_App/app.py est introuvable.","!",RED); return
        try:
            py=Path(sys.executable); pyw=py.with_name("pythonw.exe")
            exe=str(pyw if os.name=="nt" and pyw.exists() else py)
            args=[exe,str(app_py),"--page",page]
            if reference: args += ["--ref",reference]
            subprocess.Popen(args,cwd=str(app_dir))
        except Exception as exc:self._professional_notice("HBZ Crédit",f"Impossible d’ouvrir HBZ Crédit :\n{exc}","!",RED)

    def _selected_hbz_credit_ref(self):
        tree=getattr(self,"hbz_credit_fin_tree",None)
        if tree is None or not tree.selection(): return ""
        vals=tree.item(tree.selection()[0],"values"); return str(vals[0]) if vals else ""

    def _delete_selected_hbz_credit(self):
        ref=self._selected_hbz_credit_ref()
        if not ref:self._professional_notice("HBZ Crédit","Sélectionnez d’abord un dossier crédit.","!",ORANGE);return
        if not self._professional_confirm("Supprimer crédit",f"Supprimer le dossier HBZ Crédit {ref} et toutes ses échéances ?","🗑",RED):return
        con=sqlite3.connect(str(self._hbz_credit_db_path()))
        try: con.execute("DELETE FROM echeances WHERE ref=?",(ref,));con.commit()
        finally: con.close()
        self._refresh_hbz_credit_finance();self._professional_notice("HBZ Crédit",f"Le dossier {ref} a été supprimé.","✓",GREEN)

    def _refresh_hbz_credit_finance(self):
        if not hasattr(self,"hbz_credit_fin_tree"): return
        snap=self._hbz_credit_snapshot(); self._sync_hbz_credit_monthly_bank()
        mapping={"count":str(snap["count"]),"capital":f'{snap["capital"]:,.2f} MAD',"paid":f'{snap["paid"]:,.2f} MAD',
                 "remaining":f'{snap["remaining"]:,.2f} MAD',"monthly":f'{snap["monthly"]:,.2f} MAD',"global_monthly":f'{snap["global_monthly"]:,.2f} MAD'}
        for k,v in mapping.items():
            if k in self.hbz_credit_fin_vars:self.hbz_credit_fin_vars[k].set(v)
        tree=self.hbz_credit_fin_tree
        for i in tree.get_children():tree.delete(i)
        for row in snap["rows"]:tree.insert("","end",values=(row[0],row[1],f"{row[2]:.2f}",f"{row[3]:.2f}",f"{row[4]:.2f}",f"{row[5]:.2f}",row[6]))

