        for c,(lab,key,color) in enumerate(defs):
            cards.grid_columnconfigure(c,weight=1,uniform="hbzcredit");box=tk.Frame(cards,bg=CARD,highlightbackground=color,highlightthickness=1);box.grid(row=0,column=c,sticky="nsew",padx=(0 if c==0 else 4,0))
            tk.Label(box,text=lab,bg=CARD,fg=TEXT,font=("Segoe UI",7,"bold"),wraplength=130).pack(anchor="w",padx=8,pady=(7,1));tk.Label(box,textvariable=self.hbz_credit_fin_vars[key],bg=CARD,fg=color,font=("Segoe UI",11,"bold")).pack(anchor="w",padx=8,pady=(0,7))
        info=tk.Frame(page,bg=CARD,highlightbackground=BORDER,highlightthickness=1);info.pack(fill="x",padx=16,pady=(0,7))
        tk.Label(info,text="INFORMATIONS & FINANCE — HBZ CRÉDIT",bg=CARD,fg=NAVY,font=("Segoe UI",11,"bold")).pack(anchor="w",padx=12,pady=(9,2))
        tk.Label(info,text="Les anciennes tables Crédit/Échéances restent suspendues. Les cartes, la liste et le débit Banque mensuel proviennent uniquement de HBZ Crédit.",bg=CARD,fg=MUTED,font=("Segoe UI",8),anchor="w").pack(fill="x",padx=12,pady=(0,9))
        cols=("ref","org","capital","mens","reste","paye","date");tree=ttk.Treeview(page,columns=cols,show="headings",height=14);self.hbz_credit_fin_tree=tree
        for c,h,w in (("ref","Référence",125),("org","Organisme",170),("capital","Capital crédit",130),("mens","Mensualité",115),("reste","Capital restant",130),("paye","Total payé",120),("date","Prochaine échéance",125)):
            tree.heading(c,text=h);tree.column(c,width=w,anchor="center")
        tree.pack(fill="both",expand=True,padx=16,pady=(0,12));tree.bind("<Double-1>",lambda _e:self._open_hbz_credit_target("credits",self._selected_hbz_credit_ref()))
        self._refresh_hbz_credit_finance();return page

