        foot=tk.Frame(host,bg=BG);foot.pack(fill="x",pady=(7,0))
        footer_labels=[]
        for col,(label,value,color,soft) in enumerate((("RÉSULTAT · CA − CHARGES",totals["result"],"#15885b","#e6faef"),
                 ("ÉCART DÉBIT / CRÉDIT",totals["balance_gap"],"#b16f3f","#fff0e5"))):
            foot.grid_columnconfigure(col,weight=1,uniform="summary_result")
            field=tk.Label(foot,text=f"{label} :  {value:,.2f} MAD",bg=soft,fg=color,
                           font=("Segoe UI",10,"bold"),padx=12,pady=8)
            field.grid(row=0,column=col,sticky="ew",padx=4)
            footer_labels.append(field)
        footer_layout={"narrow":None}
        def resize_footer(event):
            narrow=event.width<660
            if footer_layout["narrow"]==narrow:return
