    def _build_invoices_pro_page(self, name, title, fields):
        """V140 — forme Factures dédiée, structurée comme la maquette Créances."""
        if not hasattr(self,"module_vars"):
            self.module_vars,self.module_trees,self.module_fields={},{},{}
        self.module_fields[name]=fields
        self.module_vars[name]={key:tk.StringVar() for _label,key in fields}
        page=self._new_page(name)
        self._page_title(page,"GESTION DES FACTURES","Création, règlement et suivi des factures clients")
        self._action_bar(page,(
            ("＋ Nouvelle",lambda:self.new_business_record("invoices")),
            ("▣ Enregistrer",lambda:self.save_business_record("invoices")),
            ("✎ Modifier",lambda:self.update_business_record("invoices")),
            ("▣ Supprimer",lambda:self.delete_business_record("invoices")),
            ("▣ Aperçu / PDF",self.preview_invoice),
            ("↻ Actualiser",lambda:self.refresh_business_records("invoices")),
        ))

        # Cartes de synthèse en tête.
        metrics=tk.Frame(page,bg=BG);metrics.pack(fill="x",padx=16,pady=(0,7))
        self.invoice_metric_vars={k:tk.StringVar(value="0,00 MAD") for k in ("total","paid","balance","settled","unpaid")}
        metric_defs=(("▤","Total facturé","total","#e5f2ff",BLUE),("▣","Total réglé","paid","#e5f6ea",GREEN),
                     ("◕","Reste global","balance","#fff1dc",ORANGE),("✓","Factures payées","settled","#e7f7ed","#087a35"),
                     ("!","Factures impayées","unpaid","#ffe7ea",RED))
        for col,(icon,label,key,bg,fg) in enumerate(metric_defs):
            card=tk.Frame(metrics,bg=bg,highlightbackground=fg,highlightthickness=1);card.grid(row=0,column=col,sticky="nsew",padx=(0 if col==0 else 5,0))
            metrics.grid_columnconfigure(col,weight=1,uniform="invoice_metrics")
            tk.Label(card,text=icon,bg=bg,fg=fg,font=("Segoe UI Symbol",21,"bold"),width=3).pack(side="left",padx=(7,2),pady=6)
            info=tk.Frame(card,bg=bg);info.pack(side="left",fill="both",expand=True,pady=6)
            tk.Label(info,text=label,bg=bg,fg=TEXT,font=("Segoe UI",8,"bold"),anchor="w").pack(fill="x")
            tk.Label(info,textvariable=self.invoice_metric_vars[key],bg=bg,fg=fg,font=("Segoe UI",12,"bold"),anchor="w").pack(fill="x")

        cards=tk.Frame(page,bg=BG);cards.pack(fill="x",padx=16,pady=(0,7))
        for col in range(3):cards.grid_columnconfigure(col,weight=1,uniform="invoice_cards")
        def make_card(col,title_text,field_defs):
            outer=tk.Frame(cards,bg=CARD,highlightbackground="#bcd3e2",highlightthickness=1);outer.grid(row=0,column=col,sticky="nsew",padx=(0 if col==0 else 5,0))
            tk.Label(outer,text=title_text,bg="#dceffc",fg=NAVY,font=("Segoe UI",10,"bold"),anchor="w",padx=10,pady=6).pack(fill="x")
            body=tk.Frame(outer,bg=CARD);body.pack(fill="both",expand=True,padx=10,pady=5)
            for row,(label,key,kind) in enumerate(field_defs):
                tk.Label(body,text=label+" :",bg=CARD,fg="#526b7d",font=("Segoe UI",8,"bold"),anchor="w").grid(row=row,column=0,sticky="w",pady=2,padx=(0,6))
                if kind=="contract":
                    widget=ttk.Combobox(body,textvariable=self.module_vars[name][key],values=self._invoice_contract_choices(),style="GP.TCombobox")
                    widget.bind("<<ComboboxSelected>>",self._load_invoice_contract);widget.bind("<Return>",self._load_invoice_contract)
                elif kind=="status":
                    widget=ttk.Combobox(body,textvariable=self.module_vars[name][key],values=("EN ATTENTE","PARTIEL","PAYÉ","ANNULÉ"),state="readonly",style="GP.TCombobox")
                else:
                    widget=ttk.Entry(body,textvariable=self.module_vars[name][key],style="GP.TEntry",state="readonly" if kind=="readonly" else "normal")
                widget.grid(row=row,column=1,sticky="ew",pady=2);body.grid_columnconfigure(1,weight=1)
                if key=="date":self._attach_date_picker(widget,self.module_vars[name][key])
                self._enable_combobox_autocomplete(widget)
        make_card(0,"①  FACTURE",(("N° facture","reference","entry"),("N° contrat","contract","contract"),("Date facture","date","entry"),("Statut","status","status")))
        make_card(1,"②  CLIENT",(("Code client","client","readonly"),("Nom / raison sociale","customer_name","readonly"),("CIN / ICE","customer_id","readonly"),("Véhicule","vehicle","readonly"),("Immatriculation","plate","readonly")))
        make_card(2,"③  SYNTHÈSE — TVA INCLUSE",(("Montant HT","subtotal","readonly"),("TVA incluse","tax","readonly"),("Total TTC","total","readonly"),("Règlement","payment","entry"),("Reste à payer","balance","readonly")))

        # Détails de facturation compacts.
        detail=tk.Frame(page,bg=CARD,highlightbackground="#bfd3df",highlightthickness=1);detail.pack(fill="x",padx=16,pady=(0,7))
