        tree.configure(yscrollcommand=ybar.set,xscrollcommand=xbar.set);tree.pack(fill="both",expand=True,padx=(12,25),pady=(14,3));ybar.place(relx=1,rely=.03,relheight=.84,anchor="ne");xbar.pack(fill="x",padx=12,pady=(0,8))
