    def open_versements(self, initial_mode="VERSEMENT BANQUE"):
        """Structure dédiée aux transferts caisse/banque avec historique."""
        win=self._secondary_window(self.root);win.title("Versements — GestionPro HBZ")
        win.geometry("900x610");win.minsize(800,540);win.transient(self.root);win.configure(bg=BG)
        head=tk.Frame(win,bg=NAVY);head.pack(fill="x")
        tk.Label(head,text="⇄  VERSEMENTS CAISSE / BANQUE",bg=NAVY,fg="white",font=("Segoe UI",15,"bold"),pady=14).pack(fill="x")
        vars={k:tk.StringVar() for k in ("reference","date","amount","bank","mode","notes")}
        vars["date"].set(datetime.now().strftime("%d/%m/%Y"));vars["mode"].set(initial_mode if initial_mode in ("VERSEMENT BANQUE","RETRAIT BANQUE") else "VERSEMENT BANQUE")
        # Le versement bancaire proposé correspond au solde caisse réellement disponible.
        available_cash=max(0.0,self._financial_totals().get("cash",0.0));vars["amount"].set(f"{available_cash:.2f}")
        existing=[int(r[0][3:]) for r in self.conn.execute("SELECT record_id FROM module_records WHERE module='transfers'")
                  if str(r[0]).startswith("VRS") and str(r[0])[3:].isdigit()]
        vars["reference"].set(f"VRS{max(existing,default=0)+1:06d}")
        form=tk.Frame(win,bg=CARD,highlightbackground=BORDER,highlightthickness=1);form.pack(fill="x",padx=16,pady=14)
        form.grid_columnconfigure(1,weight=1);form.grid_columnconfigure(3,weight=1)
        fields=(("Référence","reference"),("Date","date"),("Montant (MAD)","amount"),("Banque / Compte","bank"),("Type","mode"),("Observation","notes"))
        for i,(label,key) in enumerate(fields):
            r=i//2;c=(i%2)*2
            tk.Label(form,text=label.upper(),bg=CARD,fg="#4d6475",font=("Segoe UI",8,"bold")).grid(row=r,column=c,sticky="w",padx=(14,7),pady=9)
            if key=="mode":w=ttk.Combobox(form,textvariable=vars[key],values=("VERSEMENT BANQUE","RETRAIT BANQUE"),state="readonly",style="GP.TCombobox")
            else:w=ttk.Entry(form,textvariable=vars[key],style="GP.TEntry")
            w.grid(row=r,column=c+1,sticky="ew",padx=(0,14),pady=7,ipady=3)
            if key=="date":self._attach_date_picker(w,vars[key])
        cols=("reference","date","amount","bank","notes")
        tree=ttk.Treeview(win,columns=cols,show="headings",height=12)
        for key,label,width in (("reference","Référence",120),("date","Date",100),("amount","Montant",120),("bank","Banque / Compte",180),("notes","Observation",300)):
            tree.heading(key,text=label);tree.column(key,width=width,anchor="center")
        tree.pack(fill="both",expand=True,padx=16,pady=(0,72))
        def refresh():
            tree.delete(*tree.get_children())
            for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='transfers' ORDER BY created_at DESC"):
                try:q=json.loads(raw)
                except Exception:continue
                tree.insert("","end",iid=rid,values=(rid,q.get("date",""),q.get("amount",""),q.get("bank",""),q.get("notes","")))
        def load(_e=None):
            sel=tree.selection()
            if not sel:return
            rid=sel[0];row=self.conn.execute("SELECT payload FROM module_records WHERE module='transfers' AND record_id=?",(rid,)).fetchone()
            if not row:return
            q=json.loads(row[0]);vars["reference"].set(rid)
            for k in ("date","amount","bank","mode","notes"):vars[k].set(str(q.get(k,"")))
        tree.bind("<<TreeviewSelect>>",load)
        def save():
            rid=vars["reference"].get().strip();amount=self._number(vars["amount"].get())
            if not rid or amount<=0 or not self._parse_french_date(vars["date"].get()):
                messagebox.showwarning("Versement","Référence, date valide et montant supérieur à zéro obligatoires.",parent=win);return
            current=self.conn.execute("SELECT payload FROM module_records WHERE module='transfers' AND record_id=?",(rid,)).fetchone()
            old_amount=0.0;old_mode=""
            if current:
                try:
                    previous=json.loads(current[0]);old_amount=self._number(previous.get("amount"))
                    old_mode=str(previous.get("mode","")).upper()
                except Exception: old_amount=0.0
            totals_now=self._financial_totals(); mode_now=vars["mode"].get().upper()
            if "RETRAIT" in mode_now:
                adjustment=old_amount if "RETRAIT" in old_mode else -old_amount
                available=max(0.0,totals_now.get("bank",0.0)+adjustment)
                if amount>available+0.005:
                    messagebox.showwarning("Retrait",f"Retrait impossible : banque disponible {available:.2f} MAD.",parent=win);return
            else:
                adjustment=old_amount if "VERSEMENT" in old_mode else -old_amount
                available=max(0.0,totals_now.get("cash",0.0)+adjustment)
                if amount>available+0.005:
                    messagebox.showwarning("Versement",f"Versement impossible : caisse disponible {available:.2f} MAD.",parent=win);return
            q={k:v.get().strip() for k,v in vars.items()};q["amount"]=f"{amount:.2f}"
            exists=self.conn.execute("SELECT 1 FROM module_records WHERE module='transfers' AND record_id=?",(rid,)).fetchone()
            if exists:self.conn.execute("UPDATE module_records SET payload=?,created_at=? WHERE module='transfers' AND record_id=?",(json.dumps(q,ensure_ascii=False),datetime.now().isoformat(timespec="seconds"),rid))
            else:self.conn.execute("INSERT INTO module_records VALUES(?,?,?,?)",("transfers",rid,json.dumps(q,ensure_ascii=False),datetime.now().isoformat(timespec="seconds")))
            self.conn.commit();refresh()
            if hasattr(self,"financial_center_cards"):self._refresh_financial_center()
            messagebox.showinfo("Versement",f"{vars['mode'].get().title()} : {amount:.2f} MAD enregistré.",parent=win)
        def delete():
            rid=vars["reference"].get().strip()
            if rid and messagebox.askyesno("Versement",f"Supprimer {rid} ?",parent=win):
                self.conn.execute("DELETE FROM module_records WHERE module='transfers' AND record_id=?",(rid,));self.conn.commit();refresh()
                if hasattr(self,"financial_center_cards"):self._refresh_financial_center()
        bar=tk.Frame(win,bg=BG,height=60);bar.place(relx=0,rely=1,anchor="sw",relwidth=1,height=60);bar.lift()
        tk.Button(bar,text="Fermer",command=win.destroy,bg=MUTED,fg="white",relief="flat",padx=18,pady=8).pack(side="right",padx=8,pady=10)
        tk.Button(bar,text="Supprimer",command=delete,bg=RED,fg="white",relief="flat",padx=18,pady=8).pack(side="right",padx=4,pady=10)
        tk.Button(bar,text="Enregistrer / Modifier",command=save,bg=GREEN,fg="white",relief="flat",padx=18,pady=8,font=("Segoe UI",9,"bold")).pack(side="right",padx=4,pady=10)
        refresh()

    def _validate_check(self, payload):
        if payload.get("type") not in ("CHÈQUE", "TRAITE"):
            return "Choisissez CHÈQUE ou TRAITE."
        if payload.get("direction") not in ("ÉMIS", "REÇU", ""):
            return "Choisissez un chèque émis ou reçu."
        if not payload.get("number") or not payload.get("client"):
            return "Le numéro de l’effet et le client sont obligatoires."
        if not self._parse_french_date(payload.get("due_date")):
            return "Échéance invalide. Utilisez JJ/MM/AAAA."
        if self._number(payload.get("amount")) <= 0:
            return "Le montant doit être supérieur à zéro."
        return ""

    def _validate_maintenance(self, payload):
        if not payload.get("vehicle") or not payload.get("service"):
            return "Choisissez le véhicule et le type d’intervention."
        if payload.get("service") not in ("AdBlue", "Vidange", "Chaîne"):
            return "Type d’intervention invalide."
        if not self._parse_french_date(payload.get("date")):
            return "Date d’intervention invalide. Utilisez JJ/MM/AAAA."
        if self._number(payload.get("mileage")) < 0 or self._number(payload.get("product_km")) <= 0:
            return "Les kilométrages doivent être valides et le Km produit supérieur à zéro."
        if str(payload.get("payment_method","")).upper() not in ("ESPÈCES","CHÈQUE","À CRÉDIT"):
            return "Choisissez le type de règlement : Espèces, Chèque ou À crédit."
        if self._number(payload.get("amount")) < 0:
            return "Le montant de l’intervention ne peut pas être négatif."
        if str(payload.get("payment_method","")).upper()=="À CRÉDIT" and not str(payload.get("supplier","")).strip():
            return "Le fournisseur est obligatoire pour un entretien à crédit."
        return ""

    def _validate_planning(self, payload):
        if not payload.get("subject"):
            return "L’objet du rendez-vous est obligatoire."
        if not self._parse_french_date(payload.get("date")):
            return "Date invalide. Utilisez JJ/MM/AAAA."
        if not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", payload.get("time", "")):
            return "Heure invalide. Utilisez HH:MM."
        reminder=self._number(payload.get("reminder"))
        if reminder < 0 or reminder > 365:
            return "Le rappel doit être compris entre 0 et 365 jours."
        return ""

    def _checks_totals(self):
        totals = {"checks":0.0, "drafts":0.0, "pending":0.0, "overdue":0.0, "near":0}
        today = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
        for (raw,) in self.conn.execute("SELECT payload FROM module_records WHERE module='checks'"):
            try: payload = json.loads(raw)
            except json.JSONDecodeError: continue
            amount = self._number(payload.get("amount")); kind = str(payload.get("type", "")).upper()
            status = str(payload.get("status", "")).upper()
            if kind == "CHÈQUE": totals["checks"] += amount
            elif kind == "TRAITE": totals["drafts"] += amount
            if status in ("PAYÉ", "PAYE", "ENCAISSÉ", "ENCAISSE", "ANNULÉ", "ANNULE"):
                continue
            totals["pending"] += amount
            due = self._parse_french_date(payload.get("due_date"))
            if due and due < today: totals["overdue"] += amount
            if due and today <= due <= today + timedelta(days=15): totals["near"] += 1
        return totals

    def open_checks_summary(self):
        totals = self._checks_totals()
        win = self._secondary_window(self.root); win.title("Situation Chèques & Traites")
        win.geometry("760x390"); win.transient(self.root); win.configure(bg=BG)
        tk.Label(win, text="SITUATION CHÈQUES & TRAITES", bg=NAVY, fg="white",
                 font=("Segoe UI", 16, "bold"), pady=15).pack(fill="x")
        cards = tk.Frame(win, bg=BG); cards.pack(fill="both", expand=True, padx=18, pady=14)
        data = (("TOTAL CHÈQUES", "checks", BLUE, "MAD"), ("TOTAL TRAITES", "drafts", PURPLE, "MAD"),
                ("EN ATTENTE", "pending", ORANGE, "MAD"), ("ÉCHUS", "overdue", RED, "MAD"),
                ("ÉCHÉANCES ≤ 15 JOURS", "near", GREEN, "effet(s)"))
        for i,(label,key,color,unit) in enumerate(data):
            frame=tk.Frame(cards,bg=color); frame.grid(row=i//3,column=i%3,sticky="nsew",padx=6,pady=6)
            tk.Label(frame,text=label,bg=color,fg="white",font=("Segoe UI",9,"bold")).pack(padx=12,pady=(13,3))
            value = f"{totals[key]:,.2f}" if key != "near" else str(totals[key])
            tk.Label(frame,text=f"{value} {unit}",bg=color,fg="white",font=("Segoe UI",14,"bold")).pack(padx=12,pady=(0,14))
        for col in range(3): cards.grid_columnconfigure(col,weight=1)
        tk.Button(win,text="Fermer",command=win.destroy,bg=NAVY,fg="white",relief="flat",padx=22,pady=8).pack(pady=12)

    def preview_check(self):
        payload = self._business_payload("checks")
        error = self._validate_check(payload)
        if error: messagebox.showwarning("Chèque / Traite", error); return
        p={k:html.escape(str(v or "")) for k,v in payload.items()}
        content=f"""<!doctype html><html><head><meta charset='utf-8'><title>{p['type']} {p['number']}</title>
        <style>@page{{size:210mm 100mm;margin:8mm}}body{{font:15px Arial;color:#18364c}}.sheet{{border:2px solid #168bd0;border-radius:16px;padding:18px}}
        h1{{color:#0e5a91;margin:0 0 16px}}.row{{display:flex;justify-content:space-between;margin:13px 0}}.amount{{font-size:22px;font-weight:bold;color:#0e5a91}}</style>
        </head><body><div class='sheet'>{self._print_logo_html()}<h1>HBZ Rent Car — {p['type']}</h1><div class='row'><b>N° {p['number']}</b><span>Échéance : {p['due_date']}</span></div>
        <div class='row'><span>Bénéficiaire / Client : <b>{p['client']}</b></span><span>Banque : {p['bank']}</span></div>
        <div class='row'><span>{p['notes']}</span><span class='amount'>{p['amount']} MAD</span></div></div></body></html>"""
        EXPORT_DIR.mkdir(exist_ok=True); path=EXPORT_DIR/f"{payload['type']}_{payload['number']}.html"
        path.write_text(content,encoding="utf-8"); webbrowser.open(path.as_uri())

    def _contract_period_share(self, departure, return_date, duration, start_date=None, end_date=None):
        """Production par mois, hors journée de passage au 1er du mois suivant."""
        first=self._parse_french_date(departure)
        if first is None:return 1.0 if start_date is None and end_date is None else 0.0
        last=self._parse_french_date(return_date)
        days=max(1,(last.date()-first.date()).days) if last and last.date()>first.date() else max(1,int(duration or 1))
        first_day=first.date()+timedelta(days=1)
        finish=first_day+timedelta(days=days)
        period_first=start_date.date() if start_date else first_day
        period_finish=end_date.date()+timedelta(days=1) if end_date else finish
        overlap=max(0,(min(finish,period_finish)-max(first_day,period_first)).days)
        # Le 1er situé entre deux mois est une journée « Vision épargne ».
        first_month=datetime(first_day.year,first_day.month,1).date()
        boundary=first_month
        while boundary<finish:
            if first.date()<boundary and period_first<=boundary<period_finish and first_day<=boundary<finish:
                overlap-=1
            boundary=(boundary.replace(day=28)+timedelta(days=4)).replace(day=1)
        return overlap/days

    def _contract_boundary_share(self, departure, return_date, duration, end_date):
        """Part d'une seule journée entre la clôture du mois et le mois suivant."""
        if end_date is None:return 0.0
        first=self._parse_french_date(departure)
        if first is None:return 0.0
        last=self._parse_french_date(return_date)
        days=max(1,(last.date()-first.date()).days) if last and last.date()>first.date() else max(1,int(duration or 1))
        boundary=end_date.date()+timedelta(days=1)
        finish=first.date()+timedelta(days=days+1)
        return 1.0/days if boundary.day==1 and first.date()<boundary<finish else 0.0

    def _contract_allocated_parts(self, departure, return_date, duration, amount, cash, bank,
                                  start_date=None, end_date=None, savings=False):
        """Affecte l'avance aux jours dans l'ordre, puis crée la créance sur les jours impayés."""
        first=self._parse_french_date(departure)
        last=self._parse_french_date(return_date)
        if first is None:
            share=0.0 if savings else (1.0 if start_date is None and end_date is None else 0.0)
            paid=min(amount,max(0,cash+bank))
            return amount*share,cash*share,bank*share,(amount-paid)*share
        days=max(1,(last.date()-first.date()).days) if last and last.date()>first.date() else max(1,int(duration or 1))
        first_day=first.date()+timedelta(days=1)
        paid=min(max(0,amount),max(0,cash+bank))
        cash_ratio=cash/(cash+bank) if cash+bank else 0.0
        portion=amount/days
        selected=settled=0.0
        for index in range(days):
            day=first_day+timedelta(days=index)
            boundary=day.day==1 and day>first.date()
            if savings:
                included=bool(end_date and boundary and day==end_date.date()+timedelta(days=1))
            else:
                included=(not boundary and (start_date is None or day>=start_date.date())
                          and (end_date is None or day<=end_date.date()))
            if included:
                selected+=portion
                settled+=max(0.0,min(paid,(index+1)*portion)-min(paid,index*portion))
        return selected,settled*cash_ratio,settled*(1-cash_ratio),selected-settled

    def _save_contract_payment_mode(self, contract_no, mode):
        value=str(mode or "ESPÈCES").strip().upper()
        self.conn.execute("INSERT OR REPLACE INTO module_records(module,record_id,payload,created_at) VALUES(?,?,?,?)",
                          ("contract_payment_mode",str(contract_no),json.dumps({"mode":value},ensure_ascii=False),
                           datetime.now().isoformat(timespec="seconds")))

    def _contract_payment_parts(self):
        """Ventilation des règlements réels par contrat, sans double compter l'acompte."""
        modes={}
        for reference,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='contract_payment_mode'"):
            try:modes[str(reference)]=str(json.loads(raw).get("mode") or "ESPÈCES").upper()
            except (ValueError,TypeError):continue
        payments={}
        for (raw,) in self.conn.execute("SELECT payload FROM module_records WHERE module='payments'"):
            try:q=json.loads(raw)
            except (ValueError,TypeError):continue
            contract=str(q.get("contract","")).strip()
            if not contract:continue
            cash=self._number(q.get("cash_amount"));bank=self._number(q.get("bank_amount"))
            if "cash_amount" not in q and "bank_amount" not in q:
                amount=self._number(q.get("amount"));mode=str(q.get("mode","")).upper()
                cash,bank=(amount,0.0) if "ESP" in mode else (0.0,amount)
            old=payments.get(contract,(0.0,0.0))
            payments[contract]=(old[0]+max(0,cash),old[1]+max(0,bank))
        return modes,payments

    def _production_expense_date(self, value):
        """Échéance du 1 au 5 : production du mois précédent ; dès le 6 : mois courant."""
        due=self._parse_french_date(value)
        if due is None:return None
        return due.replace(day=1)-timedelta(days=1) if due.day<=5 else due

    def _is_production_draft(self, payload):
        if str(payload.get('category','')).upper() in ('TRAITE BANCAIRE','CRÉDIT HBZ / ÉCHÉANCE'):
            return True
        reference=payload.get('source_check')
        if reference:
            row=self.conn.execute("SELECT payload FROM module_records WHERE module='checks' AND record_id=?",(reference,)).fetchone()
            if row:
                try:return str(json.loads(row[0]).get('type','')).upper()=='TRAITE'
                except (ValueError,TypeError):pass
        return False

    def _draft_period_info_rows(self, start_date=None, end_date=None, received_checks=False):
        """Échéances informatives du 6 au 5, indépendantes des charges comptabilisées."""
        rows=[]
        def add(value,ref,party,label,amount):
            due=self._parse_french_date(value)
            production=self._production_expense_date(value)
            if due is None or production is None:return
            today=datetime.now().date()
            if not today<due.date()<=today+timedelta(days=3):return
            if start_date is not None and production<start_date:return
            if end_date is not None and production>end_date:return
            amount=max(0.0,self._number(amount))
            if amount>0:rows.append((due.strftime('%d/%m/%Y'),str(ref or ''),str(party or ''),label,amount,'INFORMATIF'))
        for ref,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='checks'"):
            try:q=json.loads(raw)
            except (ValueError,TypeError):continue
            kind=str(q.get('type','')).strip().upper()
            if kind not in ('TRAITE','CHÈQUE','CHEQUE'):continue
            if str(q.get('status','')).upper() in ('ANNULÉ','ANNULE','REJETÉ','REJETE'):continue
            received=str(q.get('direction','ÉMIS')).upper() in ('REÇU','RECU')
            if received!=received_checks or (received_checks and kind=='TRAITE'):continue
            add(q.get('due_date',''),q.get('number') or ref,q.get('client'), ('Traite' if kind=='TRAITE' else ('Chèque reçu' if received_checks else 'Chèque émis'))+' — date réelle d’échéance',q.get('amount'))
        if received_checks:return sorted(rows,key=lambda row:(self._parse_french_date(row[0]),row[1]))
        path=self._hbz_credit_db_path()
        if path.exists():
            con=sqlite3.connect(str(path))
            try:
                for ref,org,due,amount in con.execute("SELECT ref,COALESCE(organisme,''),date_ech,COALESCE(echeance,0) FROM echeances"):
                    add(due,ref,org,'Échéance HBZ Crédit — date réelle d’échéance',amount)
            finally:con.close()
        else:
            for ref,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='expenses'"):
                try:q=json.loads(raw)
                except (ValueError,TypeError):continue
                if str(q.get('category','')).upper()!='CRÉDIT HBZ / ÉCHÉANCE':continue
                if str(q.get('status','')).upper() in ('ANNULÉ','ANNULE','REJETÉ','REJETE'):continue
                add(q.get('date',''),q.get('document') or ref,q.get('party'),'Échéance HBZ Crédit — date réelle d’échéance',q.get('amount'))
        return sorted(rows,key=lambda row:(self._parse_french_date(row[0]),row[1]))

    def _expense_is_executed(self, payload):
        if str(payload.get('status','')).upper() in ('EN ATTENTE','ANNULÉ','ANNULE','REJETÉ','REJETE'):return False
        if self._is_production_draft(payload):
            due=self._parse_french_date(payload.get('date',''))
            return due is not None and due.date()<=datetime.now().date()
        return True

    def _expense_charge_date(self, payload):
        return (self._production_expense_date(payload.get('date','')) if self._is_production_draft(payload)
                else self._parse_french_date(payload.get('date','')))

    def _expense_charge_in_period(self, payload, start=None, end=None):
        if not self._expense_is_executed(payload):return False
        date=self._expense_charge_date(payload)
        if date is None:return start is None and end is None
        return (start is None or date>=start) and (end is None or date<=end)

    def _expense_bank_in_period(self,payload,start=None,end=None):
        """Le bilan mensuel rattache le débit exécuté au même cycle que sa charge."""
        if not self._expense_is_executed(payload):return False
        received=str(payload.get('direction','')).upper() in ('REÇU','RECU')
        if self._is_production_draft(payload) and not received:
            return self._expense_charge_in_period(payload,start,end)
        date=self._parse_french_date(payload.get('date',''))
        if date is None:return start is None and end is None
        return (start is None or date>=start) and (end is None or date<=end)

    def _financial_totals(self, start_date=None, end_date=None):
        """Synthèse HBZ : Débit = Banque + Caisse + Créances + Charges ; Crédit = CA ; Résultat = CA - Charges."""
        self._sync_pending_drafts()
        self._sync_hbz_credit_monthly_bank()
        self._sync_recurring_charges()
        totals={"revenue":0.0,"expenses":0.0,"cash":0.0,"bank":0.0,"receivables":0.0,"supplier_payable":0.0,
                "savings_future":0.0,"savings_cash":0.0,"savings_bank":0.0,"savings_receivables":0.0,
                "versements":0.0,"client_cheques":0.0,"charge_cash":0.0,"charge_cheques":0.0}
        def in_period(value):
            d=self._parse_french_date(value)
            if d is None:return start_date is None and end_date is None
            return (start_date is None or d>=start_date) and (end_date is None or d<=end_date)
        # Les parts espèces, banque et créance suivent toutes les mêmes jours de production.
        modes,payments=self._contract_payment_parts()
        for row in self.conn.execute("SELECT numero,date_depart,date_retour,duree,montant,reglement,reste FROM contracts"):
            contract=str(row[0]);amount=max(0.0,float(row[4] or 0));paid=min(amount,max(0.0,float(row[5] or 0)))
            detailed_cash,detailed_bank=payments.get(contract,(0.0,0.0))
            detailed_total=detailed_cash+detailed_bank
            if detailed_total>paid and detailed_total>0:
                factor=paid/detailed_total;detailed_cash*=factor;detailed_bank*=factor
            initial=max(0.0,paid-detailed_cash-detailed_bank)
            mode=modes.get(contract,"ESPÈCES")
            is_bank=any(token in mode for token in ("CHÈQUE","CHEQUE","BANQUE","VIREMENT","CARTE"))
            cash=detailed_cash+(0.0 if is_bank else initial)
            bank=detailed_bank+(initial if is_bank else 0.0)
            production=self._contract_allocated_parts(row[1],row[2],row[3],amount,cash,bank,start_date,end_date)
            totals["revenue"]+=production[0]
            totals["cash"]+=production[1]
            totals["client_cheques"]+=production[2]
            totals["receivables"]+=production[3]
            reserve=self._contract_allocated_parts(row[1],row[2],row[3],amount,cash,bank,start_date,end_date,savings=True)
            for field,value in zip(("savings_future","savings_cash","savings_bank","savings_receivables"),reserve):
                totals[field]+=value
        # Charges et banque du bilan : même cycle du 6 au 5 ; aucun débit avant la date réelle.
        totals['drafts_period_info']=sum(row[4] for row in self._draft_period_info_rows(start_date,end_date))
        for (raw,) in self.conn.execute("SELECT payload FROM module_records WHERE module='expenses'"):
            try:q=json.loads(raw)
            except (ValueError,TypeError):continue
            status=str(q.get('status','')).upper()
            if status in ('ANNULÉ','ANNULE','REJETÉ','REJETE'):continue
            amount=max(0.0,self._number(q.get('amount')))
            category=str(q.get('category','')).upper()
            draft=self._is_production_draft(q)
            received=str(q.get('direction','')).upper() in ('REÇU','RECU')
            if not self._expense_is_executed(q):continue
            if draft and not received and self._expense_charge_in_period(q,start_date,end_date):
                totals['expenses']+=amount
            if not self._expense_bank_in_period(q,start_date,end_date):continue
            if q.get('source_check'):
                if not draft and not received:totals['expenses']+=amount
                totals['client_cheques' if received else 'charge_cheques']+=amount
                continue
            if str(q.get('type','')).upper()!='CHARGE':continue
            if not draft and category not in ('RÈGLEMENT FOURNISSEUR','CRÉDIT HBZ / MENSUALITÉ'):
                totals['expenses']+=amount
            mode=str(q.get('payment_method','')).upper()
            if 'ESP' in mode:totals['charge_cash']+=amount
            elif any(token in mode for token in ('CHÈQUE','CHEQUE','BANQUE')):totals['charge_cheques']+=amount
        # Entretiens : impact mensuel direct selon le mode de règlement.
        for (raw,) in self.conn.execute("SELECT payload FROM module_records WHERE module='maintenance'"):
            try:q=json.loads(raw)
            except Exception:continue
            if not in_period(q.get("date","")):continue
            amount=max(0.0,self._number(q.get("amount")));mode=str(q.get("payment_method","")).upper()
            totals["expenses"]+=amount
            if "ESP" in mode:totals["charge_cash"]+=amount
            elif "CHÈQUE" in mode or "CHEQUE" in mode:totals["charge_cheques"]+=amount
            elif "CRÉDIT" in mode or "CREDIT" in mode:totals["supplier_payable"]+=amount
        # Les règlements fournisseur du mois réduisent la dette correspondante.
        for (raw,) in self.conn.execute("SELECT payload FROM module_records WHERE module='supplier_payments'"):
            try:q=json.loads(raw)
            except Exception:continue
            if in_period(q.get("date","")):totals["supplier_payable"]-=max(0.0,self._number(q.get("amount")))
        totals["supplier_payable"]=max(0.0,totals["supplier_payable"])
        # Transferts internes : versement Caisse -> Banque, retrait Banque -> Caisse.
        # Ils déplacent la trésorerie sans modifier l'actif total ni le CA/passif.
        transfer_to_bank=0.0; transfer_to_cash=0.0
        for (raw,) in self.conn.execute("SELECT payload FROM module_records WHERE module='transfers'"):
            try:q=json.loads(raw)
            except Exception:continue
            if not in_period(q.get("date","")):continue
            amount=self._number(q.get("amount")); mode=str(q.get("mode","VERSEMENT BANQUE")).upper()
            if "RETRAIT" in mode: transfer_to_cash+=amount
            else: transfer_to_bank+=amount
        totals["versements"]=transfer_to_bank-transfer_to_cash
        totals["cash"]+=transfer_to_cash-transfer_to_bank-totals["charge_cash"]
        totals["bank"]=transfer_to_bank-transfer_to_cash+totals["client_cheques"]-totals["charge_cheques"]
        # Présentation de synthèse demandée :
        # Débit = Banque + Caisse + Créances clients + Charges
        # Crédit = Chiffre d'affaires (CA)
        # Résultat = CA - Charges
        from cash_funding import rows as funding_rows
        totals['cash_funding']=sum(float(q['amount']) for _,q,_ in funding_rows(self,start_date,end_date))
        totals['cash']+=totals['cash_funding']
        totals["debit"]=totals["bank"]+totals["cash"]+totals["receivables"]+totals["expenses"]
        totals["credit"]=totals["revenue"]+totals["cash_funding"]
        totals["assets"]=totals["debit"]  # compatibilité avec les anciens appels
        totals["turnover"]=totals["revenue"]
        totals["result"]=totals["revenue"]-totals["expenses"]
        totals["deficit_remaining"]=max(0.0,-totals["result"]-totals["cash_funding"])
        totals["balance_gap"]=totals["debit"]-totals["credit"]
        totals["gap"]=totals["balance_gap"]  # compatibilité avec les anciens appels
        return totals

    def _open_financial_card_details(self, title, key, total, start_date=None, end_date=None):
        """Affiche le détail qui compose une carte de la synthèse financière."""
        if key=="expenses" and hasattr(self,"financial_center_month"):
            center_start,center_end=self._center_period()
            if start_date==center_start and end_date==center_end:
                self._open_center_card_sources("expenses");return
        self._sync_pending_drafts()
        def in_period(value):
            d=self._parse_french_date(value)
            if d is None:return start_date is None and end_date is None
            return (start_date is None or d>=start_date) and (end_date is None or d<=end_date)
        rows=[]
        def add(date,ref,party,label,amount,status=""):
            rows.append((str(date or ""),str(ref or ""),str(party or ""),str(label or ""),float(amount or 0),str(status or "")))
        if key in ("receivables","revenue","bank","cash"):
            modes,payments=self._contract_payment_parts()
            for row in self.conn.execute("SELECT numero,date_depart,date_retour,duree,montant,reglement,client_code FROM contracts ORDER BY date_depart DESC"):
                share=self._contract_period_share(row[1],row[2],row[3],start_date,end_date)
                if not share:continue
                amount=max(0.0,self._number(row[4]));paid=min(amount,max(0.0,self._number(row[5])))
                cash,bank=payments.get(str(row[0]),(0.0,0.0));detail=cash+bank
                if detail>paid and detail>0:cash*=paid/detail;bank*=paid/detail
                initial=max(0.0,paid-cash-bank)
                mode=modes.get(str(row[0]),"ESPÈCES")
                if any(token in mode for token in ("CHÈQUE","CHEQUE","BANQUE","VIREMENT","CARTE")):bank+=initial
                else:cash+=initial
                allocated=self._contract_allocated_parts(row[1],row[2],row[3],amount,cash,bank,start_date,end_date)
                part=dict(zip(("revenue","cash","bank","receivables"),allocated))[key]
                if part>.005:add(row[1],row[0],row[6],"Part du contrat dans la période",part,"PRODUCTION")
        if key in ("expenses","bank","cash"):
            for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='expenses' ORDER BY created_at DESC"):
                try:q=json.loads(raw)
                except Exception:continue
                if not self._expense_is_executed(q):continue
                received=str(q.get("direction","")).upper() in ("REÇU","RECU")
                if received and q.get("source_check"):
                    if key=="bank" and self._expense_bank_in_period(q,start_date,end_date):
                        add(q.get("date"),rid,q.get("party"),q.get("description") or "Chèque client reçu",self._number(q.get("amount")),"ENTRÉE")
                    continue
                if str(q.get("type","")).upper()!="CHARGE":continue
                if key=="expenses":
                    if not self._expense_charge_in_period(q,start_date,end_date):continue
                elif not self._expense_bank_in_period(q,start_date,end_date):continue
                amt=self._number(q.get("amount"));mode=str(q.get("payment_method","")).upper();cat=str(q.get("category","")).upper()
                if key=="expenses" and cat not in ("RÈGLEMENT FOURNISSEUR","CRÉDIT HBZ / MENSUALITÉ"):
                    add(q.get("date"),rid,q.get("party"),q.get("description") or q.get("category"),amt,q.get("status"))
                elif key=="bank" and ("BANQUE" in mode or "CHÈQUE" in mode or "CHEQUE" in mode):
                    add(q.get("date"),rid,q.get("party"),q.get("description") or q.get("category"),-amt,"SORTIE")
                elif key=="cash" and "ESP" in mode:
                    add(q.get("date"),rid,q.get("party"),q.get("description") or q.get("category"),-amt,"SORTIE")
            if key in ("bank","cash"):
                for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='transfers' ORDER BY created_at DESC"):
                    try:q=json.loads(raw)
                    except Exception:continue
                    if not in_period(q.get("date","")):continue
                    amt=self._number(q.get("amount"));mode=str(q.get("mode","VERSEMENT BANQUE")).upper()
                    signed=(amt if "RETRAIT" not in mode else -amt) if key=="bank" else (-amt if "RETRAIT" not in mode else amt)
                    add(q.get("date"),rid,"",q.get("mode","Transfert"),signed,"TRANSFERT")
        elif key=="supplier_payable":
            for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='supplier_purchases' ORDER BY created_at DESC"):
                try:q=json.loads(raw)
                except Exception:continue
                if in_period(q.get("date","")):add(q.get("date"),rid,q.get("supplier_name") or q.get("supplier"),q.get("description") or "Dette fournisseur",self._number(q.get("total") or q.get("amount")),q.get("status"))
        elif key=='drafts_period_info':
            rows.extend(self._draft_period_info_rows(start_date,end_date))
        elif key in ("drafts_pending","checks_pending","drafts_other"):
            for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='checks' ORDER BY created_at DESC"):
                try:q=json.loads(raw)
                except Exception:continue
                kind=str(q.get("type","")).upper();due=self._parse_french_date(q.get("due_date",""))
                if kind not in ("TRAITE","CHÈQUE","CHEQUE") or not due or (kind!="TRAITE" and due.date()>datetime.now().date()+timedelta(days=3)) or str(q.get("status","")).upper()!="EN ATTENTE":continue
                if key=="checks_pending" and kind=="TRAITE":continue
                if key=="checks_pending" and str(q.get("direction","ÉMIS")).upper() in ("REÇU","RECU"):continue
                if key=="drafts_other" and kind!="TRAITE":continue
                add(q.get("due_date"),q.get("number") or rid,q.get("client"),f"{'Traite' if kind=='TRAITE' else 'Chèque'} à venir — {q.get('bank','')}",self._number(q.get("amount")),"INFORMATIF")
            # Même présentation informative pour les échéances HBZ Crédit.
            for rid,raw in (() if key=="checks_pending" else self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='expenses' ORDER BY created_at DESC")):
                try:q=json.loads(raw)
                except Exception:continue
                if str(q.get("category","")).upper()!="CRÉDIT HBZ / ÉCHÉANCE" or str(q.get("status","")).upper()!="EN ATTENTE":continue
                due=self._parse_french_date(q.get("date",""))
                if not due:continue
                add(q.get("date"),q.get("document") or rid,q.get("party"),q.get("description") or "Échéance HBZ Crédit à venir",self._number(q.get("amount")),"INFORMATIF")
        elif key=="credit_j10":
            today=datetime.now().date();limit=today+timedelta(days=10);db_path=self._hbz_credit_db_path()
            if db_path.exists():
                con=sqlite3.connect(str(db_path))
                try:
                    for ref,org,date_text,amount in con.execute("SELECT ref,COALESCE(organisme,''),date_ech,COALESCE(echeance,0) FROM echeances ORDER BY date_ech"):
                        try:due=datetime.strptime(str(date_text)[:10],"%Y-%m-%d").date()
                        except Exception:continue
                        if today<=due<=limit:add(due.strftime("%d/%m/%Y"),ref,org,"Échéance crédit à prélever",amount,"À PRÉLEVER")
                finally:con.close()
            for rid,raw in self.conn.execute("SELECT record_id,payload FROM module_records WHERE module='checks' ORDER BY created_at DESC"):
                try:q=json.loads(raw)
                except Exception:continue
                if str(q.get("type","")).upper()!="TRAITE" or str(q.get("status","")).upper()!="EN ATTENTE":continue
                due=self._parse_french_date(q.get("due_date",""))
                if due and today<=due.date()<=limit:add(q.get("due_date"),q.get("number") or rid,q.get("client"),"Traite à prélever",self._number(q.get("amount")),"À PRÉLEVER")
        win=self._secondary_window(self.root);win.title(f"Détail — {title}");win.geometry("1040x610");win.minsize(850,500);win.transient(self.root);win.configure(bg=BG)
        tk.Label(win,text=f"DÉTAIL • {title}",bg=NAVY,fg="white",font=("Segoe UI",16,"bold"),pady=12).pack(fill="x")
        # Le montant affiché doit toujours correspondre exactement aux lignes du tableau.
        detail_total=sum(amount for _date,_ref,_party,_label,amount,_status in rows)
        tk.Label(win,text=f"Montant de la carte : {detail_total:,.2f} MAD",bg="#eaf4fb",fg=NAVY,font=("Segoe UI",12,"bold"),pady=8).pack(fill="x")
        frame=tk.Frame(win,bg=BG);frame.pack(fill="both",expand=True,padx=16,pady=14)
        cols=("date","ref","party","label","amount","status");tree=ttk.Treeview(frame,columns=cols,show="headings")
        heads=(("date","Date",110),("ref","Référence",150),("party","Client / Organisme",180),("label","Libellé",300),("amount","Montant",120),("status","Statut",120))
        for c,h,w in heads:tree.heading(c,text=h);tree.column(c,width=w,anchor="center" if c in ("date","amount","status") else "w")
        sy=ttk.Scrollbar(frame,orient="vertical",command=tree.yview);sx=ttk.Scrollbar(frame,orient="horizontal",command=tree.xview);tree.configure(yscrollcommand=sy.set,xscrollcommand=sx.set)
        tree.grid(row=0,column=0,sticky="nsew");sy.grid(row=0,column=1,sticky="ns");sx.grid(row=1,column=0,sticky="ew");frame.grid_rowconfigure(0,weight=1);frame.grid_columnconfigure(0,weight=1)
        for date,ref,party,label,amount,status in rows:tree.insert("","end",values=(date,ref,party,label,f"{amount:,.2f} MAD",status))
        if not rows:tree.insert("","end",values=("","","","Aucun mouvement détaillé pour cette carte/période.","",""))
        tk.Button(win,text="Fermer",command=win.destroy,bg=NAVY,fg="white",relief="flat",padx=22,pady=8).pack(pady=(0,14))

    def open_financial_summary(self, custom_period=False, period=None):
        """Synthèse aux couleurs de Produits & Charges, avec les prévisions séparées."""
        if period is not None:
            start_text,end_text=period
        elif custom_period:
            chosen=self._choose_financial_period()
            if chosen is None:return
            start_text,end_text=chosen
        else:
            names=("Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre")
            month_text=self.expense_month_filter.get() if hasattr(self,"expense_month_filter") else "Tous les mois"
            year_text=self.expense_year_filter.get() if hasattr(self,"expense_year_filter") else ""
            year=int(year_text) if str(year_text).isdigit() else None
            if year and month_text in names:
                m=names.index(month_text)+1
                start_text=f"01/{m:02d}/{year}"
                end_text=f"{monthcalendar.monthrange(year,m)[1]:02d}/{m:02d}/{year}"
            elif year:start_text,end_text=f"01/01/{year}",f"31/12/{year}"
            else:start_text,end_text="",""
        start=self._parse_french_date(start_text) if start_text else None
        end=self._parse_french_date(end_text) if end_text else None
        if (start_text and not start) or (end_text and not end) or (start and end and end<start):
            messagebox.showwarning("Synthèse financière","Période invalide.");return
        totals=self._financial_totals(start,end)
        totals["drafts_pending"]=self._pending_drafts_total()
        totals["credit_j10"]=self._hbz_credit_due_10d_total()
        win=self._secondary_window(self.root)
        win.title("Synthèse financière — HBZ Rent Car")
        win.geometry("1160x750");win.minsize(960,670)
        win.transient(self.root);win.configure(bg=BG)
