        tk.Label(header,text="▣",bg="#168cf6",fg="white",width=2,pady=5,
                 font=("Segoe MDL2 Assets",23)).pack(side="left",padx=(0,12))
        titles=tk.Frame(header,bg=BG);titles.pack(side="left",fill="x",expand=True)
