    def refresh_history(self):
        if not hasattr(self,"history_tree"): return
        rows=self._history_rows(self.history_query.get(),"CONTRATS",self.history_month.get(),self.history_year.get(),self.history_client.get(),self.history_vehicle.get())
        selected=self.history_tree.selection()
        selected_no=str(self.history_tree.item(selected[0],'values')[0]) if selected else ''
        self.history_tree.delete(*self.history_tree.get_children()); income=balance=0.0
        selected_item=None
        for index,row in enumerate(rows):
            income+=row[9]; balance+=row[10]
            values=row[:9]+(('' if row[11]=='Jour de passage · Épargne' else f"{row[9]:.2f}"),('' if row[11]=='Jour de passage · Épargne' else f"{row[10]:.2f}"),row[11],row[12])
            status=row[11]
            tag=('returned' if 'confirmé' in status.lower() and 'retard' not in status.lower() else
                 'late' if 'retard' in status.lower() else 'near' if 'proche' in status.lower() else
                 'closed' if status.startswith(('Annulé','Échéance')) else 'rented')
            iid=f"{row[0]}:{index}"
            self.history_tree.insert('','end',iid=iid,values=values,tags=(tag,))
            if selected_no==str(row[0]) and selected_item is None:selected_item=iid
        from signed_contracts import refresh_signed_column
        refresh_signed_column(self.history_tree)
        if selected_item:self.history_tree.selection_set(selected_item)
        self._history_show_selected_status()
        from history_layout import filtered_ca_averages
        annual,monthly=filtered_ca_averages(income,rows,self.history_month.get(),self.history_year.get())
        self.history_totals['annual'].set(f'{annual:,.2f} MAD/an')
        self.history_totals['monthly'].set(f'{monthly:,.2f} MAD/mois')
        self.history_totals["count"].set(str(len({row[0] for row in rows}))); self.history_totals["income"].set(f"{income:,.2f} MAD"); self.history_totals["balance"].set(f"{balance:,.2f} MAD")
        if hasattr(self,'_history_alarm_refresh'):self._history_alarm_refresh()
        if hasattr(self,'_archive_history_refresh'):self._archive_history_refresh()

    def _history_show_selected_status(self,_event=None):
        if not hasattr(self,'history_selected_status'):return
        selection=self.history_tree.selection() if hasattr(self,'history_tree') else ()
        if not selection:
            self.history_selected_status.set('Sélectionnez une location pour voir son statut de retour.')
            return
        values=self.history_tree.item(selection[0],'values')
        self.history_selected_status.set(f"Contrat {values[0]}  ·  {values[11]}  ·  Retour effectif : {values[12]}")

    def history_change_vehicle_status(self,numero=None):
        """Modifie un retour via les parcours métier, sans altérer les montants par erreur."""
        numero=numero or self._history_selected_contract_number()
        if not numero:return
        row=self.conn.execute('SELECT * FROM contracts WHERE numero=?',(numero,)).fetchone()
        if row is None:return
        status=self._history_vehicle_status(row)
        win=self._secondary_window(self.root);win.title('Statut du véhicule — historique')
        win.geometry('660x400');win.resizable(False,False);win.transient(self.root)
        win.grab_set();win.configure(bg=BG)
        tk.Label(win,text='MODIFIER LE STATUT DU VÉHICULE',bg=NAVY,fg='white',
                 font=('Segoe UI',14,'bold'),anchor='w',padx=18,pady=13).pack(fill='x')
        tk.Label(win,text=f"Contrat {numero}   ·   Véhicule {row['vehicle_code']}",bg=BG,fg=NAVY,
                 font=('Segoe UI',11,'bold')).pack(anchor='w',padx=22,pady=(17,4))
        tk.Label(win,text=f"Statut actuel : {status}\nRetour prévu : {row['date_retour']} à {row['heure_retour'] or '23:59'}",
                 bg=BG,fg=TEXT,font=('Segoe UI',9),justify='left').pack(anchor='w',padx=22,pady=(0,13))
        buttons=tk.Frame(win,bg=BG);buttons.pack(fill='x',padx=18)
        for col in range(2):buttons.grid_columnconfigure(col,weight=1)
        choices=(('✓  Retour confirmé','return','#e3f6eb','#196747'),
                 ('●  Encore en location','rented','#e3f1fc','#145a86'),
                 ('!  Retard confirmé','late','#ffe8ea','#9c303b'),
                 ('↗  Prolonger','extend','#eee8fc','#6240a1'),
                 ('↶  Retour anticipé','early','#e5f2ff','#145a86'),
                 ('×  Annuler la location','cancel','#fce9e9','#a12d3c'))
        for i,(label,action,soft,ink) in enumerate(choices):
            tk.Button(buttons,text=label,command=lambda a=action:(win.destroy(),self.root.after(40,lambda:self._history_apply_status(numero,a))),
                      bg=soft,fg=ink,relief='flat',padx=13,pady=12,
                      font=('Segoe UI',9,'bold'),anchor='w').grid(row=i//2,column=i%2,sticky='ew',padx=5,pady=5)
        tk.Button(win,text='Fermer',command=win.destroy,bg='#e8edf1',fg=TEXT,
                  relief='flat',padx=22,pady=7).pack(side='right',padx=24,pady=12)

    def _history_apply_status(self,numero,action):
        row=self.conn.execute('SELECT * FROM contracts WHERE numero=?',(numero,)).fetchone()
        if row is None:return
        state=str(row['return_status'] or '')
        if action=='return':
            if self._is_returned_contract(state) or row['actual_return_date']:
                self._professional_notice('Statut du véhicule','Ce retour est déjà enregistré.','✓',GREEN);return
            self._confirm_history_return_for(numero);return
        if action=='cancel':self.cancel_vehicle_contract(numero);return
        if action in ('extend','early'):
            if self._is_returned_contract(state) or row['actual_return_date']:
                self._professional_notice('Statut du véhicule','Ce contrat est déjà clôturé.','!',ORANGE);return
            if action=='extend':self.extend_vehicle_return(numero)
            else:self.anticipate_vehicle_return(numero)
            self.refresh_history();self.refresh_contract_history();return
        if 'ANNUL' in state.upper() or 'ANTICIP' in state.upper():
            self._professional_notice('Statut du véhicule','Une location annulée ou un retour anticipé doit être corrigé dans sa fiche de location.','!',ORANGE);return
        now=datetime.now();start=self._contract_datetime(row['date_depart'],row['heure_depart'])
        due=self._contract_datetime(row['date_retour'],row['heure_retour'],True)
        if not start or not due or now<start:
            self._professional_notice('Statut du véhicule','La période du contrat n’a pas commencé.','!',ORANGE);return
        if action=='rented' and now>=due:
            self._professional_notice('Statut du véhicule','L’échéance est passée. Prolongez la location ou confirmez explicitement un retard.','!',ORANGE);return
        if action=='late' and now<=due:
            self._professional_notice('Statut du véhicule','Le retour prévu n’est pas encore dépassé.','!',ORANGE);return
        if action=='rented' and not state and not row['actual_return_date']:
            self._professional_notice('Statut du véhicule','Le véhicule est déjà en location.','✓',GREEN);return
        if action=='late' and self._is_confirmed_delay(state):
            self._professional_notice('Statut du véhicule','Le retard de ce véhicule est déjà confirmé.','✓',GREEN);return
        # Ne jamais rouvrir une ancienne location si une autre occupe déjà le véhicule.
        others=self.conn.execute('SELECT * FROM contracts WHERE vehicle_code=? AND numero<>?',
                                 (row['vehicle_code'],numero)).fetchall()
        for other in others:
            if self._is_returned_contract(other['return_status']) or other['actual_return_date']:continue
            other_start=self._contract_datetime(other['date_depart'],other['heure_depart'])
            other_due=self._contract_datetime(other['date_retour'],other['heure_retour'],True)
            if other_start and other_start<=now and ((other_due and now<other_due) or self._is_confirmed_delay(other['return_status'])):
                self._professional_notice('Statut du véhicule',f"Le véhicule est déjà lié au contrat actif {other['numero']}.",'!',ORANGE);return
        new_state='RETARD CONFIRMÉ' if action=='late' else ''
        label='retard confirmé' if action=='late' else 'encore en location'
        if not self._professional_confirm('Corriger le statut',f"Déclarer le véhicule {label} pour le contrat {numero} ?\n\nCette correction modifie la disponibilité du parc.",'!',ORANGE):return
        self.conn.execute('UPDATE contracts SET return_status=?,actual_return_date=NULL,actual_return_time=NULL WHERE numero=?',
                          (new_state,numero))
        self._audit('STATUT VÉHICULE','CONTRAT',numero,f"{state or 'sans statut'} → {new_state or 'EN LOCATION'} depuis Historique général")
        self.conn.commit();self.refresh_history();self.refresh_dashboard();self.refresh_alerts();self.schedule_web_sync()

    def clear_history_filters(self):
        self.history_query.set(""); self.history_mode.set("CONTRATS"); self.history_month.set(("Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre")[datetime.now().month-1]); self.history_year.set(str(datetime.now().year)); self.history_client.set("Tous les clients"); self.history_vehicle.set("Tous les véhicules"); self.refresh_history()

    def _history_selected_contract_number(self):
        selected=self.history_tree.selection() if hasattr(self,"history_tree") else ()
        if not selected: self._professional_notice("Historique","Sélectionnez d’abord un contrat.","!",ORANGE); return ""
        values=self.history_tree.item(selected[0],"values"); return str(values[0]).strip() if values else ""

    def history_confirm_return(self):
        """Confirme le retour depuis Historique général et libère immédiatement le véhicule."""
        numero=self._history_selected_contract_number()
        if not numero:return
        self._confirm_history_return_for(numero)

    def _confirm_history_return_for(self,numero):
        row=self.conn.execute("SELECT vehicle_code,km_retour,actual_return_date,COALESCE(return_status,'') return_status FROM contracts WHERE numero=?",(numero,)).fetchone()
        if not row:return
        state=str(row["return_status"] or "").upper()
        if "ANNUL" in state:
            self._professional_notice("Retour véhicule","Ce contrat est annulé.","!",ORANGE);return
        if self._is_returned_contract(state) or row['actual_return_date']:
            self._professional_notice("Retour véhicule",f"Le retour du contrat {numero} est déjà confirmé.","✓",GREEN);return
        now=datetime.now()
        if not self._professional_confirm("Confirmer le retour",f"Confirmer le retour du véhicule du contrat {numero} ?\n\nLe véhicule sera immédiatement considéré disponible pour toute nouvelle location commençant après cette confirmation.","✓",GREEN):return
        self.conn.execute("UPDATE contracts SET return_status='RETOUR CONFIRMÉ',actual_return_date=?,actual_return_time=? WHERE numero=?",(now.strftime("%d/%m/%Y"),now.strftime("%H:%M"),numero))
        if int(row['km_retour'] or 0)>0:
            self.conn.execute('UPDATE vehicles SET compteur=MAX(compteur,?) WHERE code=?',(int(row['km_retour']),row['vehicle_code']))
        self._audit("RETOUR","CONTRAT",numero,f"Retour confirmé depuis Historique général le {now:%d/%m/%Y à %H:%M}")
        self.conn.commit()
        self.refresh_history();self.refresh_contract_history();self.refresh_dashboard();self.refresh_vehicles();self.refresh_alerts();self.schedule_web_sync()
        self._professional_notice("Retour véhicule",f"Retour du contrat {numero} confirmé.\nLe véhicule est maintenant libéré.","✓",GREEN)

    def history_edit_location(self):
        numero=self._history_selected_contract_number()
        if not numero:return
        self.open_quick_contract_dialog(contract_number=numero)

    def history_delete_location(self):
        numero=self._history_selected_contract_number()
        if not numero:return
        row=self.conn.execute("SELECT client_code,vehicle_code,montant FROM contracts WHERE numero=?",(numero,)).fetchone()
        if not row:return
        if not self._professional_confirm("Supprimer une location",f"Supprimer définitivement la location {numero} ?\n\nMontant retiré du chiffre d’affaires : {float(row['montant'] or 0):.2f} MAD","🗑",RED):return
        self.conn.execute("DELETE FROM contracts WHERE numero=?",(numero,)); self._audit("SUPPRESSION","CONTRAT",numero,"Suppression depuis Historique général"); self.conn.commit(); self.refresh_history(); self.refresh_dashboard(); self.schedule_web_sync()

    def history_to_location(self):
        selected=self.history_tree.selection() if hasattr(self,"history_tree") else ()
        if not selected: messagebox.showwarning("Historique","Sélectionnez d'abord un contrat."); return
        values=self.history_tree.item(selected[0],"values")
        if len(values)<9:return
        client_code,vehicle_code=str(values[5]).strip(),str(values[7]).strip(); self.new_contract(); self.vars["client_code"].set(client_code); self.load_client(); self.vars["vehicle_code"].set(vehicle_code); self.load_vehicle(); self.vars["date_start"].set(datetime.now().strftime("%d/%m/%Y")); self.vars["date_end"].set((datetime.now()+timedelta(days=1)).strftime("%d/%m/%Y")); self.calculate(); self.show_page("contract")

