    def _alert_selected_return(self, action):
        selected=self.alerts_tree.selection() if hasattr(self,"alerts_tree") else ()
        if not selected:
            messagebox.showwarning("Alertes", "Sélectionnez une alerte de retour dans la liste.")
            return
        values=self.alerts_tree.item(selected[0],"values")
        if len(values)<3 or not str(values[1]).startswith("RETOUR LOCATION"):
            messagebox.showwarning("Alertes", "Cette action concerne uniquement une alerte de retour de location.")
            return
        reference=values[2]
        if action=="confirm":self.confirm_vehicle_return(reference)
        elif action=="extend":self.extend_vehicle_return(reference)
        else:self.anticipate_vehicle_return(reference)

    def _confirm_selected_returns(self, tree, parent=None):
        selected=tree.selection() if tree else ()
        references=[]
        for item in selected:
            values=tree.item(item,"values")
            if len(values)>=3 and str(values[1]).startswith("RETOUR LOCATION"):
                references.append(str(values[2]))
        references=list(dict.fromkeys(references))
        if not references:
            messagebox.showwarning("Retours","Sélectionnez une ou plusieurs lignes de retour.",parent=parent);return
        if not self._professional_confirm("Confirmation groupée",f"Confirmer simultanément {len(references)} retour(s) sélectionné(s) ?","✓✓",GREEN,parent):return
        today=datetime.now().strftime("%d/%m/%Y")
        for contract_no in references:
            row=self.conn.execute("SELECT vehicle_code,km_retour FROM contracts WHERE numero=?",(contract_no,)).fetchone()
            if not row:continue
            self.conn.execute("UPDATE contracts SET return_status='RETOUR CONFIRMÉ',actual_return_date=? WHERE numero=?",(today,contract_no))
            if int(row[1] or 0)>0:self.conn.execute("UPDATE vehicles SET compteur=MAX(compteur,?) WHERE code=?",(int(row[1]),row[0]))
            self._audit("RETOUR CONFIRMÉ","CONTRAT",contract_no,f"Confirmation groupée — {today}")
        self.conn.commit();self.refresh_alerts();self.refresh_vehicles();self.refresh_dashboard()
        if parent and parent.winfo_exists():parent.destroy()
        messagebox.showinfo("Retours",f"{len(references)} retour(s) confirmé(s) avec succès.")

    def _alert_vehicle(self, item):
        """Associe une alerte au véhicule réellement cité par sa source métier."""
        category=str(item[1] or "").upper()
        reference=str(item[2] or "")
        code=""
        if category.startswith("RETOUR LOCATION"):
            contract=self.conn.execute("SELECT vehicle_code FROM contracts WHERE numero=?",(reference,)).fetchone()
            code=str(contract[0] or "") if contract else ""
        elif category.startswith(("TECHNIQUE","ADMINISTRATIF")) or category in (
                "ENTRETIEN","ADBLUE","VIDANGE","CHAÎNE","CHAINE","ASSURANCE","CONTRÔLE TECHNIQUE"):
            direct=self.conn.execute("SELECT code FROM vehicles WHERE code=?",(reference,)).fetchone()
            if direct:code=str(direct[0])
            else:
                record=self.conn.execute("SELECT payload FROM module_records WHERE module='maintenance' AND record_id=?",(reference,)).fetchone()
                if record:
                    try:code=str(json.loads(record[0]).get("vehicle","")).split("|")[0].strip()
                    except (ValueError,TypeError):pass
        elif category in ("RÉSERVATION","RENDEZ-VOUS","CHÈQUE / TRAITE"):
            module={"RÉSERVATION":"reservations","RENDEZ-VOUS":"planning","CHÈQUE / TRAITE":"checks"}[category]
            record=self.conn.execute("SELECT payload FROM module_records WHERE module=? AND record_id=?",(module,reference)).fetchone()
            if record:
                try:
                    details=json.loads(record[0])
                    code=str(details.get("vehicle_code") or details.get("vehicle") or details.get("vehicule") or "").split("|")[0].strip()
                except (ValueError,TypeError):pass
        elif category.startswith("ÉCHÉANCE CRÉDIT"):
            # La base HBZ Crédit conserve seulement un organisme/libellé, jamais
            # un code de voiture. Une correspondance de modèle doit être unique.
            label=str(item[3] or "").split(" — ",1)[0].strip()
            normalized=lambda value:re.sub(r"[^A-Z0-9]+"," ",str(value or "").upper()).strip()
            needle=normalized(label)
            if len(needle)>=4:
                fleet=self.conn.execute("SELECT code,modele FROM vehicles").fetchall()
                matches=[row for row in fleet if needle==normalized(row['modele']) or
                         (f" {needle} " in f" {normalized(row['modele'])} ")]
                if len(matches)==1:code=str(matches[0]['code'])
        if not code:return None
        return self.conn.execute("SELECT code,modele,photo FROM vehicles WHERE code=?",(code,)).fetchone()

    def _alert_display_row(self, item, photo_cache):
        """Renvoie la ligne enrichie et garde les miniatures actives pour Tkinter."""
        vehicle=self._alert_vehicle(item)
        if vehicle is None:return item,None
        code=str(vehicle["code"]);model=str(vehicle["modele"] or code)
        values=list(item)
        if model.casefold() not in str(values[3]).casefold():
            values[3]=f"{model} ({code}) — {values[3]}"
        if code not in photo_cache:
            photo_cache[code]=None
            path=self._resolve_vehicle_photo_path(vehicle["photo"],code)
            if path:
                try:
                    from PIL import Image,ImageTk,ImageOps
                    with Image.open(path) as original:
                        picture=ImageOps.exif_transpose(original)
                        picture.thumbnail((64,45),Image.Resampling.LANCZOS)
                        photo_cache[code]=ImageTk.PhotoImage(picture,master=self.root)
                except (OSError,ValueError,ImportError,tk.TclError):pass
        return tuple(values),photo_cache[code]

    def refresh_alerts(self):
        if not hasattr(self, "alerts_tree"): return
        alerts=self._filtered_alerts(); self.alerts_tree.delete(*self.alerts_tree.get_children())
        self._alert_row_images={}
        for item in alerts:
            display,photo=self._alert_display_row(item,self._alert_row_images)
            self.alerts_tree.insert("","end",text="" if photo else "🚘" if self._alert_vehicle(item) else "—",
                                    values=display,image=photo or "",tags=(item[0],))
        for name,var in self.alert_count_vars.items(): var.set(str(sum(1 for item in alerts if item[0]==name)))
        if hasattr(self, "alert_credit_total_var"):
            total=0.0
            for item in alerts:
                if item[1] != "ÉCHÉANCE CRÉDIT HBZ":
                    continue
                match=re.search(r"([0-9][0-9 ]*(?:[.,][0-9]{1,2})?)\s*MAD", str(item[3]))
                if match:
                    total += self._number(match.group(1).replace(" ", ""))
            self.alert_credit_total_var.set(f"{total:,.2f} MAD".replace(",", " "))

    def _filtered_alerts(self):
        alerts=self.collect_alerts()
        month=getattr(self,"alert_month_filter",None); year=getattr(self,"alert_year_filter",None); vehicle=getattr(self,"alert_vehicle_filter",None)
        month_value=month.get() if month else "Tous les mois"; year_value=year.get() if year else "Toutes les années"; vehicle_value=vehicle.get() if vehicle else "Tous les véhicules"
        month_names=("Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre")
        month_number=month_names.index(month_value)+1 if month_value in month_names else None
        vehicle_code=vehicle_value.split("|",1)[0].strip() if vehicle_value!="Tous les véhicules" else ""
        result=[]
        for item in alerts:
            due=self._parse_french_date(str(item[4]).split()[0])
            if month_number and (not due or due.month!=month_number):continue
            if year_value.isdigit() and (not due or due.year!=int(year_value)):continue
            if vehicle_code:
                linked=self._alert_vehicle(item)
                if (not linked or str(linked['code'])!=vehicle_code) and vehicle_code not in f"{item[2]} {item[3]}":continue
            result.append(item)
        return result

    def clear_alert_filters(self):
        self.alert_month_filter.set("Tous les mois");self.alert_year_filter.set("Toutes les années");self.alert_vehicle_filter.set("Tous les véhicules");self.refresh_alerts()

    def open_whatsapp_for_contract(self, contract_no, parent=None):
        """Ouvre WhatsApp Web vers le téléphone du client du contrat."""
        row = self.conn.execute(
            "SELECT cl.telephone FROM contracts c LEFT JOIN clients cl ON cl.code=c.client_code "
            "WHERE c.numero=?", (contract_no,)).fetchone()
        raw_phone = str(row[0] or "") if row else ""
        phone = re.sub(r"\D", "", raw_phone)
        if phone.startswith("0"):
            phone = "212" + phone[1:]
        if not phone:
            messagebox.showwarning("WhatsApp", "Aucun numéro de téléphone valide pour ce client.", parent=parent)
            return
        webbrowser.open(f"https://wa.me/{phone}")

