    def reset_password_dialog(self, parent=None):
        admin=simpledialog.askstring("Réinitialiser le mot de passe","Identifiant administrateur :",parent=parent or self.root)
        if not admin:return
        secret=simpledialog.askstring("Réinitialiser le mot de passe","Mot de passe administrateur :",show="•",parent=parent or self.root)
        row=self.conn.execute("SELECT password_hash,active FROM users WHERE username=? AND role='ADMINISTRATEUR'",(admin.strip(),)).fetchone();valid=False
        if row and row[1] and secret:
            try:
                _prefix,salt,digest=str(row[0]).split("$",2);valid=hashlib.pbkdf2_hmac("sha256",secret.encode(),salt.encode("ascii"),200000).hex()==digest
            except (ValueError,AttributeError):pass
        if not valid:messagebox.showerror("Réinitialisation","Accès administrateur refusé.",parent=parent or self.root);return
        target=simpledialog.askstring("Réinitialiser le mot de passe","Identifiant du compte à modifier :",parent=parent or self.root)
        new_password=simpledialog.askstring("Nouveau mot de passe","Nouveau mot de passe (8 caractères minimum) :",show="•",parent=parent or self.root)
        if not target or not new_password or len(new_password)<8:messagebox.showwarning("Réinitialisation","Mot de passe invalide.",parent=parent or self.root);return
        if not self.conn.execute("SELECT 1 FROM users WHERE username=?",(target.strip(),)).fetchone():messagebox.showwarning("Réinitialisation","Utilisateur introuvable.",parent=parent or self.root);return
        self.conn.execute("UPDATE users SET password_hash=? WHERE username=?",(self._password_hash(new_password),target.strip()));self.conn.commit();messagebox.showinfo("Réinitialisation","Mot de passe réinitialisé avec succès.",parent=parent or self.root)

    def _login_account_for_role(self,role,password):
        """Identifie un unique compte actif par rôle et mot de passe, sans identifiant affiché."""
        import hmac
        if role not in ("ADMINISTRATEUR","UTILISATEUR") or not password:return None
        matches=[]
        for row in self.conn.execute("SELECT username,display_name,password_hash,role,active FROM users WHERE role=? AND active=1",(role,)):
            try:
                prefix,salt,digest=str(row[2]).split("$",2)
                if prefix!="pbkdf2_sha256":continue
                actual=hashlib.pbkdf2_hmac("sha256",password.encode("utf-8"),salt.encode("ascii"),200000).hex()
                if hmac.compare_digest(actual,digest):matches.append(row)
            except (ValueError,AttributeError,UnicodeError):continue
        if len(matches)>1:raise ValueError("Plusieurs comptes de ce profil utilisent ce mot de passe. L’administrateur doit leur attribuer des mots de passe distincts.")
        return matches[0] if matches else None

    def show_login(self):
        from login_reference import show_login
        return show_login(self)

    def confirm_vehicle_return(self, contract_no, alert_window=None):
        row=self.conn.execute("SELECT vehicle_code,km_retour FROM contracts WHERE numero=?",(contract_no,)).fetchone()
        if not row:
            messagebox.showwarning("Retour véhicule","Contrat introuvable.",parent=alert_window); return
        if not self._professional_confirm("Retour confirmé",f"Confirmer le retour du contrat {contract_no} ?","✓",GREEN,alert_window): return
        today=datetime.now().strftime("%d/%m/%Y")
        self.conn.execute("UPDATE contracts SET return_status='RETOUR CONFIRMÉ',actual_return_date=? WHERE numero=?",(today,contract_no))
        if int(row[1] or 0)>0:
            self.conn.execute("UPDATE vehicles SET compteur=MAX(compteur,?) WHERE code=?",(int(row[1]),row[0]))
        self._audit("RETOUR CONFIRMÉ","CONTRAT",contract_no,today); self.conn.commit(); self.refresh_alerts(); self.refresh_vehicles();self.refresh_dashboard()
        if alert_window and alert_window.winfo_exists(): alert_window.destroy()
        messagebox.showinfo("Retour véhicule","Retour confirmé et véhicule remis disponible.")

    def cancel_vehicle_contract(self, contract_no, parent=None):
        """Annule une location active tout en conservant sa trace dans l'historique."""
        row=self.conn.execute("SELECT numero,vehicle_code,client_code,montant,reglement,reste,return_status FROM contracts WHERE numero=?",(contract_no,)).fetchone()
        if not row:
            self._professional_notice("Annulation de location","Contrat introuvable.","!",RED,parent);return
        current_state=str(row["return_status"] or "").upper()
        if self._is_returned_contract(current_state):
            self._professional_notice("Annulation de location","Cette location est déjà clôturée et ne peut plus être annulée depuis le tableau de bord.","!",RED,parent);return
        warning=(f"Annuler la location {contract_no} ?\n\n"
                 f"Client : {row['client_code'] or '—'}\nVéhicule : {row['vehicle_code'] or '—'}\n\n"
                 "Le contrat restera visible dans l’historique avec le statut ANNULÉ. "
                 "Son montant, son règlement et son reste à payer seront ramenés à zéro afin de ne plus être comptabilisés.")
        if not self._professional_confirm("Annuler la location",warning,"✕",RED,parent,height_cm=9.2):return
        old_values=f"montant={float(row['montant'] or 0):.2f}; règlement={float(row['reglement'] or 0):.2f}; reste={float(row['reste'] or 0):.2f}"
        today=datetime.now().strftime("%d/%m/%Y")
        self.conn.execute("UPDATE contracts SET montant=0,reglement=0,reste=0,return_status='ANNULÉ',actual_return_date=? WHERE numero=?",(today,contract_no))
        self._audit("ANNULATION","CONTRAT",contract_no,old_values)
        self.conn.commit();self.refresh_dashboard();self.refresh_alerts();self.refresh_vehicles()
        if hasattr(self,"history_tree"):self.refresh_history()
        if hasattr(self,"receivables_tree"):self.refresh_receivables()
        self.schedule_web_sync()
        self._professional_notice("Location annulée",f"Le contrat {contract_no} est annulé.\nLe véhicule est de nouveau disponible.","✓",GREEN,parent)
        self.root.after(100,lambda:self._open_modified_contract_documents(contract_no,"ANNULATION"))

    def extend_vehicle_return(self, contract_no, alert_window=None):
        row=self.conn.execute("SELECT date_depart,date_retour,heure_retour,prix,reglement,montant,reste,vehicle_code FROM contracts WHERE numero=?",(contract_no,)).fetchone()
        if not row:
            self._professional_notice("Prolongation","Contrat introuvable.","!",RED,alert_window); return
        start_date=self._parse_french_date(row['date_depart']); old_date=self._parse_french_date(row['date_retour'])
        if not start_date or not old_date:
            self._professional_notice("Prolongation","Dates du contrat invalides.","!",RED,alert_window); return
        win=self._secondary_window(self.root);win.title("Prolongation — HBZ Rent Car");win.configure(bg=BG);win.resizable(False,False)
        win.geometry("620x500");win.transient(alert_window or self.root);win.grab_set()
        head=tk.Frame(win,bg=PURPLE);head.pack(fill="x")
        tk.Label(head,text="↗  PROLONGATION DE LOCATION",bg=PURPLE,fg="white",font=("Segoe UI",15,"bold"),pady=14).pack(side="left",padx=18)
        tk.Label(head,text=f"Contrat {contract_no}",bg=PURPLE,fg="white",font=("Segoe UI",9,"bold")).pack(side="right",padx=18)
        body=tk.Frame(win,bg=BG);body.pack(fill="both",expand=True,padx=18,pady=15)
        current=tk.Frame(body,bg="#f3efff",highlightbackground=BORDER,highlightthickness=1);current.pack(fill="x",pady=(0,12))
        tk.Label(current,text="RETOUR ACTUEL",bg="#f3efff",fg=MUTED,font=("Segoe UI",9,"bold")).pack(anchor="w",padx=14,pady=(9,1))
        tk.Label(current,text=f"{row['date_retour']}  •  {row['heure_retour'] or '18:00'}",bg="#f3efff",fg=PURPLE,font=("Segoe UI",13,"bold")).pack(anchor="w",padx=14,pady=(0,9))
        fields=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1);fields.pack(fill="x");fields.grid_columnconfigure(1,weight=1)
        date_var=tk.StringVar(value=(old_date+timedelta(days=1)).strftime("%d/%m/%Y"));time_var=tk.StringVar(value=row['heure_retour'] or "18:00")
        tk.Label(fields,text="Nouvelle date de retour",bg=CARD,fg=TEXT,font=("Segoe UI",10,"bold")).grid(row=0,column=0,sticky="w",padx=14,pady=(14,8))
        ent=tk.Entry(fields,textvariable=date_var,font=("Segoe UI",11),relief="solid",bd=1);ent.grid(row=0,column=1,sticky="ew",padx=(8,46),pady=(14,8),ipady=7)
        tk.Button(fields,text="▣",command=lambda:self.open_date_picker(date_var,ent),bg=BLUE,fg="white",relief="flat",font=("Segoe UI",11,"bold")).grid(row=0,column=1,sticky="e",padx=10,pady=(14,8),ipadx=8,ipady=5)
        tk.Label(fields,text="Nouvelle heure",bg=CARD,fg=TEXT,font=("Segoe UI",10,"bold")).grid(row=1,column=0,sticky="w",padx=14,pady=(4,14))
        ttk.Combobox(fields,textvariable=time_var,values=self._times(),state="normal",width=12).grid(row=1,column=1,sticky="w",padx=8,pady=(4,14))
        summary=tk.Frame(body,bg="#f8fbfd",highlightbackground=BORDER,highlightthickness=1);summary.pack(fill="x",pady=12)
        days_var=tk.StringVar(value="—");extra_var=tk.StringVar(value="—");total_var=tk.StringVar(value="—");balance_var=tk.StringVar(value="—")
        for i,(lab,var) in enumerate((("Durée totale",days_var),("Supplément CA",extra_var),("Nouveau montant",total_var),("Nouveau reste",balance_var))):
            cell=tk.Frame(summary,bg="#f8fbfd");cell.grid(row=i//2,column=i%2,sticky="nsew",padx=12,pady=8);summary.grid_columnconfigure(i%2,weight=1)
            tk.Label(cell,text=lab,bg="#f8fbfd",fg=MUTED,font=("Segoe UI",8,"bold")).pack(anchor="w");tk.Label(cell,textvariable=var,bg="#f8fbfd",fg=(GREEN if i==1 else NAVY),font=("Segoe UI",12,"bold")).pack(anchor="w")
        def calc(show=False):
            nd=self._parse_french_date(date_var.get().strip())
            try: datetime.strptime(time_var.get().strip(),"%H:%M")
            except ValueError: nd=None
            if not nd or nd<=old_date:
                days_var.set("Date invalide");extra_var.set("—");total_var.set("—");balance_var.set("—")
                if show:self._professional_notice("Prolongation","La nouvelle date doit être strictement postérieure au retour actuel et l’heure doit être au format HH:MM.","!",RED,win)
                return None
            days=max(1,(nd-start_date).days);price=float(row['prix'] or 0);paid=float(row['reglement'] or 0);old_total=float(row['montant'] or 0);new_total=round(price*days,2);extra=round(new_total-old_total,2);balance=round(max(0,new_total-paid),2)
            days_var.set(f"{days} jour(s)");extra_var.set(f"+{extra:,.2f} MAD");total_var.set(f"{new_total:,.2f} MAD");balance_var.set(f"{balance:,.2f} MAD");return nd,days,new_total,extra,balance
        date_var.trace_add("write",lambda *_:calc(False));time_var.trace_add("write",lambda *_:calc(False));calc(False)
        buttons=tk.Frame(body,bg=BG);buttons.pack(fill="x",pady=(5,0));tk.Button(buttons,text="✕  Annuler",command=win.destroy,bg="#e9eef2",fg=TEXT,relief="flat",font=("Segoe UI",11,"bold"),padx=20,pady=11).pack(side="left")
        def confirm():
            c=calc(True)
            if not c:return
            nd,days,new_total,extra,balance=c
            self.conn.execute("UPDATE contracts SET date_retour=?,heure_retour=?,duree=?,montant=?,reste=?,return_status='PROLONGÉ' WHERE numero=?",(date_var.get().strip(),time_var.get().strip(),days,new_total,balance,contract_no))
            self._audit("PROLONGATION","CONTRAT",contract_no,f"CA +{extra:.2f} MAD | nouveau montant {new_total:.2f} MAD | retour {date_var.get()} {time_var.get()}")
            self.conn.commit();self.refresh_dashboard();self.refresh_alerts();self.schedule_web_sync();win.destroy()
            if alert_window and alert_window.winfo_exists():alert_window.destroy()
            self._professional_notice("Prolongation",f"Prolongation enregistrée.\n\nSupplément ajouté au CA : {extra:.2f} MAD\nNouveau montant du contrat : {new_total:.2f} MAD","✓",GREEN)
            self.root.after(100,lambda:self._open_modified_contract_documents(contract_no,"PROLONGATION"))
        tk.Button(buttons,text="✓  Confirmer la prolongation",command=confirm,bg=GREEN,fg="white",relief="flat",font=("Segoe UI",11,"bold"),padx=22,pady=11).pack(side="right")
        win.protocol("WM_DELETE_WINDOW",win.destroy);ent.focus_set()

    def anticipate_vehicle_return(self, contract_no, alert_window=None):
        row=self.conn.execute("SELECT date_depart,date_retour,heure_retour,prix,reglement,montant,reste FROM contracts WHERE numero=?",(contract_no,)).fetchone()
        if not row:
            messagebox.showwarning("Retour anticipé","Contrat introuvable.",parent=alert_window); return
        start=self._parse_french_date(row['date_depart']); old=self._parse_french_date(row['date_retour'])
        if not start or not old:
            messagebox.showwarning("Retour anticipé","Dates du contrat invalides.",parent=alert_window); return

        win=self._secondary_window(self.root); win.title("Retour anticipé — HBZ Rent Car"); win.configure(bg=BG)
        win.resizable(False,False); win.transient(alert_window or self.root); win.grab_set()
        try: win.geometry("620x555")
        except Exception: pass
        head=tk.Frame(win,bg=NAVY); head.pack(fill="x")
        tk.Label(head,text="↶",bg=NAVY,fg="white",font=("Segoe UI",22,"bold")).pack(side="left",padx=(18,10),pady=13)
        tk.Label(head,text="RETOUR ANTICIPÉ",bg=NAVY,fg="white",font=("Segoe UI",15,"bold")).pack(side="left")
        tk.Label(head,text=f"Contrat {contract_no}",bg=NAVY,fg="#d9efff",font=("Segoe UI",9,"bold")).pack(side="right",padx=18)

        body=tk.Frame(win,bg=BG); body.pack(fill="both",expand=True,padx=18,pady=15)
        planned=tk.Frame(body,bg="#eef6fb",highlightbackground=BORDER,highlightthickness=1); planned.pack(fill="x",pady=(0,12))
        tk.Label(planned,text="RETOUR PRÉVU",bg="#eef6fb",fg=MUTED,font=("Segoe UI",9,"bold")).pack(anchor="w",padx=14,pady=(9,1))
        tk.Label(planned,text=f"{row['date_retour']}  •  {row['heure_retour'] or '18:00'}",bg="#eef6fb",fg=NAVY,font=("Segoe UI",13,"bold")).pack(anchor="w",padx=14,pady=(0,9))

        fields=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); fields.pack(fill="x")
        fields.grid_columnconfigure(1,weight=1)
        date_var=tk.StringVar(value=datetime.now().strftime("%d/%m/%Y")); time_var=tk.StringVar(value=row['heure_retour'] or "18:00")
        tk.Label(fields,text="Date réelle du retour",bg=CARD,fg=TEXT,font=("Segoe UI",10,"bold")).grid(row=0,column=0,sticky="w",padx=14,pady=(14,8))
        date_entry=tk.Entry(fields,textvariable=date_var,font=("Segoe UI",11),relief="solid",bd=1); date_entry.grid(row=0,column=1,sticky="ew",padx=(8,46),pady=(14,8),ipady=7)
        cal=tk.Button(fields,text="▣",command=lambda:self.open_date_picker(date_var,date_entry),bg=BLUE,fg="white",relief="flat",font=("Segoe UI",11,"bold"),cursor="hand2")
        cal.grid(row=0,column=1,sticky="e",padx=10,pady=(14,8),ipadx=8,ipady=5)
        tk.Label(fields,text="Heure réelle",bg=CARD,fg=TEXT,font=("Segoe UI",10,"bold")).grid(row=1,column=0,sticky="w",padx=14,pady=(4,14))
        tk.Entry(fields,textvariable=time_var,font=("Segoe UI",11),relief="solid",bd=1,width=12).grid(row=1,column=1,sticky="w",padx=8,pady=(4,14),ipady=7)

        summary=tk.Frame(body,bg="#f8fbfd",highlightbackground=BORDER,highlightthickness=1); summary.pack(fill="x",pady=12)
        duration_var=tk.StringVar(value="—"); total_var=tk.StringVar(value="—"); deduct_var=tk.StringVar(value="—"); balance_var=tk.StringVar(value="—")
        items=(("Nouvelle durée",duration_var),("Nouveau montant",total_var),("À déduire du CA",deduct_var),("Nouveau reste",balance_var))
        for i,(lab,var) in enumerate(items):
            cell=tk.Frame(summary,bg="#f8fbfd"); cell.grid(row=i//2,column=i%2,sticky="nsew",padx=12,pady=8); summary.grid_columnconfigure(i%2,weight=1)
            tk.Label(cell,text=lab,bg="#f8fbfd",fg=MUTED,font=("Segoe UI",8,"bold")).pack(anchor="w")
            tk.Label(cell,textvariable=var,bg="#f8fbfd",fg=("#c0392b" if i==2 else NAVY),font=("Segoe UI",12,"bold")).pack(anchor="w")

        def calculate(show_error=False):
            parsed=self._parse_french_date(date_var.get().strip())
            if not parsed or parsed < start or parsed >= old:
                duration_var.set("Date invalide"); total_var.set("—"); deduct_var.set("—"); balance_var.set("—")
                if show_error: messagebox.showwarning("Retour anticipé","La date réelle doit être égale ou postérieure au départ et strictement antérieure au retour prévu.",parent=win)
                return None
            try:
                datetime.strptime(time_var.get().strip(),"%H:%M")
            except ValueError:
                if show_error: messagebox.showwarning("Retour anticipé","Heure invalide. Utilisez le format HH:MM.",parent=win)
                return None
            old_total=float(row['montant'] or 0); price=float(row['prix'] or 0); paid=float(row['reglement'] or 0)
            days=max(1,(parsed-start).days); new_total=round(price*days,2); deduction=round(max(0,old_total-new_total),2); balance=round(max(0,new_total-paid),2)
            duration_var.set(f"{days} jour(s)"); total_var.set(f"{new_total:,.2f} MAD"); deduct_var.set(f"-{deduction:,.2f} MAD"); balance_var.set(f"{balance:,.2f} MAD")
            return parsed,days,new_total,deduction,balance,round(max(0,paid-new_total),2)

        date_var.trace_add("write",lambda *_:calculate(False)); time_var.trace_add("write",lambda *_:calculate(False)); calculate(False)
        buttons=tk.Frame(body,bg=BG); buttons.pack(fill="x",pady=(4,0))
        tk.Button(buttons,text="✕  Annuler",command=win.destroy,bg="#e9eef2",fg=TEXT,activebackground="#dde5ea",relief="flat",font=("Segoe UI",11,"bold"),cursor="hand2",padx=20,pady=11).pack(side="left")
        def confirm():
            calc=calculate(True)
            if not calc:return
            parsed,days,new_total,deduction,balance,overpayment=calc; new_date=date_var.get().strip(); new_time=time_var.get().strip()
            old_total=float(row['montant'] or 0)
            self.conn.execute("""UPDATE contracts SET date_retour=?,heure_retour=?,duree=?,montant=?,reste=?, return_status='RETOUR ANTICIPÉ',actual_return_date=? WHERE numero=?""",(new_date,new_time,days,new_total,balance,new_date,contract_no))
            self._audit("RETOUR ANTICIPÉ","CONTRAT",contract_no,f"Retour {new_date} {new_time} | CA {old_total:.2f}->{new_total:.2f} | déduction {deduction:.2f} MAD")
            self.conn.commit(); self.refresh_alerts(); self.refresh_dashboard()
            if hasattr(self,"history_tree"): self.refresh_history()
            self.schedule_web_sync(); win.destroy()
            if alert_window and alert_window.winfo_exists(): alert_window.destroy()
            msg=f"Retour anticipé enregistré.\n\nMontant déduit du CA : {deduction:.2f} MAD\nNouveau CA de la location : {new_total:.2f} MAD"
            if overpayment>0: msg+=f"\nTrop-perçu à traiter : {overpayment:.2f} MAD"
            self._professional_notice("Retour anticipé",msg,"✓",GREEN)
            self.root.after(100,lambda:self._open_modified_contract_documents(contract_no,"RÉSILIATION ANTICIPÉE"))
        tk.Button(buttons,text="✓  Confirmer le retour anticipé",command=confirm,bg=GREEN,fg="white",activebackground=GREEN,activeforeground="white",relief="flat",font=("Segoe UI",11,"bold"),cursor="hand2",padx=22,pady=11).pack(side="right")
        win.protocol("WM_DELETE_WINDOW",win.destroy); date_entry.focus_set()

