    def _get_setting(self,key,default=""):
        row=self.conn.execute("SELECT setting_value FROM app_settings WHERE setting_key=?",(key,)).fetchone()
        return row[0] if row else default

    def _company_logo_path(self):
        """Logo configuré, ou logo HBZ fourni par défaut ; accepte les anciens chemins Windows."""
        configured=str(self._get_setting("logo_path","") or "").strip()
        candidates=[]
        if configured:
            filename=configured.replace("\\","/").rsplit("/",1)[-1]
            candidates.extend((Path(configured),APP_DIR/configured,APP_DIR/"assets"/filename))
        candidates.append(APP_DIR/"assets"/"HBZ_REN_CAR_LOGO.png")
        for path in candidates:
            if path.is_file():return path
        return candidates[-1]

    def _document_logo_uri(self):
        """Logo société commun à toutes les impressions, même après déplacement de l'installation."""
        path=self._company_logo_path()
        return html.escape(path.resolve().as_uri(),quote=True) if path.is_file() else ""

    def _print_logo_html(self):
        uri=self._document_logo_uri()
        return (f'<img src="{uri}" alt="Logo société" style="display:block;max-width:43mm;'
                'max-height:15mm;object-fit:contain;margin:0 0 2mm">') if uri else ""

    def _set_setting(self,key,value):
        self.conn.execute("INSERT INTO app_settings VALUES(?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value",(key,str(value)))

    def _apply_appearance_live_to_widgets(self, old_palette):
        """Répercute immédiatement la palette sur les widgets déjà affichés."""
        mapping = {
            old_palette.get("NAVY"): NAVY, old_palette.get("BLUE"): BLUE,
            old_palette.get("BG"): BG, old_palette.get("CARD"): CARD,
            old_palette.get("TEXT"): TEXT, old_palette.get("MUTED"): MUTED,
            old_palette.get("BORDER"): BORDER,
        }
        mapping = {k:v for k,v in mapping.items() if k and v}
        def walk(widget):
            for option in ("bg","background","fg","foreground","activebackground","activeforeground","highlightbackground"):
                try:
                    value=widget.cget(option)
                    if value in mapping: widget.configure(**{option:mapping[value]})
                except (tk.TclError, KeyError, TypeError):
                    pass
            for child in widget.winfo_children(): walk(child)
        walk(self.root)
        try: self.root.configure(bg=BG)
        except tk.TclError: pass
        try: self._build_styles()
        except Exception: pass
        self.root.update_idletasks()

    def save_appearance_settings(self):
        old_palette={"NAVY":NAVY,"BLUE":BLUE,"BG":BG,"CARD":CARD,"TEXT":TEXT,"MUTED":MUTED,"BORDER":BORDER}
        for key,var in zip(("language","font_size","theme","font_color","font_weight","ui_style"),self.settings_vars): self._set_setting(key,var.get())
        if hasattr(self,"table_color_vars"):
            for key,var in self.table_color_vars.items(): self._set_setting("table_color_"+key,var.get())
        self._audit("MODIFICATION","PARAMÈTRES","APPARENCE"); self.conn.commit()
        self._apply_saved_appearance()
        self._apply_appearance_live_to_widgets(old_palette)
        # Aucun redémarrage requis et aucun popup bloquant : le résultat est visible immédiatement.

    def apply_windows_startup_setting(self):
        enabled=self.windows_startup_var.get()=="ACTIVÉ"
        if not sys.platform.startswith("win"):
            messagebox.showwarning("Démarrage Windows","Cette option est disponible uniquement sous Windows.");return
        script=APP_DIR/("ACTIVER_DEMARRAGE_WINDOWS.bat" if enabled else "DESACTIVER_DEMARRAGE_WINDOWS.bat")
        if not script.exists():messagebox.showerror("Démarrage Windows",f"Fichier système introuvable : {script.name}");return
        try:
            result=subprocess.run(["cmd.exe","/c",str(script),"/silent"],cwd=str(APP_DIR),capture_output=True,text=True)
            if result.returncode:raise RuntimeError(result.stderr.strip() or result.stdout.strip() or "Erreur Windows")
            self._set_setting("windows_startup","ACTIVÉ" if enabled else "DÉSACTIVÉ");self.conn.commit()
            state="activé" if enabled else "désactivé"
            messagebox.showinfo("Démarrage Windows",f"Le démarrage automatique est {state}.")
        except (OSError,RuntimeError) as exc:messagebox.showerror("Démarrage Windows",f"Modification impossible :\n{exc}")

    def save_company_settings(self):
        if not self.company_vars["company_name"].get().strip(): messagebox.showwarning("Société","Le nom commercial est obligatoire."); return
        for key,var in self.company_vars.items(): self._set_setting(key,var.get().strip())
        self._set_setting("general_conditions",self.general_conditions.get("1.0","end-1c").strip())
        self._set_setting("general_conditions_ar",self.general_conditions_ar.get("1.0","end-1c").strip())
        if hasattr(self,"logo_path_var") and self.logo_path_var.get().strip() and Path(self.logo_path_var.get()).exists():
            self._set_setting("logo_path",self.logo_path_var.get().strip())
        self._audit("MODIFICATION","PARAMÈTRES","SOCIÉTÉ"); self.conn.commit()
        self._apply_company_settings_live()
        messagebox.showinfo("Paramètres","Informations société, logo et conditions enregistrés et appliqués immédiatement.")

    def _apply_company_settings_live(self):
        """Actualise l'identité de l'application sans imposer un redémarrage."""
        company=self._get_setting("company_name","HBZ Rent Car")
        self.root.title(f"GestionPro — {company} — {BUILD_ID}")
        self._refresh_settings_logo_preview()
        if not hasattr(self,"app_logo_label"):return
