        tk.Label(head,text="⚠  GESTION DES INFRACTIONS",bg=NAVY,fg="white",font=("Segoe UI",17,"bold")).pack(side="left",padx=22,pady=15)
        tk.Label(head,text="Clients • Locations • Documents • Suivi financier",bg=NAVY,fg="#d9efff",font=("Segoe UI",9)).pack(side="left",padx=8)

