        tk.Label(filters,text="MOIS",bg=CARD,fg=TEXT,font=("Segoe UI",8,"bold")).grid(row=0,column=2,padx=(12,4)); cb_month=ttk.Combobox(filters,textvariable=month_filter,values=["Tous"]+[f"{i:02d}" for i in range(1,13)],width=8,state="readonly"); cb_month.grid(row=0,column=3,padx=4)
        years=set()
        for rr in self.conn.execute("SELECT date_depart FROM contracts WHERE date_depart IS NOT NULL"):
            import re as _re
            m=_re.search(r'(20\d{2}|19\d{2})',str(rr[0] or ''))
            if m: years.add(m.group(1))
        tk.Label(filters,text="ANNÉE",bg=CARD,fg=TEXT,font=("Segoe UI",8,"bold")).grid(row=0,column=4,padx=(12,4)); cb_year=ttk.Combobox(filters,textvariable=year_filter,values=["Toutes"]+sorted(years,reverse=True),width=9,state="readonly"); cb_year.grid(row=0,column=5,padx=4)
        tk.Label(filters,text="RECHERCHE",bg=CARD,fg=TEXT,font=("Segoe UI",8,"bold")).grid(row=0,column=6,padx=(12,4)); ttk.Entry(filters,textvariable=search_var,width=26).grid(row=0,column=7,padx=4)

        total_client=tk.StringVar(value="Cumul client : 0,00"); selected_info=tk.StringVar(value="Sélectionnez une location")
        tk.Label(filters,text="Client sélectionnable • cliquez aussi une location pour rattacher le contrat",bg=CARD,fg=MUTED,font=("Segoe UI",8,"italic"),padx=8).grid(row=0,column=8,padx=8)

        body=tk.PanedWindow(win,orient="vertical",bg=BG,sashwidth=5); body.pack(fill="both",expand=True,padx=16,pady=(0,8))
        upper=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); lower=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); body.add(upper,minsize=210); body.add(lower,minsize=250)

        # Locations concernées
        tk.Label(upper,text="LOCATIONS / PÉRIODES DE RESPONSABILITÉ",bg=CARD,fg=NAVY,font=("Segoe UI",10,"bold")).pack(anchor="w",padx=12,pady=(9,4))
        cols=("contrat","code","nom","prenom","vehicule","immat","depart","hdepart","retour","hretour")
        labels=("CONTRAT","CODE","NOM","PRÉNOM","VÉHICULE","IMMATR.","DATE DÉPART","HEURE","DATE RETOUR","HEURE")
        tree=ttk.Treeview(upper,columns=cols,show="headings",height=7); [tree.heading(c,text=l) for c,l in zip(cols,labels)]
