        ttk.Combobox(search_bar,textvariable=search_mode,values=("Code client","CIN / Passeport","Nom","Prénom","Téléphone"),state="readonly",width=17,style="GP.TCombobox").grid(row=0,column=1,sticky="ew",padx=5,pady=8,ipady=2)
        search_entry=ttk.Entry(search_bar,textvariable=search_value,style="GP.TEntry")
