        tk.Button(photo_buttons,text="Scan",command=scan_client,bg=colors["green"],fg="white",font=("Segoe UI",7,"bold"),padx=5,pady=3).pack(side="left",fill="x",expand=True,padx=(2,0))
        faces=tk.Frame(photo_body,bg="white");faces.pack(fill="x",pady=(5,0));ui["front_images"]={}
