        add_fields(identity,(("CIN / Passeport","cin"),("Nom *","nom"),("Prénom *","prenom"),("Date naissance","date_naissance"),("Âge","age")))
        add_fields(contact,(("Téléphone *","telephone"),("Ville","ville"),("Adresse","adresse")))
        add_fields(permit,(("N° permis *","permis"),("Date délivrance","date_permis"),("Ancienneté","permis_age"),("Catégorie","categorie"),("Validité","validite_permis")))

        # 5 — Résultats toujours visibles, même sur un écran portable.
